Matching Ayahs
- = ಅಲಿಫ್, ಲಾಮ್, ಮೀಮ್. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = ಅವರೇ ತಮ್ಮ ಒಡೆಯನ ಕಡೆಯಿಂದ ಸನ್ಮಾರ್ಗದಲ್ಲಿರುವವರು ಮತ್ತು ಅವರೇ ಯಶಸ್ವಿಗಳು. 2:5; 31:5
- = ಓ ಇಸ್ರಾಈಲ್ ಸಂತತಿಯವರೇ! ನಾನು ನಿಮಗೆ ಅನುಗ್ರಹಿಸಿದ ನನ್ನ ಅನುಗ್ರಹವನ್ನು ಮತ್ತು ನಾನು ನಿಮ್ಮನ್ನು ಸಮಸ್ತ ಲೋಕಗಳ (ಜನಾಂಗಗಳ) ಮೇಲೆ ಶ್ರೇಷ್ಠರನ್ನಾಗಿ ಮಾಡಿದ್ದನ್ನು ಸ್ಮರಿಸಿರಿ. 2:47; 2:122
- = ಅದು ಒಂದು ಸಮುದಾಯವಾಗಿತ್ತು, ಅದು ಕಳೆದುಹೋಯಿತು. ಅದು ಗಳಿಸಿದ್ದು ಅದಕ್ಕೆ, ಮತ್ತು ನೀವು ಗಳಿಸಿದ್ದು ನಿಮಗೆ. ಮತ್ತು ಅವರು ಏನು ಮಾಡುತ್ತಿದ್ದರೆಂದು ನಿಮ್ಮನ್ನು ಕೇಳಲಾಗುವುದಿಲ್ಲ. 2:134; 2:141
- = ಅವರು ಅದರಲ್ಲಿ ಸದಾಕಾಲ ಇರುವರು. ಅವರ ಶಿಕ್ಷೆಯನ್ನು ಇಳಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ಅವರಿಗೆ ಅವಕಾಶವನ್ನೂ ನೀಡಲಾಗುವುದಿಲ್ಲ. 2:162; 3:88
- = ಆದರೆ ಆ ನಂತರ ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟು ತಮ್ಮನ್ನು ಸುಧಾರಿಸಿಕೊಳ್ಳುವವರ ಹೊರತು. ನಿಶ್ಚಯವಾಗಿ ಅಲ್ಲಾಹು ಕ್ಷಮಾಶೀಲನೂ ಅಪಾರ ಕರುಣಾಳುವೂ ಆಗಿದ್ದಾನೆ. 3:89; 24:5
- = ಆದರೆ ಧಿಕ್ಕರಿಸಿದವರು ಮತ್ತು ನಮ್ಮ ವಚನಗಳನ್ನು ಸುಳ್ಳೆಂದು ತಿರಸ್ಕರಿಸಿದವರು – ಅವರೇ ನರಕದವರು. 5:10; 5:86
- = ಮತ್ತು ಅವರ ಒಡೆಯನ ಕಡೆಯಿಂದ ಅವರ ಬಳಿಗೆ ಯಾವುದೇ ಸೂಚನೆ ಬಂದರೂ, ಅವರು ಅದರಿಂದ ಮುಖ ತಿರುಗಿಸಿಕೊಳ್ಳುತ್ತಾರೆ. 6:4; 36:46
- = ಮತ್ತು ನಿಮಗಿಂತ ಮುಂಚೆಯೂ ಸಂದೇಶವಾಹಕರನ್ನು ಅಪಹಾಸ್ಯ ಮಾಡಲಾಗಿತ್ತು, ಆದರೆ ಅಪಹಾಸ್ಯ ಮಾಡುತ್ತಿದ್ದವರನ್ನು, ಅವರು ಅಪಹಾಸ್ಯ ಮಾಡುತ್ತಿದ್ದ ವಿಷಯವೇ ಸುತ್ತುವರೆದುಕೊಂಡಿತು. 6:10; 21:41
- = ಹೇಳಿರಿ: "ನಾನು ನನ್ನ ಒಡೆಯನನ್ನು ಅವಿಧೇಯನಾದರೆ, ಮಹಾದಿನದ ಶಿಕ್ಷೆಗೆ ಹೆದರುವೆನು." 6:15; 39:13
- = ಆಗ ಭೂಕಂಪವು ಅವರನ್ನು ಆವರಿಸಿತು, ಮತ್ತು ಅವರು ತಮ್ಮ ಮನೆಗಳಲ್ಲಿ ಬೋರಲು ಬಿದ್ದು ಸತ್ತರು. 7:78; 7:91
- = ಆಗ ಅವನು ತನ್ನ ಕೋಲನ್ನು ಎಸೆದನು, ಇದ್ದಕ್ಕಿದ್ದಂತೆ ಅದು ಸ್ಪಷ್ಟವಾದ ಹಾವಾಯಿತು. 7:107; 26:32
- = ಮತ್ತು ಅವನು ತನ್ನ ಕೈಯನ್ನು ಹೊರಗೆ ತೆಗೆದನು, ಆಗ ಅದು ನೋಡುವವರಿಗೆ ಬೆಳ್ಳಗೆ (ಹೊಳೆಯುತ್ತಾ) ಕಂಡಿತು. 7:108; 26:33
- = ಅವರು ಹೇಳಿದರು: "ನಾವು ಸರ್ವಲೋಕಗಳ ಒಡೆಯನನ್ನು ನಂಬಿದೆವು." 7:121; 26:47
- = ಮೂಸಾ ಮತ್ತು ಹಾರೂನರ ಒಡೆಯ. 7:122; 26:48
- = ಮತ್ತು ನಾನು ಅವರಿಗೆ ಅವಕಾಶ ನೀಡುವೆನು. ನಿಶ್ಚಯವಾಗಿ ನನ್ನ ಯೋಜನೆ ಗಟ್ಟಿಯಾಗಿದೆ. 7:183; 68:45
- = ಅವನೇ ತನ್ನ ಸಂದೇಶವಾಹಕನನ್ನು ಸನ್ಮಾರ್ಗ ಮತ್ತು ಸತ್ಯ ಧರ್ಮದೊಂದಿಗೆ ಕಳುಹಿಸಿದನು – ಅದನ್ನು ಎಲ್ಲಾ ಧರ್ಮಗಳ ಮೇಲೆ ಪ್ರಬಲಗೊಳಿಸಲು, ಬಹುದೇವಾರಾಧಕರು ಅದನ್ನು ಅಸಹ್ಯಿಸಿದರೂ. 9:33; 61:9
- = ಓ ಪ್ರವಕ್ತರೇ! ಧಿಕ್ಕಾರಿಗಳು ಮತ್ತು ಕಪಟಿಗಳ ವಿರುದ್ಧ ಹೋರಾಡಿರಿ ಮತ್ತು ಅವರ ಬಗ್ಗೆ ಕಠಿಣರಾಗಿರಿ. ಅವರ ಆಶ್ರಯ ನರಕವಾಗಿದೆ, ಮತ್ತು ಅದು ಎಷ್ಟು ಕೆಟ್ಟ ಗಮ್ಯಸ್ಥಾನ! 9:73; 66:9
- = ಮತ್ತು ಅವರು ಹೇಳುತ್ತಾರೆ: "ನೀವು ಸತ್ಯವಂತರಾಗಿದ್ದರೆ, ಈ ವಾಗ್ದಾನವು ಯಾವಾಗ?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ಮತ್ತು ನಾವು ಮೂಸಾರನ್ನು ನಮ್ಮ ಸೂಚನೆಗಳು ಮತ್ತು ಸ್ಪಷ್ಟ ಅಧಿಕಾರದೊಂದಿಗೆ ಕಳುಹಿಸಿದ್ದೆವು. 11:96; 40:23
- = ಮತ್ತು ನಾವು ಮೂಸಾರಿಗೆ ಗ್ರಂಥವನ್ನು ನೀಡಿದೆವು, ಆದರೆ ಅದರಲ್ಲಿ ಭಿನ್ನಾಭಿಪ್ರಾಯವುಂಟಾಯಿತು. ಮತ್ತು ನಿಮ್ಮ ಒಡೆಯನಿಂದ ಒಂದು ಮಾತು ಮುಂಚಿತವಾಗಿ ಇಲ್ಲದಿದ್ದರೆ, ಅವರ ನಡುವೆ ತೀರ್ಪು ನೀಡಲಾಗುತ್ತಿತ್ತು. ಮತ್ತು ನಿಶ್ಚಯವಾಗಿ ಅವರು ಅದರ ಬಗ್ಗೆ ಸಂದೇಹದಲ್ಲಿದ್ದಾರೆ. 11:110; 41:45
- = ಅದು ಅಲ್ಲಾಹನಿಗೆ ಕಷ್ಟಕರವಲ್ಲ. 14:20; 35:17
