- ನಿಮ್ಮ ಒಡೆಯನಿಂದ, ನೀವು ಆ ಜನಾಂಗವನ್ನು ಎಚ್ಚರಿಸಲು, ಅವರ ಬಳಿಗೆ ನಿಮ್ಮ ಮೊದಲು ಯಾವುದೇ ಎಚ್ಚರಿಕೆ ನೀಡುವವನು ಬಂದಿರಲಿಲ್ಲ, ಅವರು... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- ಓ ಪ್ರವಾದಿಯೇ! ಧಿಕ್ಕಾರಿಗಳು ಮತ್ತು ಕಪಟಿಗಳ ವಿರುದ್ಧ ಹೋರಾಡಿರಿ ಮತ್ತು ಅವರ ಮೇಲೆ ಕಠಿಣರಾಗಿರಿ. ಅವರ ನೆಲೆಯು ನರಕವಾಗಿದೆ, ಮತ್ತು ಅದು ಎಷ್ಟು ಕೆಟ್ಟ ನೆಲೆಯಾಗಿದೆ! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- ನಿಶ್ಚಯವಾಗಿ, ನಿಮ್ಮ ಒಡೆಯನು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಅವರ ನಡುವೆ, ಅವರು ಭಿನ್ನಾಭಿಪ್ರಾಯ ಹೊಂದಿದ್ದ ವಿಷಯಗಳ ಬಗ್ಗೆ ತೀರ್ಪು ನೀಡುವನು. (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- ಅವರು ಹೇಳಿದರು: "ಓ ನನ್ನ ಒಡೆಯನೇ! ನನಗೆ ಒಂದು ಸೂಚನೆಯನ್ನು ನೀಡು." ಅವನು ಹೇಳಿದನು: "ನಿಮ್ಮ ಸೂಚನೆಯೆಂದರೆ, ನೀವು ಜನರೊಂದಿಗೆ ಮಾತನಾಡುವುದಿಲ್ಲ..." (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- ಆದ್ದರಿಂದ, ನಿಮ್ಮ ಮುಖವನ್ನು ಮಸ್ಜಿದುಲ್ ಹರಾಮ್ ಕಡೆಗೆ ತಿರುಗಿಸಿರಿ. ಮತ್ತು ನೀವು ಎಲ್ಲಿದ್ದರೂ, ನಿಮ್ಮ ಮುಖಗಳನ್ನು ಅದರ ಕಡೆಗೆ ತಿರುಗಿಸಿರಿ. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- ಓ ಇಸ್ರಾಈಲರ ಮಕ್ಕಳೇ! ನಾನು ನಿಮಗೆ ಅನುಗ್ರಹಿಸಿದ ನನ್ನ ಅನುಗ್ರಹವನ್ನು ಮತ್ತು ನಾನು ನಿಮ್ಮನ್ನು ಸಮಸ್ತ ಲೋಕಗಳಿಗಿಂತ ಶ್ರೇಷ್ಠರನ್ನಾಗಿ ಮಾಡಿದ್ದನ್ನು ಸ್ಮರಿಸಿರಿ. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
