- ಮತ್ತು ಪ್ರತಿಯೊಂದು ಸಮುದಾಯಕ್ಕೂ ಒಂದು ನಿಗದಿತ ಅವಧಿಯಿದೆ; ಆದ್ದರಿಂದ ಅವರ ಅವಧಿಯು ಬಂದಾಗ, ಅವರು ಒಂದು ಗಳಿಗೆಯೂ ಹಿಂದಿರುಗಲಾರರು, ಮತ್ತು ಮುಂದೂ ಹೋಗಲಾರರು. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (ಅಲ್ಲಾಹನ ಹೊರತು) ಬೇರೆಯವರ ಹೆಸರಿನಲ್ಲಿ ವಧಿಸಲ್ಪಟ್ಟದ್ದು. ಆದರೆ ಯಾರಾದರೂ ಬಲವಂತಕ್ಕೊಳಗಾದರೆ, ಅತಿಕ್ರಮಿಯಾಗಿಯೂ, ಮಿತಿಮೀರಿದವನಾಗಿಯೂ ಅಲ್ಲದಿದ್ದರೆ, ಆಗ... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- ಮತ್ತು ಅವರಿಗೆ "ಅಲ್ಲಾಹನು ಇಳಿಸಿದ್ದನ್ನು ಅನುಸರಿಸಿರಿ" ಎಂದು ಹೇಳಲಾದಾಗ, ಅವರು ಹೇಳುತ್ತಾರೆ: "ಇಲ್ಲ, ನಾವು ನಮ್ಮ ಪೂರ್ವಜರು ಯಾವುದರ ಮೇಲೆ ಇದ್ದರೋ ಅದನ್ನು ಅನುಸರಿಸುತ್ತೇವೆ." (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- ಅವರು ಹೇಳಿದರು: "ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ಅಲ್ಲಾಹನನ್ನು ಆರಾಧಿಸಿರಿ; ಅವನ ಹೊರತು ನಿಮಗೆ ಯಾವುದೇ ದೇವರು ಇಲ್ಲ. ನೀವು (ಅಲ್ಲಾಹನಿಗೆ) ಹೆದರುವುದಿಲ್ಲವೇ?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
