- ಸತ್ಯವನ್ನು ನಂಬಿ ಮತ್ತು ಸತ್ಕರ್ಮಗಳನ್ನು ಮಾಡಿದವರನ್ನು ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ಸ್ವರ್ಗದ ತೋಟಗಳಿಗೆ ಸೇರಿಸಲಾಯಿತು. (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- ಅವನು ಹೇಳಿದನು: "ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ಅಲ್ಲಾಹನನ್ನು ಆರಾಧಿಸಿರಿ, ಆತನ ಹೊರತಾಗಿ ನಿಮಗೆ ಯಾವುದೇ ದೇವರು ಇಲ್ಲ, ನೀವೇನು ಭಯಪಡುವುದಿಲ್ಲವೇ?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- ಅವರ ಸಂಪತ್ತು ಮತ್ತು ಅವರ ಸಂತಾನವು ಅಲ್ಲಾಹನ ಬಳಿ ಅವರಿಗೆ ಯಾವುದೇ ಪ್ರಯೋಜನವನ್ನು ನೀಡುವುದಿಲ್ಲ, ಮತ್ತು ಅವರೇ ಆಗಿದ್ದಾರೆ. (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ತೋಟಗಳು, ಅವುಗಳಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು, ಮತ್ತು ಅದು ಮಹಾನ್ ವಿಜಯವಾಗಿದೆ. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- ತಮ್ಮ ಹಿಂದಿನವರ ಸುದ್ದಿ, ನೂಹ್, ಆದ್ ಮತ್ತು ಸಮೂದ್ ಜನಾಂಗಗಳ ಸುದ್ದಿಯು ಅವರಿಗೆ ಬರಲಿಲ್ಲವೇ? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- ಅಲ್ಲಾಹನ ಮಾರ್ಗದಲ್ಲಿ ನನ್ನ ಸಹಾಯಕರು ಯಾರು? ಶಿಷ್ಯರು ಹೇಳಿದರು: "ನಾವು ಅಲ್ಲಾಹನ ಸಹಾಯಕರು, ನಾವು ಸತ್ಯವನ್ನು ನಂಬಿದೆವು." (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- ನಿನ್ನ ಒಡೆಯನು ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪಿದನೆಂದು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು, ಮತ್ತು ಸನ್ಮಾರ್ಗ ಪಡೆದವರನ್ನು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- ಇದು ಏಕೆಂದರೆ ಅಲ್ಲಾಹನೇ ಸತ್ಯ, ಮತ್ತು ಅವರು ಆತನ ಹೊರತಾಗಿ ಪ್ರಾರ್ಥಿಸುವುದು ಅಸತ್ಯ. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- ಅಲ್ಲಾಹನ ಮತ್ತು ಆತನ ಪ್ರವಕ್ತರ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸುವವನನ್ನು ಅಲ್ಲಾಹನು ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ಸ್ವರ್ಗದ ತೋಟಗಳಿಗೆ ಸೇರಿಸುವನು. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- ಅವನು ನಿಮ್ಮ ಮೇಲೆ ಸತ್ತ ಪ್ರಾಣಿ, ರಕ್ತ, ಹಂದಿಯ ಮಾಂಸ ಮತ್ತು ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆಯವರ ಹೆಸರಿನಲ್ಲಿ ವಧಿಸಲ್ಪಟ್ಟದ್ದನ್ನು ಮಾತ್ರ ನಿಷೇಧಿಸಿದ್ದಾನೆ. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ಅಲ್ಲಾಹನ ಹೊರತು ಯಾರನ್ನೂ ಪೂಜಿಸಬೇಡಿರಿ; ನಾನು ನಿಮಗಾಗಿ ಮಹಾನ್ ದಿನದ ಶಿಕ್ಷೆಯ ಭಯಪಡುತ್ತೇನೆ. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- ಇದು ಗುಪ್ತ ವಿಷಯಗಳ ಸುದ್ದಿಗಳಲ್ಲಿ ಒಂದಾಗಿದೆ, ಅದನ್ನು ನಾವು ನಿನಗೆ ದಿವ್ಯವಾಣಿಯಾಗಿ ಕಳುಹಿಸುತ್ತೇವೆ; ಅವರು ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುತ್ತಿದ್ದಾಗ ನೀನು ಅವರ ಬಳಿ ಇರಲಿಲ್ಲ. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ನಿಮ್ಮೊಳಗಿನ ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಮೂಲಕ ನಿಮ್ಮ ಒಡೆಯನ ಕಡೆಯಿಂದ ಉಪದೇಶವು ಬಂದಿದೆಯೆಂದು ನೀವು ಆಶ್ಚರ್ಯ ಪಡುತ್ತೀರಾ, ಅವನು ನಿಮ್ಮನ್ನು ಎಚ್ಚರಿಸಲು? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- ಹೇಳು: "ನಿಶ್ಚಯವಾಗಿಯೂ ನಾನು ಅಲ್ಲಾಹನ ಹೊರತಾಗಿ ನೀವು ಪ್ರಾರ್ಥಿಸುವವರನ್ನು ಪೂಜಿಸುವುದನ್ನು ನಿಷೇಧಿಸಲ್ಪಟ್ಟಿದ್ದೇನೆ." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- ಅವರ ಪತ್ನಿಯರು ಅಥವಾ ಅವರ ಬಲಗೈಗಳು ಒಡೆದುಕೊಂಡವರ ಹೊರತಾಗಿ, ಏಕೆಂದರೆ ಅವರು ನಿಂದೆಗೊಳಗಾಗುವವರಲ್ಲ. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ಏಕೆಂದರೆ ಅಲ್ಲಾಹನು ರಾತ್ರಿಯನ್ನು ಹಗಲಿನೊಳಗೆ ಸೇರಿಸುತ್ತಾನೆ ಮತ್ತು ಹಗಲನ್ನು ರಾತ್ರಿಯೊಳಗೆ ಸೇರಿಸುತ್ತಾನೆ. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ಬೆಂಕಿ, ಮತ್ತು ಅವನು ತನ್ನ ಕುಟುಂಬದವರಿಗೆ ಹೇಳಿದನು: "ನಿಲ್ಲಿರಿ, ನಾನು ಬೆಂಕಿಯನ್ನು ನೋಡಿದೆ, ಬಹುಶಃ ನಾನು ಅದರಿಂದ ನಿಮಗೆ ಏನನ್ನಾದರೂ ತರಬಹುದು." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- ಅವನು ಹೇಳಿದನು: "ನಾನು ಅವನಿಗಿಂತ ಉತ್ತಮನು; ನೀನು ನನ್ನನ್ನು ಬೆಂಕಿಯಿಂದ ಸೃಷ್ಟಿಸಿದೆ, ಮತ್ತು ಅವನನ್ನು ಮಣ್ಣಿನಿಂದ ಸೃಷ್ಟಿಸಿದೆ." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ಮತ್ತು ಅವರಿಗೆ ಹೇಳಲಾದಾಗ: "ಅಲ್ಲಾಹನು ಇಳಿಸಿದ್ದರ ಕಡೆಗೆ ಮತ್ತು ಪ್ರವಕ್ತರ ಕಡೆಗೆ ಬನ್ನಿರಿ." (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- ಮತ್ತು ನೀನು ಅವರಿಗಾಗಿ ದುಃಖಪಡಬೇಡ, ಮತ್ತು ಅವರ ಪಿತೂರಿಗಳಿಂದ ಸಂಕಟಪಡಬೇಡ. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- ಅಲ್ಲಾಹನು ನಿನಗೆ ಕೇಡನ್ನು ತಟ್ಟಿದರೆ, ಆತನ ಹೊರತು ಬೇರಾರೂ ಅದನ್ನು ನಿವಾರಿಸಲಾರರು, ಮತ್ತು ಒಂದು ವೇಳೆ. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ಅವರ ಹಿಂದೆ ಅನೇಕ ತಲೆಮಾರುಗಳು, ಅವರು ತಮ್ಮ ವಾಸಸ್ಥಾನಗಳಲ್ಲಿ ಸಂಚರಿಸುತ್ತಿದ್ದರು; ನಿಶ್ಚಯವಾಗಿಯೂ ಇದರಲ್ಲಿ ಸೂಚನೆಗಳಿವೆ. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ಮತ್ತು ನಾವು ಅವರ ಹೃದಯಗಳ ಮೇಲೆ ಪೊರೆಗಳನ್ನು ಹಾಕಿದೆವು ಇದರಿಂದ ಅವರು ಅದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳದಿರಲಿ, ಮತ್ತು ಅವರ ಕಿವಿಗಳಲ್ಲಿ ತಡೆ, ಮತ್ತು ಅವರು. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- ಅವರ ಪ್ರವಕ್ತರು ಸ್ಪಷ್ಟ ಪುರಾವೆಗಳೊಂದಿಗೆ ಅವರ ಬಳಿಗೆ ಬಂದರು, ಆದರೆ ಅಲ್ಲಾಹನು ಅವರ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡುವವನಲ್ಲ, ಆದರೆ ಅವರೇ ತಮ್ಮ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡಿಕೊಳ್ಳುತ್ತಿದ್ದರು. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ಮತ್ತು ಭೂಮಿಯಲ್ಲಿ, ಮತ್ತು ಅಲ್ಲಾಹನ ಹೊರತಾಗಿ ನಿಮಗೆ ಯಾವುದೇ ರಕ್ಷಕನಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಸಹಾಯಕನಿಲ್ಲ. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ನಂತರ ನಿಮ್ಮನ್ನು ಗುಪ್ತ ಮತ್ತು ವ್ಯಕ್ತವಾದವುಗಳ ಜ್ಞಾನಿಯ ಬಳಿಗೆ ಮರಳಿಸಲಾಗುವುದು, ಮತ್ತು ಅವನು ನೀವು ಮಾಡುತ್ತಿದ್ದುದನ್ನು ನಿಮಗೆ ತಿಳಿಸುವನು. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ರಾತ್ರಿ, ನೀವು ಅದರಲ್ಲಿ ವಿಶ್ರಾಂತಿ ಪಡೆಯಲು, ಮತ್ತು ಹಗಲು, ನೀವು ನೋಡಲು; ನಿಶ್ಚಯವಾಗಿಯೂ ಇದರಲ್ಲಿ ಚಿಂತನೆ ಮಾಡುವ ಜನರಿಗೆ ಸೂಚನೆಗಳಿವೆ. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- ಮತ್ತು ನಿನ್ನ ಒಡೆಯನ ಕಡೆಯಿಂದ ನಿನಗೆ ಇಳಿಸಲ್ಪಟ್ಟದ್ದು ಅವರಲ್ಲಿ ಹಲವರಿಗೆ ದಂಗೆ ಮತ್ತು ಅವಿಶ್ವಾಸವನ್ನು ಮತ್ತಷ್ಟು ಹೆಚ್ಚಿಸುವುದು. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- ಅವನು ಹೇಳಿದನು: "ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ನೀವು ಹೇಳಿರಿ, ನಾನು ನನ್ನ ಒಡೆಯನ ಕಡೆಯಿಂದ ಸ್ಪಷ್ಟವಾದ ಪುರಾವೆಯ ಮೇಲಿದ್ದು ಆತನು ನನಗೆ ಕೊಟ್ಟಿದ್ದರೆ." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
