- ಅಲ್ಲಾಹನು ಒಂದು ಕಾರ್ಯವನ್ನು ನಿರ್ಧರಿಸಿದಾಗ, ಅವನು ಅದಕ್ಕೆ "ಆಗು" ಎಂದು ಹೇಳುತ್ತಾನೆ, ಮತ್ತು ಅದು ಆಗುತ್ತದೆ. (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
