- ನಾನು ಅವರ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸುವೆನು ಮತ್ತು ಅವರನ್ನು ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ಸ್ವರ್ಗದ ತೋಟಗಳಿಗೆ ಸೇರಿಸುವೆನು. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- ನಾವು ಅವರನ್ನು ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ತೋಟಗಳಿಗೆ ಸೇರಿಸುವೆವು, ಅವುಗಳಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- ನಿನ್ನ ಒಡೆಯನು ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪಿದನೆಂದು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು, ಮತ್ತು ಅವನು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- ನಿಮ್ಮನ್ನು ಗುಪ್ತ ಮತ್ತು ವ್ಯಕ್ತವಾದವುಗಳ ಜ್ಞಾನಿಯ ಬಳಿಗೆ ಮರಳಿಸಲಾಗುವುದು, ಮತ್ತು ಅವನು ನೀವು ಮಾಡುತ್ತಿದ್ದುದನ್ನು ನಿಮಗೆ ತಿಳಿಸುವನು. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- ಅವರು ನಿಮ್ಮ ಪುತ್ರರನ್ನು ಕೊಂದರು ಮತ್ತು ನಿಮ್ಮ ಸ್ತ್ರೀಯರನ್ನು ಜೀವಂತವಾಗಿ ಬಿಟ್ಟರು; ಇದರಲ್ಲಿ ನಿಮ್ಮ ಒಡೆಯನ ಕಡೆಯಿಂದ ಒಂದು ಮಹಾನ್ ಪರೀಕ್ಷೆಯಿತ್ತು. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- ನಿಶ್ಚಯವಾಗಿಯೂ, ನಿನ್ನ ಒಡೆಯನು ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪುತ್ತಾನೆಂದು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು, ಮತ್ತು ಅವನು. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- ಅಲ್ಲಾಹನು, ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವ ಎಲ್ಲವನ್ನೂ ಹೊಂದಿದವನು. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- ನಿಮ್ಮ ಹಿಂದಿನ ಜನಾಂಗಗಳಲ್ಲಿ, ಜಿನ್ನ್ ಮತ್ತು ಮಾನವರಲ್ಲಿ. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- ಅಲ್ಲಾಹನನ್ನು ಆರಾಧಿಸಿರಿ, ಆತನ ಹೊರತಾಗಿ ನಿಮಗೆ ಯಾವುದೇ ದೇವರು ಇಲ್ಲ, ನೀವೇನು ಭಯಪಡುವುದಿಲ್ಲವೇ? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- ಮತ್ತು ನಾವು ಅವರ ಹೃದಯಗಳ ಮೇಲೆ ಪೊರೆಗಳನ್ನು ಹಾಕಿದೆವು ಇದರಿಂದ ಅವರು ಅದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳದಿರಲಿ, ಮತ್ತು ಅವರ ಕಿವಿಗಳಲ್ಲಿ ತಡೆ. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- ಅವನು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಅವರು ಭಿನ್ನಾಭಿಪ್ರಾಯ ಹೊಂದಿದ್ದ ವಿಷಯಗಳಲ್ಲಿ ಅವರ ನಡುವೆ ತೀರ್ಪು ನೀಡುವನು. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ಅವನು ಹೇಳಿದನು: "ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ನೀವು ಹೇಳಿರಿ, ನಾನು ನನ್ನ ಒಡೆಯನ ಕಡೆಯಿಂದ ಸ್ಪಷ್ಟವಾದ ಪುರಾವೆಯ ಮೇಲಿದ್ದರೆ?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- ಇದು ನಿಮ್ಮ ಕೈಗಳು ಮುಂದೆ ಕಳುಹಿಸಿದುದರ ಫಲವಾಗಿದೆ, ಮತ್ತು ಅಲ್ಲಾಹನು ತನ್ನ ದಾಸರ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡುವವನಲ್ಲ. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- ಅವರಿಗೆ ಇಹಲೋಕದಲ್ಲಿ ಅಪಮಾನವಿದೆ, ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಮಹಾನ್ ಶಿಕ್ಷೆಯಿದೆ. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವ ಎಲ್ಲವೂ ಅಲ್ಲಾಹನದೇ, ಮತ್ತು ಅಲ್ಲಾಹನೇ ರಕ್ಷಕನಾಗಿ ಸಾಕು. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- ಸತ್ಯವನ್ನು ನಂಬಿ ಸತ್ಕರ್ಮಗಳನ್ನು ಮಾಡಿದವರ ಹೊರತು; ಅವರಿಗೆ ಎಂದಿಗೂ ಕಡಿತವಾಗದ ಪ್ರತಿಫಲವಿದೆ. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ನೀನು ನನಗೆ ತಿಳಿದಿಲ್ಲದುದನ್ನು ಪಾಲುದಾರನನ್ನಾಗಿ ಮಾಡಬಾರದು; ಅವರ ಮಾತನ್ನು ಕೇಳಬೇಡ. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- ನಿಶ್ಚಯವಾಗಿಯೂ, ಇದು ಒಂದು ಉಪದೇಶವಾಗಿದೆ; ಆದ್ದರಿಂದ ಇಚ್ಛಿಸುವವನು ತನ್ನ ಒಡೆಯನ ಕಡೆಗೆ ಮಾರ್ಗವನ್ನು ತೆಗೆದುಕೊಳ್ಳಲಿ. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ಮತ್ತು ಕೃತಜ್ಞನಾಗುವವನು ತನಗಾಗಿಯೇ ಕೃತಜ್ಞನಾಗುತ್ತಾನೆ; ಮತ್ತು ಕೃತಜ್ಞನಲ್ಲದವನು. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ನಮಾಜ್ ಅನ್ನು ಸ್ಥಾಪಿಸುವವರು, ಝಕಾತ್ ಅನ್ನು ನೀಡುವವರು, ಮತ್ತು ಪರಲೋಕವನ್ನು ನಂಬುವವರು. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ಇಬ್ರಾಹೀಮ್, ಇಸ್ಮಾಯೀಲ್, ಇಸ್ಹಾಕ್, ಯಾಕೂಬ್ ಮತ್ತು ವಂಶಗಳಿಗೆ, ಮತ್ತು ಮೂಸಾ ಮತ್ತು ಈಸಾರಿಗೆ ನೀಡಲ್ಪಟ್ಟದ್ದಕ್ಕೆ. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ಗುಂಪು ಗುಂಪಾಗಿ, ಅವರು ಅದರ ಬಳಿಗೆ ಬಂದಾಗ, ಅದರ ಬಾಗಿಲುಗಳನ್ನು ತೆರೆಯಲಾಗುವುದು, ಮತ್ತು ಅದರ ಕಾವಲುಗಾರರು ಅವರಿಗೆ ಹೇಳುವರು. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- ಅಲ್ಲಾಹನು ನಿಮ್ಮ ಪ್ರತಿಜ್ಞೆಗಳಲ್ಲಿನ ನಿಷ್ಪ್ರಯೋಜಕ ಮಾತುಗಳಿಗಾಗಿ ನಿಮ್ಮನ್ನು ಹಿಡಿಯುವುದಿಲ್ಲ, ಆದರೆ ಅವನು ನಿಮ್ಮನ್ನು ಹಿಡಿಯುವನು. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ಕರುಣೆ, ಅವರು ಅದರಿಂದ ಸಂತೋಷಪಡುತ್ತಾರೆ, ಮತ್ತು ಅವರ ಕೈಗಳು ಮುಂದೆ ಕಳುಹಿಸಿದುದರ ಕಾರಣ ಅವರಿಗೆ ಕೇಡು ತಟ್ಟಿದರೆ. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ತಳದಲ್ಲಿ ನದಿಗಳು ಹರಿಯುವ ತೋಟಗಳು, ಅವುಗಳಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು, ಮತ್ತು ಕೆಲಸ ಮಾಡುವವರ ಪ್ರತಿಫಲವು ಎಷ್ಟು ಸುಂದರವಾಗಿದೆ! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- ಅಲ್ಲಾಹನು ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವುದನ್ನು ಬಲ್ಲನು, ಮತ್ತು ಅಲ್ಲಾಹನು. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- ಅಲ್ಲಾಹನ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿರಿ ಮತ್ತು ಪ್ರವಕ್ತರ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿರಿ; ಆದರೆ ನೀವು ಮುಖ ತಿರುಗಿಸಿದರೆ, ಅವನ ಮೇಲೆ (ಹೊಣೆ) ಇದೆ. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ಅವರಿಗೆ ಅವರ ಒಡೆಯನ ಬಳಿ ಅವರ ಪ್ರತಿಫಲವಿದೆ, ಮತ್ತು ಅವರಿಗೆ ಯಾವುದೇ ಭಯವಿಲ್ಲ, ಮತ್ತು ಅವರು. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ಮತ್ತು ಅವರು ಹೇಳಿದರು: "ನಾವು ಮೂಳೆಗಳು ಮತ್ತು ಕಸಕಡ್ಡಿಗಳಾದಾಗ, ನಾವು ಹೊಸ ಸೃಷ್ಟಿಯಾಗಿ ಎಬ್ಬಿಸಲ್ಪಡುವೆವೇ?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ಮತ್ತು ಅವರು ತಮಗಾಗಿ ಅಲ್ಲಾಹನ ಹೊರತು ಯಾವುದೇ ರಕ್ಷಕ ಮತ್ತು ಸಹಾಯಕನನ್ನು ಕಾಣುವುದಿಲ್ಲ. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ನೀನು ಎಷ್ಟು ಕಾಲ ಇದ್ದೆ?" ಅವನು ಹೇಳಿದನು: "ನಾನು ಒಂದು ದಿನ ಅಥವಾ ದಿನದ ಒಂದು ಭಾಗ ಇದ್ದೆ." ಅವನು ಹೇಳಿದನು. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ಪುನರುತ್ಥಾನದ ದಿನದವರೆಗೆ, ಅಲ್ಲಾಹನ ಹೊರತು ನಿಮಗೆ ತರಬಲ್ಲ ದೇವರು ಯಾರು? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ಸತ್ಕರ್ಮ ಮಾಡಿದವನು, ಪುರುಷನಾಗಿರಲಿ ಅಥವಾ ಸ್ತ್ರೀಯಾಗಿರಲಿ, ಮತ್ತು ಅವನು ವಿಶ್ವಾಸಿಯಾಗಿರಲಿ. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ಅಲ್ಲಾಹನ ಮಾರ್ಗದಿಂದ ಜನರನ್ನು ತಡೆಯುವವರು ಮತ್ತು ಅದನ್ನು ವಕ್ರಗೊಳಿಸಲು ಬಯಸುವವರು, ಮತ್ತು ಅವರು ಪರಲೋಕವನ್ನು ನಂಬದವರು. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ನೀವು ಇಚ್ಛಿಸಿದ ಕಡೆ ತಿನ್ನಿರಿ, ಆದರೆ ಈ ಮರದ ಬಳಿ ಸಮೀಪಿಸಬೇಡಿ, ಇಲ್ಲದಿದ್ದರೆ ನೀವು ಅಕ್ರಮಿಗಳಾಗುವಿರಿ. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ಹೇಳು: "ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ನಿಮ್ಮ ಸ್ಥಾನದಲ್ಲಿ ಕೆಲಸ ಮಾಡಿರಿ, ನಾನೂ ಕೆಲಸ ಮಾಡುತ್ತೇನೆ, ಮತ್ತು ಬೇಗ ನೀವು ತಿಳಿಯುವಿರಿ." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- ನಿಶ್ಚಯವಾಗಿಯೂ, ನಷ್ಟದಲ್ಲಿರುವವರು ತಮ್ಮನ್ನು ಮತ್ತು ತಮ್ಮ ಕುಟುಂಬವನ್ನು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ನಷ್ಟಪಡಿಸಿಕೊಂಡವರೇ, ನೋಡಿರಿ. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ಸನ್ಮಾರ್ಗ ಪಡೆದವನು ತನಗಾಗಿಯೇ ಸನ್ಮಾರ್ಗ ಪಡೆಯುತ್ತಾನೆ; ಮತ್ತು ದಾರಿ ತಪ್ಪಿದವನು ತನಗಾಗಿಯೇ ದಾರಿ ತಪ್ಪುತ್ತಾನೆ; ಮತ್ತು. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- ಮತ್ತು ಅವಿಶ್ವಾಸಿಗಳು ಹೇಳುತ್ತಾರೆ: "ಅವನ ಒಡೆಯನ ಕಡೆಯಿಂದ ಅವನ ಮೇಲೆ ಒಂದು ಸೂಚನೆ ಏಕೆ ಇಳಿಸಲಾಗಿಲ್ಲ?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ನಿಮಗಾಗಿ ರಾತ್ರಿಯನ್ನು ಆರಾಮಕ್ಕಾಗಿ ಮತ್ತು ಹಗಲನ್ನು ಪ್ರಕಾಶಮಾನವಾಗಿ ಮಾಡಿದವನು, ನಿಶ್ಚಯವಾಗಿಯೂ. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ಯಾವುದೇ ವ್ಯಾಪಾರ ಅಥವಾ ಸ್ನೇಹವಿಲ್ಲದ ದಿನವು ಬರುವ ಮುನ್ನ. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ಅವರ ಸಹಚರನಿಗೆ ಯಾವುದೇ ಹುಚ್ಚಿಲ್ಲ ಎಂದು ಅವರು ಯೋಚಿಸಲಿ; ಅವನು ಸ್ಪಷ್ಟ ಎಚ್ಚರಿಕೆ ನೀಡುವವನು ಮಾತ್ರ. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- ಅವುಗಳಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು, ಅವರಿಂದ ಶಿಕ್ಷೆಯು ಕಡಿಮೆಯಾಗದು, ಮತ್ತು ಅವರಿಗೆ ವಿಳಂಬ ನೀಡಲಾಗದು. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ನಾವು ಅವರಲ್ಲಿ ಕೆಲವರಿಗೆ ಆನಂದವಾಗಿ ನೀಡಿದ್ದರ ಕಡೆಗೆ ನಿನ್ನ ಕಣ್ಣುಗಳನ್ನು ಹರಿಸಬೇಡ. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ಮತ್ತು ಜನರಿಗೆ ಅವರ ವಸ್ತುಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಬೇಡಿ, ಮತ್ತು ಭೂಮಿಯಲ್ಲಿ ಅಶಾಂತಿಯನ್ನು ಹರಡಬೇಡಿ. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- ಅವನು ಹುಟ್ಟಿದ ದಿನ, ಅವನು ಸಾಯುವ ದಿನ, ಮತ್ತು ಅವನು ಜೀವಂತವಾಗಿ ಎಬ್ಬಿಸಲ್ಪಡುವ ದಿನ ಅವನ ಮೇಲೆ ಶಾಂತಿ ಇರಲಿ. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ಓ ನನ್ನ ಜನಾಂಗದವರೇ! ನಿಮ್ಮ ಸ್ಥಾನದಲ್ಲಿ ಕೆಲಸ ಮಾಡಿರಿ, ನಾನೂ ಕೆಲಸ ಮಾಡುತ್ತೇನೆ, ಮತ್ತು ಬೇಗ ನೀವು ತಿಳಿಯುವಿರಿ ಯಾರು. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ಮತ್ತು ಯಾವುದೇ ಪ್ರವಕ್ತನಿಗೆ ಅಲ್ಲಾಹನ ಅನುಮತಿಯಿಲ್ಲದೆ ಸೂಚನೆಯನ್ನು ತರಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ನಂತರ ಪ್ರತಿಯೊಂದು ಜೀವಕ್ಕೂ ತಾನು ಸಂಪಾದಿಸಿದ್ದಕ್ಕೆ ಸಂಪೂರ್ಣ ಪ್ರತಿಫಲ ನೀಡಲಾಗುವುದು, ಮತ್ತು ಅವರ ಮೇಲೆ ಅಕ್ರಮವಾಗುವುದಿಲ್ಲ. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ಪುರುಷನಾಗಿರಲಿ ಅಥವಾ ಸ್ತ್ರೀಯಾಗಿರಲಿ, ಮತ್ತು ಅವನು ವಿಶ್ವಾಸಿಯಾಗಿರಲಿ, ಅಂತಹವರು ಸ್ವರ್ಗಕ್ಕೆ ಪ್ರವೇಶಿಸುವರು. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ಅವನು ಯಾವುದೇ ಸಂತಾನವನ್ನು ಹೊಂದಿಲ್ಲ, ಮತ್ತು ಆಡಳಿತದಲ್ಲಿ ಅವನಿಗೆ ಯಾವುದೇ ಪಾಲುದಾರನಿಲ್ಲ. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- ಅಲ್ಲಾಹನು ಸನ್ಮಾರ್ಗ ತೋರಿಸಿದವನು ಸನ್ಮಾರ್ಗ ಪಡೆದವನು; ಮತ್ತು ಅವನು ದಾರಿ ತಪ್ಪಿಸಿದವನಿಗೆ ನೀನು ಎಂದಿಗೂ. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ನೋಡು, ಅವರು ನಿನಗೆ ಹೇಗೆ ಉದಾಹರಣೆಗಳನ್ನು ನೀಡುತ್ತಾರೆ, ಆದ್ದರಿಂದ ಅವರು ದಾರಿ ತಪ್ಪಿದರು ಮತ್ತು ಮಾರ್ಗವನ್ನು ಕಂಡುಕೊಳ್ಳಲಿಲ್ಲ. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ಹೇಳು: "ನಾನು ನನ್ನ ಒಡೆಯನ ಆಜ್ಞೆಯನ್ನು ಮೀರಿದರೆ ಮಹಾನ್ ದಿನದ ಶಿಕ್ಷೆಯ ಭಯಪಡುತ್ತೇನೆ." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ಅವರ ಇಬ್ಬರ ಅವಯವಗಳು ತೆರೆದುಕೊಂಡವು, ಮತ್ತು ಅವರು ಸ್ವರ್ಗದ ಎಲೆಗಳಿಂದ ತಮ್ಮನ್ನು ಮುಚ್ಚಿಕೊಳ್ಳಲು ಆರಂಭಿಸಿದರು. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- ಮತ್ತು ಅಲ್ಲಾಹನ ಹೊರತು ನೀವು ಶಕ್ತರಾದವರನ್ನು ಕರೆಯಿರಿ, ನೀವು ಸತ್ಯವಂತರಾಗಿದ್ದರೆ. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- ಭೂಮಿಯಲ್ಲಿರುವ ಎಲ್ಲವೂ ಮತ್ತು ಅಷ್ಟೇನೂ, ಅದರ ಮೂಲಕ ತಮ್ಮನ್ನು ಬಿಡುಗಡೆ ಮಾಡಿಕೊಳ್ಳಲು. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ನಾವು ನಿಮಗೆ ಕೊಟ್ಟದ್ದನ್ನು ಬಲವಾಗಿ ಹಿಡಿದುಕೊಳ್ಳಿರಿ ಮತ್ತು ಅದರಲ್ಲಿರುವುದನ್ನು ನೆನಪಿಸಿಕೊಳ್ಳಿರಿ, ಆಗ ನೀವು ಭಯಭಕ್ತರಾಗಬಹುದು. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ಈ ಹೇಸಿಗೆಯ ಕಾರ್ಯವನ್ನು ನೀವು ಮಾಡುತ್ತೀರಾ, ಅದನ್ನು ನಿಮ್ಮ ಹಿಂದೆ ಯಾರೂ ಮಾಡಿಲ್ಲ? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವ ಎಲ್ಲವೂ ಅಲ್ಲಾಹನದೇ, ಮತ್ತು ಅಲ್ಲಾಹನು. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ಅವರು ಮಾಡಿದ ಕೆಟ್ಟ ಕಾರ್ಯಗಳು ಅವರ ಮೇಲೆ ಬಿದ್ದವು, ಮತ್ತು ಅವರು ಅಪಹಾಸ್ಯ ಮಾಡುತ್ತಿದ್ದದ್ದು ಅವರನ್ನು ಸುತ್ತುವರಿದುಕೊಂಡಿತು. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
