- ಅವನ ಒಡೆಯನ ಬಳಿ, ಮತ್ತು ಅವರಿಗೆ ಯಾವುದೇ ಭಯವಿಲ್ಲ, ಮತ್ತು ಅವರು ದುಃಖಿಸುವುದಿಲ್ಲ. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- ಯಾರು ಸನ್ಮಾರ್ಗವನ್ನು ಪಡೆಯುತ್ತಾರೋ, ಅವರು ತಮ್ಮ ಸ್ವಂತ ಪ್ರಯೋಜನಕ್ಕಾಗಿ ಪಡೆಯುತ್ತಾರೆ, ಮತ್ತು ಯಾರು ದಾರಿ ತಪ್ಪುತ್ತಾರೋ. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- ತಮ್ಮ ಸ್ವಂತ ಪ್ರಯೋಜನಕ್ಕಾಗಿ ಪಡೆಯುತ್ತಾರೆ, ಮತ್ತು ಯಾರು ದಾರಿ ತಪ್ಪುತ್ತಾರೋ, ಅವರು ತಮ್ಮ ಸ್ವಂತ ನಷ್ಟಕ್ಕಾಗಿ ದಾರಿ ತಪ್ಪುತ್ತಾರೆ. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- ಅವನ ಮೇಲೆ ಅವನ ಒಡೆಯನ ಕಡೆಯಿಂದ ಒಂದು ಸೂಚನೆಯು ಏಕೆ ಇಳಿಸಲ್ಪಡಲಿಲ್ಲ? ಹೇಳು: ಖಂಡಿತವಾಗಿಯೂ. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- ವಿಶ್ವಾಸವಿಟ್ಟು ಸತ್ಕರ್ಮಗಳನ್ನು ಮಾಡಿದವರಿಗೆ, ಅವರಿಗೆ ಅಂತ್ಯವಿಲ್ಲದ ಪ್ರತಿಫಲವಿದೆ. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- ನೀನು ಜೀವಂತವನ್ನು ಸತ್ತವನಿಂದ ಹೊರತರುವೆ ಮತ್ತು ಸತ್ತವನನ್ನು ಜೀವಂತದಿಂದ ಹೊರತರುವೆ. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- ಯಾರು ಅಲ್ಲಾಹನು ಇಳಿಸಿದ್ದರ ಪ್ರಕಾರ ತೀರ್ಪು ನೀಡುವುದಿಲ್ಲವೋ, ಅಂತಹವರೇ. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- ಅವನು ಆಕಾಶಗಳನ್ನು, ಭೂಮಿಯನ್ನು ಮತ್ತು ಅವುಗಳ ನಡುವಿನ ಎಲ್ಲವನ್ನೂ ಆರು ದಿನಗಳಲ್ಲಿ ಸೃಷ್ಟಿಸಿದನು. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ಮಾನವರ ಮೇಲೆ ಅಪಾರ ಅನುಗ್ರಹವುಳ್ಳವನು, ಆದರೆ ಹೆಚ್ಚಿನವರು. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- ಅಲ್ಲಾಹನು ಅವರ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡಲಿಲ್ಲ, ಆದರೆ ಅವರೇ ತಮ್ಮ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡಿಕೊಳ್ಳುತ್ತಿದ್ದರು. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- ಅವನು ನಿಮ್ಮ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸುವನು ಮತ್ತು ನಿಮ್ಮನ್ನು ಸ್ವರ್ಗದ ತೋಟಗಳಿಗೆ ಪ್ರವೇಶಿಸುವನು, ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- ಅವನು ನಿಮ್ಮ ಮೇಲೆ ಮೃತಪ್ರಾಣಿ, ರಕ್ತ, ಹಂದಿಯ ಮಾಂಸ, ಮತ್ತು ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆಯವರ ಹೆಸರಿನಲ್ಲಿ ವಧಿಸಲ್ಪಟ್ಟುದನ್ನು ನಿಷೇಧಿಸಿದನು. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- ಖಂಡಿತವಾಗಿಯೂ ನಾನು, ನನ್ನ ಒಡೆಯನಿಗೆ ಅವಿಧೇಯನಾದರೆ, ಮಹಾ ದಿನದ ಶಿಕ್ಷೆಗೆ ಹೆದರುತ್ತೇನೆ. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- ಆದರೆ ಅವರ ಬಳಿಗೆ ಜ್ಞಾನವು ಬಂದ ನಂತರ, ಅವರ ನಡುವಿನ ಹೊಟ್ಟೆಕಿಚ್ಚಿನ ಕಾರಣದಿಂದ. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- ಅವರು ನಮಾಝ್ ಅನ್ನು ಸ್ಥಾಪಿಸುತ್ತಾರೆ ಮತ್ತು ನಾವು ಅವರಿಗೆ ನೀಡಿದ್ದರಿಂದ ಗುಪ್ತವಾಗಿ ಮತ್ತು ಬಹಿರಂಗವಾಗಿ ಖರ್ಚು ಮಾಡುತ್ತಾರೆ. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- ನಾವು ಅಲ್ಲಾಹನನ್ನು ಬಿಟ್ಟು, ನಮಗೆ ಲಾಭವನ್ನೂ ನಷ್ಟವನ್ನೂ ಮಾಡದೇ ಇರುವಂತಹವನನ್ನು ಪ್ರಾರ್ಥಿಸುವುದೇ? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- ಅವರು ನಿಮ್ಮ ಕಡೆಗೆ ಇಳಿಸಲ್ಪಟ್ಟ ಮತ್ತು ನಿಮಗಿಂತ ಮೊದಲು ಇಳಿಸಲ್ಪಟ್ಟ ವಿಷಯಗಳಲ್ಲಿ ವಿಶ್ವಾಸವಿಡುತ್ತಾರೆ. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- ಅಲ್ಲಾಹನು ಆಕಾಶದಿಂದ ನೀರನ್ನು ಇಳಿಸುತ್ತಿರುವುದನ್ನು ನೀವು ನೋಡಲಿಲ್ಲವೇ? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- ಅವನು ಯಾವುದೇ ಕಾರ್ಯವನ್ನು ನಿರ್ಧರಿಸಿದಾಗ, ಅದಕ್ಕೆ: ಆಗು ಎಂದು ಹೇಳುತ್ತಾನೆ, ಅದು ಆಗುತ್ತದೆ. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- ಮತ್ತು ಮದ್ಯನ್ ಕಡೆಗೆ ಅವರ ಸಹೋದರ ಶುಐಬ್ ಅನ್ನು (ಕಳುಹಿಸಿದೆವು). ಅವನು ಹೇಳಿದನು: ಓ ನನ್ನ ಜನಾಂಗದವರೇ, ಅಲ್ಲಾಹನನ್ನು ಆರಾಧಿಸಿರಿ. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- ಇದು ಗುಪ್ತ ವಿಷಯಗಳ ಸುದ್ದಿಗಳಲ್ಲಿ ಒಂದಾಗಿದೆ, ಅದನ್ನು ನಾವು ನಿಮಗೆ ದಿವ್ಯ ಸಂದೇಶದ ಮೂಲಕ ತಿಳಿಸುತ್ತೇವೆ; ನಿಮಗೆ ಇದು ತಿಳಿದಿರಲಿಲ್ಲ. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ಅವರ ನಿಗದಿತ ಅವಧಿಯು ಬಂದಾಗ, ಅವರು ಅದನ್ನು ಒಂದು ಕ್ಷಣವೂ ವಿಳಂಬಗೊಳಿಸಲು ಅಥವಾ ಮುಂದೆ ಹಾಕಲು ಸಾಧ್ಯವಿಲ್ಲ. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- ಮತ್ತು ಶೈತಾನ್ನ ಹೆಜ್ಜೆಗಳನ್ನು ಅನುಸರಿಸಬೇಡಿ; ಖಂಡಿತವಾಗಿಯೂ ಅವನು ನಿಮ್ಮ ಸ್ಪಷ್ಟ ಶತ್ರುವಾಗಿದ್ದಾನೆ. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- ಮತ್ತು ಮಾನವರಲ್ಲಿ ಕೆಲವರು, ಯಾವುದೇ ಜ್ಞಾನವಿಲ್ಲದೇ ಅಲ್ಲಾಹನ ಬಗ್ಗೆ ವಾದಿಸುತ್ತಾರೆ. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- ಅಲ್ಲಾಹನು ಅದನ್ನು ತಾನು ಇಚ್ಛಿಸಿದವರಿಗೆ ನೀಡುತ್ತಾನೆ, ಮತ್ತು ಅಲ್ಲಾಹನು ಅಪಾರ ಅನುಗ್ರಹವುಳ್ಳವನಾಗಿದ್ದಾನೆ. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ಪ್ರತಿಯೊಬ್ಬ ವ್ಯಕ್ತಿಗೆ ಅವನು ಗಳಿಸಿದ್ದಕ್ಕೆ ಸಂಪೂರ್ಣ ಪ್ರತಿಫಲವನ್ನು ನೀಡಲಾಗುವುದು, ಮತ್ತು ಅವರ ಮೇಲೆ ಅಕ್ರಮ ಮಾಡಲಾಗುವುದಿಲ್ಲ. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- ಅಲ್ಲಾಹನು ನಿಷೇಧಿಸಿರುವ ಪ್ರಾಣವನ್ನು, ನ್ಯಾಯವಲ್ಲದೇ ಕೊಲ್ಲಬೇಡಿ. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- ಅವನು ಯಾವುದೇ ಕಾರ್ಯವನ್ನು ನಿರ್ಧರಿಸಿದಾಗ, ಅದಕ್ಕೆ: ಆಗು ಎಂದು ಹೇಳುತ್ತಾನೆ. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- ನೀವು ನರಕದ ಬಾಗಿಲುಗಳನ್ನು ಪ್ರವೇಶಿಸಿರಿ, ಅಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ಇರುವಿರಿ; ಅಹಂಕಾರಿಗಳ ವಾಸಸ್ಥಾನವು ಎಷ್ಟು ಕೆಟ್ಟದಾಗಿದೆ! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ಗ್ರಂಥದ ಭಾಗವನ್ನು ನೀಡಲ್ಪಟ್ಟವರನ್ನು ನೀವು ನೋಡಲಿಲ್ಲವೇ? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ಅವರಿಗೆ ಸ್ವರ್ಗದ ತೋಟಗಳಿವೆ, ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ, ಅಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ಓ ನನ್ನ ಜನಾಂಗದವರೇ, ನಿಮ್ಮ ಸ್ಥಾನದಲ್ಲೇ ಕಾರ್ಯ ಮಾಡಿರಿ, ನಾನೂ ಕಾರ್ಯ ಮಾಡುತ್ತೇನೆ, ಮತ್ತು ನೀವು ಬೇಗನೆ ತಿಳಿಯುವಿರಿ. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- ಯಾರು ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಪ್ರವಾದಿಯ ವಿರೋಧ ಮಾಡುತ್ತಾನೋ, ಅವನಿಗೆ ನರಕದ ಬೆಂಕಿಯಿದೆ, ಅದರಲ್ಲಿ ಅವನು ಶಾಶ್ವತವಾಗಿ ಇರುವನು. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- ಅವರ ಹೃದಯಗಳ ಮೇಲೆ ನಾವು ಪರದೆಗಳನ್ನು ಇರಿಸಿದೆವು, ಇದರಿಂದ ಅವರು ಅದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳದಿರಲಿ, ಮತ್ತು ಅವರ ಕಿವಿಗಳಲ್ಲಿ ಭಾರವನ್ನು. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- ಯಾವುದೇ ಊರಿಗೆ ನಾವು ಎಚ್ಚರಿಕೆ ನೀಡುವವರನ್ನು ಕಳುಹಿಸಿದಾಗ, ಅಲ್ಲಿನ ಐಶ್ವರ್ಯವಂತರು ಹೇಳುತ್ತಿದ್ದರು: ಖಂಡಿತವಾಗಿಯೂ ನಾವು. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- ಅವರು ಹೇಳಿದರು: ನಮಗಾಗಿ ನಿಮ್ಮ ಒಡೆಯನಲ್ಲಿ ಪ್ರಾರ್ಥಿಸಿರಿ, ಅದು ಏನೆಂದು ಅವನು ನಮಗೆ ಸ್ಪಷ್ಟಪಡಿಸಲಿ. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- ಅವರು ಖಂಡಿತವಾಗಿಯೂ: ಅಲ್ಲಾಹನು ಎಂದು ಹೇಳುವರು. ಹೇಳು: ಎಲ್ಲಾ ಸ್ತುತಿಯು ಅಲ್ಲಾಹನಿಗೇ ಸಲ್ಲುತ್ತದೆ! ಆದರೆ ಅವರಲ್ಲಿ ಹೆಚ್ಚಿನವರು. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- ಅವನ ಜನಾಂಗದ ಉತ್ತರವು, ಅವರನ್ನು ಹೊರಗೆ ಹಾಕಿರಿ ಎಂದು ಹೇಳುವುದಕ್ಕಿಂತ ಬೇರೆಯಾಗಿರಲಿಲ್ಲ. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ, ಅಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು; ಅದೇ ಮಹಾನ್ ವಿಜಯವಾಗಿದೆ. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ಅಂತಹವರು ತಮ್ಮ ಒಡೆಯನ ಕಡೆಯಿಂದ ಸನ್ಮಾರ್ಗದಲ್ಲಿರುತ್ತಾರೆ, ಮತ್ತು ಅಂತಹವರೇ ಯಶಸ್ವಿಗಳು. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- ಯಾರಿಗೆ ಅಪಮಾನಕರ ಶಿಕ್ಷೆಯು ಬರುವುದೋ ಮತ್ತು ಯಾರ ಮೇಲೆ ಶಾಶ್ವತ ಶಿಕ್ಷೆಯು ಇಳಿಯುವುದೋ. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- ಭೂಮಿಯಲ್ಲಿ ಸಂಚರಿಸಿ, ಸುಳ್ಳಾರೋಪಿಗಳ ಅಂತ್ಯವು ಹೇಗಿತ್ತು ಎಂದು ನೋಡಿರಿ. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- ಅವರು ತಮ್ಮ ಕೈಗಳು ಮುಂದೆ ಕಳುಹಿಸಿದ ಕಾರಣದಿಂದ ಅದನ್ನು ಎಂದಿಗೂ ಬಯಸುವುದಿಲ್ಲ, ಮತ್ತು ಅಲ್ಲಾಹನು ಅಕ್ರಮಿಗಳನ್ನು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- ಅವನೇ ಹೆಚ್ಚು ಬಲ್ಲವನು, ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪಿದ್ದಾರೆಂದು, ಮತ್ತು ಅವನೇ ಹೆಚ್ಚು ಬಲ್ಲವನು. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ನನ್ನ ಒಡೆಯನು ಮತ್ತು ನಿಮ್ಮ ಒಡೆಯನು; ಆದ್ದರಿಂದ ಅವನನ್ನೇ ಆರಾಧಿಸಿರಿ; ಇದೇ ನೇರ ಮಾರ್ಗವಾಗಿದೆ. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- ಅವನು ಮಾನವರ ಮೇಲೆ ಅಪಾರ ಅನುಗ್ರಹವುಳ್ಳವನು, ಆದರೆ ಅವರಲ್ಲಿ ಹೆಚ್ಚಿನವರು ಕೃತಜ್ಞರಾಗಿರುವುದಿಲ್ಲ. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ಆಕಾಶಗಳು, ಭೂಮಿ ಮತ್ತು ಅವುಗಳ ನಡುವಿನ ಎಲ್ಲವನ್ನೂ, ಸತ್ಯದೊಂದಿಗೆ ಮತ್ತು ನಿಗದಿತ ಅವಧಿಗಾಗಿ ಮಾತ್ರ ನಾವು ಸೃಷ್ಟಿಸಿದೆವು. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ಅವರನ್ನು ಅವರ ವ್ಯರ್ಥ ಚಟುವಟಿಕೆಗಳು ಮತ್ತು ಆಟಗಳಲ್ಲಿ ಮುಳುಗಿರಲು ಬಿಡಿ, ತನಕ ಅವರು ತಮ್ಮ ಆ ದಿನವನ್ನು ಎದುರಿಸುವವರೆಗೆ, ಅದರ ಭರವಸೆಯನ್ನು ಅವರಿಗೆ ನೀಡಲಾಗಿದೆ. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- ಅವರು ವಿಶ್ವಾಸಿಗಳನ್ನು ಭೇಟಿಯಾದಾಗ, ನಾವು ವಿಶ್ವಾಸವಿಟ್ಟಿದ್ದೇವೆ ಎಂದು ಹೇಳುತ್ತಾರೆ, ಮತ್ತು ಅವರು ತಮ್ಮಲ್ಲೇ ಏಕಾಂತದಲ್ಲಿದ್ದಾಗ. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- ಅವರು ತೌರಾತ್ ಮತ್ತು ಇಂಜೀಲ್ ಅನ್ನು ಮತ್ತು ತಮ್ಮ ಒಡೆಯನ ಕಡೆಯಿಂದ ತಮಗೆ ಇಳಿಸಲ್ಪಟ್ಟುದನ್ನು ಸ್ಥಾಪಿಸುತ್ತಾರೆ. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- ಅವನು ಅವರ ಮುಂದೆ ಇರುವುದನ್ನು ಮತ್ತು ಅವರ ಹಿಂದೆ ಇರುವುದನ್ನು ಬಲ್ಲನು, ಮತ್ತು ಅವರು ಅದನ್ನು ತಮ್ಮ ಜ್ಞಾನದಿಂದ ಆವರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- ಮತ್ತು ಅವನೇ ಆಕಾಶಗಳನ್ನು ಮತ್ತು ಭೂಮಿಯನ್ನು ಆರು ದಿನಗಳಲ್ಲಿ ಸೃಷ್ಟಿಸಿದನು. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- ಖಂಡಿತವಾಗಿಯೂ ಇದರಲ್ಲಿ ನಿಮಗೆ ಒಂದು ಸೂಚನೆಯಿದೆ, ನೀವು ವಿಶ್ವಾಸಿಗಳಾಗಿದ್ದರೆ. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- ಜನರಿಗೆ ಸನ್ಮಾರ್ಗವು ಬಂದಾಗ, ಅವರು ವಿಶ್ವಾಸವಿಡದಂತೆ ಮಾಡಿದ್ದೇನು? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- ಅವರು ಅಲ್ಲಾಹನಿಗೆ ಪಾಲುದಾರರನ್ನು ಸ್ಥಾಪಿಸಿದರು, ಅವನ ಮಾರ್ಗದಿಂದ ದಾರಿ ತಪ್ಪಿಸಲು. ಹೇಳು: ನೀವು ಸುಖಿಸಿರಿ. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- ಮತ್ತು ಅವರಿಗೆ ಆಶ್ಚರ್ಯವಾಯಿತು, ಅವರಲ್ಲೇ ಒಬ್ಬ ಎಚ್ಚರಿಕೆ ನೀಡುವವನು ಅವರ ಬಳಿಗೆ ಬಂದನೆಂದು, ಮತ್ತು ಅವಿಶ್ವಾಸಿಗಳು ಹೇಳಿದರು: ಇವನು. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- ಖಂಡಿತವಾಗಿಯೂ ನಿಮ್ಮ ಒಡೆಯನು ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪಿದ್ದಾರೆಂದು ಹೆಚ್ಚು ಬಲ್ಲವನು. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- ತನ್ನ ಸಂಪತ್ತನ್ನು ಜನರಿಗೆ ತೋರಿಸಲು ಖರ್ಚು ಮಾಡುವ, ಮತ್ತು ಅಲ್ಲಾಹನಲ್ಲಿ ವಿಶ್ವಾಸವಿಡದವನಂತೆ. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- ನಾವು ನಿಮಗೆ ನೀಡಿದ್ದರಿಂದ, ಅದು (ಮರಣ) ಬರುವ ಮೊದಲು ಖರ್ಚು ಮಾಡಿರಿ. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- ಅವನು ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವುದನ್ನು ನಿಮಗೆ ಅಧೀನಗೊಳಿಸಿದನು. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- ಮತ್ತು ನಾವು ಖಂಡಿತವಾಗಿಯೂ, ನೀವು ನಮ್ಮನ್ನು ಕರೆಯುವ ವಿಷಯದಲ್ಲಿ ಸಂದೇಹದಲ್ಲಿದ್ದೇವೆ. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- ಖಂಡಿತವಾಗಿಯೂ ನಿಮ್ಮ ಒಡೆಯನು ತಾನು ಇಚ್ಛಿಸಿದವರಿಗೆ ಆಹಾರವನ್ನು ವಿಸ್ತಾರಗೊಳಿಸುತ್ತಾನೆ ಮತ್ತು ಸಂಕುಚಿತಗೊಳಿಸುತ್ತಾನೆ. ಖಂಡಿತವಾಗಿಯೂ ಅವನು. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- ಆಕಾಶಗಳು, ಭೂಮಿ ಮತ್ತು ಅವುಗಳ ನಡುವೆ ಇರುವ ಎಲ್ಲದರ ಒಡೆಯನು, ನೀವು ದೃಢವಿಶ್ವಾಸಿಗಳಾಗಿದ್ದರೆ. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ನಾವು ಅಲ್ಲಾಹನಲ್ಲಿ ವಿಶ್ವಾಸವಿಟ್ಟಿದ್ದೇವೆ ಮತ್ತು ನಮ್ಮ ಕಡೆಗೆ ಇಳಿಸಲ್ಪಟ್ಟ ಮತ್ತು (ಹಿಂದಿನ ಪ್ರವಾದಿಗಳ) ಕಡೆಗೆ ಇಳಿಸಲ್ಪಟ್ಟ ವಿಷಯಗಳಲ್ಲಿ. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- ಮತ್ತು ಅಕ್ರಮಿಗಳನ್ನು ಭೀಕರ ಧ್ವನಿಯು ಹಿಡಿದುಕೊಂಡಿತು, ಮತ್ತು ಅವರು ತಮ್ಮ ಮನೆಗಳಲ್ಲಿ ಬೋರಲು ಬಿದ್ದರು. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ಆ ಸ್ತ್ರೀಯರು ತಮ್ಮ ಬಗ್ಗೆ ಮಾಡುವ ಕಾರ್ಯಗಳಲ್ಲಿ ನಿಮ್ಮ ಮೇಲೆ ಯಾವುದೇ ಪಾಪವಿಲ್ಲ. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ನಿಮ್ಮ ಒಡೆಯನು ತನ್ನ ಮಾರ್ಗದಿಂದ ಯಾರು ದಾರಿ ತಪ್ಪಿದ್ದಾರೆಂದು ಹೆಚ್ಚು ಬಲ್ಲವನು, ಮತ್ತು ಅವನು. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ತನ್ನ ಆಜ್ಞೆಯಿಂದ ಆತ್ಮವನ್ನು (ದಿವ್ಯ ಸಂದೇಶವನ್ನು) ತನ್ನ ದಾಸರಲ್ಲಿ ತಾನು ಇಚ್ಛಿಸಿದವರ ಮೇಲೆ ಇಳಿಸುತ್ತಾನೆ. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- ಮತ್ತು ನಾವು ಮರ್ಯಮ್ ಪುತ್ರ ಈಸಾಗೆ ಸ್ಪಷ್ಟ ಸೂಚನೆಗಳನ್ನು ನೀಡಿದೆವು ಮತ್ತು ಪವಿತ್ರಾತ್ಮದ ಮೂಲಕ ಅವನನ್ನು ಬೆಂಬಲಿಸಿದೆವು. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಅವರು ಭಿನ್ನಾಭಿಪ್ರಾಯ ಹೊಂದಿದ್ದ ವಿಷಯದಲ್ಲಿ ಅವರ ನಡುವೆ ತೀರ್ಪು ನೀಡಲು. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ನಾವು ಆ ಊರನ್ನು ಮೇಲುಕೆಳಗಾಗಿಸಿದೆವು ಮತ್ತು ಅವರ ಮೇಲೆ ಸುಟ್ಟ ಮಣ್ಣಿನ ಕಲ್ಲುಗಳನ್ನು ಸುರಿಸಿದೆವು. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ನೀವು ಅವರನ್ನು ಎಚ್ಚರಿಸಿದರೂ ಅಥವಾ ಎಚ್ಚರಿಸದಿದ್ದರೂ ಅವರಿಗೆ ಸಮಾನವಾಗಿದೆ; ಅವರು ವಿಶ್ವಾಸವಿಡುವುದಿಲ್ಲ. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- ಮಾನವರನ್ನು ಬಿಟ್ಟು, ನೀವು ಸತ್ಯವಂತರಾಗಿದ್ದರೆ, ಮರಣವನ್ನು ಬಯಸಿರಿ. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- ಅಲ್ಲಾಹನನ್ನು (ಆರಾಧಿಸಿರಿ), ಅವನ ಹೊರತು ನಿಮಗೆ ಯಾವುದೇ ದೇವರು ಇಲ್ಲ. ಆಗ ನೀವು ಭಯಪಡುವುದಿಲ್ಲವೇ? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- ನಾವು ಅವರಿಗೆ ಭರವಸೆ ನೀಡಿರುವ ಕೆಲವನ್ನು ನಿಮಗೆ ತೋರಿಸಿದರೂ ಅಥವಾ ನಿಮ್ಮನ್ನು ಮರಣಗೊಳಿಸಿದರೂ, ಅವರ ಮರಳುವಿಕೆಯು ನಮ್ಮ ಕಡೆಗೇ ಇದೆ. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- ಅವರು ಹೇಳಿದರು: ನಾವು ಸತ್ತು, ಮಣ್ಣು ಮತ್ತು ಎಲುಬುಗಳಾದಾಗ, ನಾವು ಮತ್ತೆ ಎಬ್ಬಿಸಲ್ಪಡುತ್ತೇವೆಯೇ? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- ಖಂಡಿತವಾಗಿಯೂ ಅನುಗ್ರಹವು ಅಲ್ಲಾಹನ ಕೈಯಲ್ಲಿದೆ, ಅವನು ಅದನ್ನು ತಾನು ಇಚ್ಛಿಸಿದವರಿಗೆ ನೀಡುತ್ತಾನೆ, ಮತ್ತು ಅಲ್ಲಾಹನು. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ಮತ್ತು ನೀವು ಗುಪ್ತ ಮತ್ತು ಬಹಿರಂಗವನ್ನು ಬಲ್ಲವನ ಕಡೆಗೆ ಮರಳಿಸಲ್ಪಡುವಿರಿ, ಆಗ ಅವನು ನೀವು ಮಾಡುತ್ತಿದ್ದ ಕಾರ್ಯಗಳನ್ನು ನಿಮಗೆ ತಿಳಿಸುವನು. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- ಓ ವಿಶ್ವಾಸಿಗಳೇ, ಅಲ್ಲಾಹನು ನಿಮ್ಮ ಮೇಲೆ ಮಾಡಿದ ಅನುಗ್ರಹವನ್ನು ಸ್ಮರಿಸಿರಿ, ಆ ಸಮಯದಲ್ಲಿ. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- ಮತ್ತು ನಾವು ನಿಮಗಿಂತ ಮೊದಲು, ಪುರುಷರನ್ನು ಮಾತ್ರ ಪ್ರವಾದಿಗಳನ್ನಾಗಿ ಕಳುಹಿಸಿದೆವು, ಅವರಿಗೆ ನಾವು ದಿವ್ಯ ಸಂದೇಶವನ್ನು ಕಳುಹಿಸುತ್ತಿದ್ದೆವು. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- ಅವನು ಅವನ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸುವನು ಮತ್ತು ಅವನನ್ನು ಸ್ವರ್ಗದ ತೋಟಗಳಿಗೆ ಪ್ರವೇಶಿಸುವನು, ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- ಯಾರು ಅನಾರೋಗ್ಯದಲ್ಲಿರುತ್ತಾನೋ ಅಥವಾ ಪ್ರಯಾಣದಲ್ಲಿರುತ್ತಾನೋ, ಅವನು ಬೇರೆ ದಿನಗಳಲ್ಲಿ (ಉಪವಾಸದ) ಸಂಖ್ಯೆಯನ್ನು ಪೂರೈಸಲಿ. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- ಅವರು ಕೇವಲ ಊಹೆಯನ್ನು ಮಾತ್ರ ಅನುಸರಿಸುತ್ತಾರೆ, ಮತ್ತು ಅವರು ಕೇವಲ ಅಂದಾಜು ಮಾಡುತ್ತಾರೆ. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- ಅಲ್ಲಾಹನನ್ನು ಮತ್ತು ಅಂತಿಮ ದಿನವನ್ನು ಆಶಿಸುವವನಿಗೆ ಉತ್ತಮ ಮಾದರಿಯಿದೆ. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- ಮತ್ತು ನಾವು ಆಕಾಶಗಳು, ಭೂಮಿ ಮತ್ತು ಅವುಗಳ ನಡುವಿನ ಎಲ್ಲವನ್ನೂ ಸತ್ಯದೊಂದಿಗೆ ಮಾತ್ರ ಸೃಷ್ಟಿಸಿದೆವು. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- ನಿಮ್ಮ ಕೈಯನ್ನು ನಿಮ್ಮ ಎದೆಯೊಳಗೆ ಇರಿಸಿರಿ, ಅದು ಯಾವುದೇ ಕುಂದಿಲ್ಲದೆ ಬಿಳಿಯಾಗಿ ಹೊರಬರುವುದು. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- ಅವನು ತನ್ನ ಕೃಪೆಯಿಂದ ತಾನು ಇಚ್ಛಿಸಿದವರನ್ನು ವಿಶೇಷವಾಗಿ ಆರಿಸಿಕೊಳ್ಳುತ್ತಾನೆ, ಮತ್ತು ಅಲ್ಲಾಹನು ಅಪಾರ ಅನುಗ್ರಹವುಳ್ಳವನಾಗಿದ್ದಾನೆ. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- ಅಲ್ಲಾಹನಿಗೆ ಆಕಾಶಗಳ ಮತ್ತು ಭೂಮಿಯ ಆಡಳಿತವು ಸೇರಿದೆ ಎಂದು ನಿಮಗೆ ತಿಳಿದಿಲ್ಲವೇ? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- ನೀವು ನಿಮ್ಮ ಸ್ವಂತಕ್ಕಾಗಿ ಮುಂದೆ ಕಳುಹಿಸುವ ಯಾವುದೇ ಒಳ್ಳೆಯ ಕಾರ್ಯವನ್ನು, ನೀವು ಅದನ್ನು ಅಲ್ಲಾಹನ ಬಳಿಯಲ್ಲಿ ಕಾಣುವಿರಿ. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- ಮತ್ತು ನೀವು ಎಲ್ಲಿಂದ ಹೊರಟರೂ, ನಿಮ್ಮ ಮುಖವನ್ನು ಮಸ್ಜಿದುಲ್ ಹರಾಮ್ ಕಡೆಗೆ ತಿರುಗಿಸಿರಿ. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ನಿಮಗಿಂತ ಮೊದಲಿನವರು (ಸಾವನ್ನಪ್ಪಿದರು), ಮತ್ತು ನೀವು ಅಲ್ಲಾಹನ ಸುನ್ನತ್ ನಲ್ಲಿ ಯಾವುದೇ ಬದಲಾವಣೆಯನ್ನು ಕಾಣುವುದಿಲ್ಲ. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- ಅವನಿಗೇ ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವ ಎಲ್ಲವೂ ಸೇರಿದೆ. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- ಯಾವುದೇ ಸ್ತ್ರೀಯು ಗರ್ಭವನ್ನು ಧರಿಸುವುದಿಲ್ಲ ಮತ್ತು ಪ್ರಸವಿಸುವುದಿಲ್ಲ, ಅವನ ಜ್ಞಾನದ ಹೊರತಾಗಿ. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ಅವನು ರಾತ್ರಿಯನ್ನು, ಸೂರ್ಯ ಮತ್ತು ಚಂದ್ರನನ್ನು ಅಧೀನಗೊಳಿಸಿದನು; ಪ್ರತಿಯೊಂದೂ ನಿಗದಿತ ಅವಧಿಯವರೆಗೆ ಚಲಿಸುತ್ತವೆ. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ, ಅಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು, ಮತ್ತು ಅದೇ ಪ್ರತಿಫಲವಾಗಿದೆ. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- ಅವನು ಹೇಳಿದನು: ಅಲ್ಲ, ನಿಮ್ಮ ಮನಸ್ಸುಗಳು ನಿಮಗೆ ಒಂದು ಕಾರ್ಯವನ್ನು ಸುಂದರವಾಗಿ ತೋರಿಸಿವೆ; ಆದ್ದರಿಂದ ಸಹನೆಯು ಉತ್ತಮವಾಗಿದೆ. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವುದು, ಮತ್ತು ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- ಅವರ ಬಳಿಗೆ ಯಾವುದೇ ಪ್ರವಾದಿಯು ಬಂದಾಗಲೂ, ಅವರು ಅವನನ್ನು ಅಪಹಾಸ್ಯ ಮಾಡುತ್ತಿದ್ದರು. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- ಅವರು ಹೇಳಿದರು: ಓ ಮೂಸಾ, ನೀವು ಎಸೆಯುತ್ತೀರಾ ಅಥವಾ ನಾವು ಎಸೆಯುತ್ತೇವಾ? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- ಅವನೇ ನಿಮ್ಮನ್ನು ಮರಣಿಸುವವನು, ಮತ್ತು ನಿಮ್ಮಲ್ಲಿ ಕೆಲವರು ಅತ್ಯಂತ ವೃದ್ಧಾಪ್ಯಕ್ಕೆ ಮರಳಿಸಲ್ಪಡುತ್ತಾರೆ, ಆದ್ದರಿಂದ. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ಅವರಿಗೆ ಅವರ ಒಡೆಯನ ಬಳಿಯಲ್ಲಿ ಸ್ವರ್ಗದ ತೋಟಗಳಿವೆ, ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ, ಅಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- ಮತ್ತು ನಾವು ಅವರ ಹೃದಯಗಳ ಮೇಲೆ ಪರದೆಗಳನ್ನು ಇರಿಸಿದೆವು, ಇದರಿಂದ ಅವರು ಅದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳದಿರಲಿ, ಮತ್ತು ಅವರ ಕಿವಿಗಳಲ್ಲಿ ಭಾರವನ್ನು. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- ಅಲ್ಲಾಹನ ಭರವಸೆಯು ಸತ್ಯವಾಗಿದೆ, ಆದರೆ ಅವರಲ್ಲಿ ಹೆಚ್ಚಿನವರು ತಿಳಿದಿಲ್ಲ. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- ಇದು ಅವರು ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಪ್ರವಾದಿಯ ವಿರೋಧ ಮಾಡಿದ್ದರಿಂದಾಗಿದೆ; ಮತ್ತು ಯಾರು ಅಲ್ಲಾಹನ ವಿರೋಧ ಮಾಡುತ್ತಾನೋ. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- ಮತ್ತು ಆ ದಿನದಂದು ಅವನು ಅವರನ್ನು ಕರೆದು ಹೇಳುವನು: ನೀವು ಭಾವಿಸಿದ್ದ ನನ್ನ ಪಾಲುದಾರರು ಎಲ್ಲಿದ್ದಾರೆ? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ಅಲ್ಲಾಹನು ಆಕಾಶಗಳನ್ನು ಮತ್ತು ಭೂಮಿಯನ್ನು ಸೃಷ್ಟಿಸಿರುವುದನ್ನು ಅವರು ನೋಡಲಿಲ್ಲವೇ? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (ಅವನು) ನಿಮ್ಮನ್ನು ಮಣ್ಣಿನಿಂದ, ನಂತರ ವೀರ್ಯದಿಂದ, ನಂತರ. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- ಅವರು ಹೇಳುತ್ತಿದ್ದರು: ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ನಮ್ಮ ಬಳಿಗೆ ಒಬ್ಬ ಪ್ರವಾದಿಯನ್ನು ಏಕೆ ಕಳುಹಿಸಲಿಲ್ಲ, ಆಗ ನಾವು ನಿನ್ನ ಸೂಚನೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತಿದ್ದೆವು? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ನಂತರ ಅವರ ಮರಳುವಿಕೆಯು ಅವರ ಒಡೆಯನ ಕಡೆಗೆ ಇದೆ, ಆಗ ಅವನು ಅವರು ಮಾಡುತ್ತಿದ್ದ ಕಾರ್ಯಗಳನ್ನು ಅವರಿಗೆ ತಿಳಿಸುವನು. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ಅವರಿಗೆ ಆ ಬಗ್ಗೆ ಯಾವುದೇ ಜ್ಞಾನವಿಲ್ಲ; ಅವರು ಕೇವಲ ಊಹೆಯನ್ನು ಅನುಸರಿಸುತ್ತಾರೆ. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ಖಂಡಿತವಾಗಿಯೂ ನಾವು ನಮ್ಮ ಪೂರ್ವಜರನ್ನು ಒಂದು ಧರ್ಮದ ಮೇಲೆ ಕಂಡೆವು, ಮತ್ತು ನಾವು ಅವರ ಹೆಜ್ಜೆಗಳನ್ನು ಅನುಸರಿಸುವವರಾಗಿದ್ದೇವೆ. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- ಗ್ರಂಥವನ್ನು ನೀಡಲ್ಪಟ್ಟವರು, ಅವರ ಬಳಿಗೆ ಜ್ಞಾನವು ಬಂದ ನಂತರವೇ (ಭಿನ್ನಾಭಿಪ್ರಾಯ ಹೊಂದಿದರು). (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ಮತ್ತು ಇಬ್ರಾಹೀಮ್ ಹೇಳಿದಾಗ: ಓ ನನ್ನ ಒಡೆಯನೇ, ಈ ನಗರವನ್ನು ಸುರಕ್ಷಿತವಾಗಿಸು. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- ಅವನು ನಿಮಗೆ ಕಿವಿಗಳು, ಕಣ್ಣುಗಳು ಮತ್ತು ಹೃದಯಗಳನ್ನು ನೀಡಿದನು; ನೀವು ಬಹಳ ಕಡಿಮೆ ಕೃತಜ್ಞರಾಗಿದ್ದೀರಿ. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- ಅಲ್ಲಾಹನ ಸೂಚನೆಗಳ ಬಗ್ಗೆ, ಯಾವುದೇ ಅಧಿಕಾರವಿಲ್ಲದೆ ವಾದಿಸುವವರು. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ಆದ್ದರಿಂದ ಇಬ್ರಾಹೀಮನ ಸನ್ಮಾರ್ಗದ ಧರ್ಮವನ್ನು ಅನುಸರಿಸಿರಿ, ಅವನು ಏಕದೇವೋಪಾಸಕನಾಗಿದ್ದನು ಮತ್ತು ಅವನು ಬಹುದೇವಾರಾಧಕರಲ್ಲಿ ಇರಲಿಲ್ಲ. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ಮತ್ತು ನಾವು ನಿಮ್ಮನ್ನು ಫಿರ್ಔನನ ಜನರಿಂದ ರಕ್ಷಿಸಿದಾಗ, ಅವರು ನಿಮಗೆ ಘೋರ ಶಿಕ್ಷೆಯನ್ನು ನೀಡುತ್ತಿದ್ದರು. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- ಅದು ಸರಿಯಾದ ಧರ್ಮವಾಗಿದೆ, ಆದರೆ ಹೆಚ್ಚಿನ ಜನರಿಗೆ ತಿಳಿದಿಲ್ಲ. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- ಅಲ್ಲಾಹನು ನಿಮಗಾಗಿ ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿರುವುದನ್ನು ಅಧೀನಗೊಳಿಸಿರುವುದನ್ನು ನೀವು ನೋಡಲಿಲ್ಲವೇ? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- ಅವಿಶ್ವಾಸಿಗಳು ಹೇಳುತ್ತಾರೆ: ಇದು ಸ್ಪಷ್ಟ ಮಾಟವಲ್ಲದೆ ಬೇರೇನೂ ಅಲ್ಲ. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- ನಮ್ಮ ಸ್ಪಷ್ಟ ಸೂಚನೆಗಳನ್ನು ಅವರಿಗೆ ಓದಿ ಕೇಳಿಸಿದಾಗ, ಅವಿಶ್ವಾಸಿಗಳು ಹೇಳುತ್ತಾರೆ. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ಶಾಶ್ವತವಾದ ಸ್ವರ್ಗದ ತೋಟಗಳು, ಅದರ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ, ಅಲ್ಲಿ ಅವರು ಶಾಶ್ವತವಾಗಿ ಇರುವರು. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- ಅವನು ತಾನು ಇಚ್ಛಿಸಿದ್ದನ್ನು ಸೃಷ್ಟಿಸುತ್ತಾನೆ; ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ಎಲ್ಲಾ ವಿಷಯಗಳಲ್ಲಿ ಸರ್ವಶಕ್ತನಾಗಿದ್ದಾನೆ. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- ಅವನು ನಿಮ್ಮ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸಲು ಮತ್ತು ನಿಮ್ಮನ್ನು ನಿಗದಿತ ಅವಧಿಯವರೆಗೆ ಮುಂದೂಡಲು. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- ನಮ್ಮ ಪೂರ್ವಜರು ಆರಾಧಿಸುತ್ತಿದ್ದುದರಿಂದ ನಮ್ಮನ್ನು ತಡೆಯಲು ನೀವು ಬಯಸುತ್ತೀರಾ? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- ಮತ್ತು ನಿಮ್ಮ ಒಡೆಯನು ದೇವದೂತರಿಗೆ ಹೇಳಿದಾಗ: ಖಂಡಿತವಾಗಿಯೂ ನಾನು ಮಣ್ಣಿನಿಂದ ಮನುಷ್ಯನನ್ನು ಸೃಷ್ಟಿಸಲಿದ್ದೇನೆ. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- ಮತ್ತು ಅವನೇ ತನ್ನ ಕೃಪೆಯ ಮುಂದೆ ಗಾಳಿಗಳನ್ನು ಶುಭ ಸಂದೇಶವಾಗಿ ಕಳುಹಿಸುವವನು. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- ಹೇಳು: ಭೂಮಿಯಲ್ಲಿ ಸಂಚರಿಸಿ, ಅಂತ್ಯವು ಹೇಗಿತ್ತು ಎಂದು ನೋಡಿರಿ. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ಆಕಾಶಗಳು ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಯಲ್ಲಿ, ಮತ್ತು ರಾತ್ರಿ ಮತ್ತು ಹಗಲಿನ ಪರ್ಯಾಯದಲ್ಲಿ (ಸೂಚನೆಗಳಿವೆ). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ಅಲ್ಲಾಹನಿಗೆ ಉತ್ತಮ ಸಾಲ ನೀಡುವವನು ಯಾರು, ಆದ್ದರಿಂದ ಅವನು ಅದನ್ನು ಹಲವಾರು ಪಟ್ಟು ಹೆಚ್ಚಿಸಿ ಕೊಡುವನು? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ಆದ್ದರಿಂದ ಅವರ ನಡುವೆ ಅಲ್ಲಾಹನು ಇಳಿಸಿದ ಪ್ರಕಾರ ತೀರ್ಪು ನೀಡಿರಿ, ಮತ್ತು ಅವರ ಮನೋಭಾವಗಳನ್ನು ಅನುಸರಿಸಬೇಡಿ. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- ಅವರು ದೇವದೂತರು ತಮ್ಮ ಬಳಿಗೆ ಬರುವುದನ್ನು ಅಥವಾ ನಿಮ್ಮ ಒಡೆಯನ ಆಜ್ಞೆಯು ಬರುವುದನ್ನು ಬಿಟ್ಟು ಬೇರೇನನ್ನೂ ನಿರೀಕ್ಷಿಸುತ್ತಿಲ್ಲವೇ? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನ ಮೇಲೆ ಸುಳ್ಳನ್ನು ರಚಿಸುವವರು ಯಶಸ್ವಿಯಾಗುವುದಿಲ್ಲ. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ಫಿರ್ಔನನ ಜನರ ಮತ್ತು ಅವರ ಹಿಂದಿನವರ ಸ್ಥಿತಿಯಂತೆ; ಅವರು ನಮ್ಮ ಸೂಚನೆಗಳನ್ನು ಸುಳ್ಳೆಂದು ನಿರಾಕರಿಸಿದರು. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ಮತ್ತು ಅವನು ವಿಶ್ವಾಸಿಗಳಿಗೆ ಮತ್ತು ಸತ್ಕರ್ಮಗಳನ್ನು ಮಾಡುವವರಿಗೆ ಶುಭವಾರ್ತೆಯನ್ನು ನೀಡುತ್ತಾನೆ, ಅವರಿಗೆ ಪ್ರತಿಫಲವಿದೆ ಎಂದು. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- ಅಲ್ಲಾಹನು ತನ್ನ ದಾಸರಲ್ಲಿ ತಾನು ಇಚ್ಛಿಸಿದವರಿಗೆ ಆಹಾರವನ್ನು ವಿಸ್ತಾರಗೊಳಿಸುತ್ತಾನೆ ಮತ್ತು ಸಂಕುಚಿತಗೊಳಿಸುತ್ತಾನೆ. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- ಮತ್ತು ನೀವು ಗುಪ್ತ ಮತ್ತು ಬಹಿರಂಗವನ್ನು ಬಲ್ಲವನ ಕಡೆಗೆ ಮರಳಿಸಲ್ಪಡುವಿರಿ, ಆಗ ಅವನು ನೀವು ಮಾಡುತ್ತಿದ್ದ ಕಾರ್ಯಗಳನ್ನು ನಿಮಗೆ ತಿಳಿಸುವನು. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- ಮತ್ತು ರಕ್ತ ಸಂಬಂಧಿಗಳು, ಅವರಲ್ಲಿ ಕೆಲವರು ಅಲ್ಲಾಹನ ಗ್ರಂಥದಲ್ಲಿ ಇತರರಿಗಿಂತ ಹೆಚ್ಚು ಹಕ್ಕುದಾರರಾಗಿದ್ದಾರೆ. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — ಕಡ್ಡಾಯ (ಮಾಡಲೇಬೇಕು; ಬಿಟ್ಟರೆ ಪಾಪ)
- mustahabb / mandub (مستحب / مندوب) — ಶಿಫಾರಸು ಮಾಡಲ್ಪಟ್ಟ (ಮಾಡಿದರೆ ಪ್ರತಿಫಲ, ಬಿಟ್ಟರೆ ಪಾಪವಿಲ್ಲ)
- mubah (مباح) — ತಟಸ್ಥ / ಅನುಮತಿಸಲ್ಪಟ್ಟ (ಪ್ರತಿಫಲವೂ ಇಲ್ಲ, ಪಾಪವೂ ಇಲ್ಲ)
- makruh (مكروه) — ಅಸಹ್ಯಕರ (ನಿರುತ್ಸಾಹಗೊಳಿಸಲಾಗಿದೆ, ಆದರೆ ಮಾಡಿದರೆ ಪಾಪವಿಲ್ಲ)
- haram (حرام) — ನಿಷೇಧಿಸಲ್ಪಟ್ಟ (ಮಾಡುವುದು ಪಾಪ)
- halal (حلال, ಅನುಮತಿಸಲ್ಪಟ್ಟ / ಕಾನೂನುಬದ್ಧ) — ಮುಬಾಹ್ ಮತ್ತು ಮುಸ್ತಹಬ್ ಎರಡನ್ನೂ ಒಳಗೊಳ್ಳುತ್ತದೆ — ನಿಷೇಧಿಸಲ್ಪಡದ ಎಲ್ಲವೂ
- ಅಲ್ಲಾಹನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸಿರಿ ಮತ್ತು ಅವನ ಸಹಾಯ/ನೆರವನ್ನು ಬೇಡಿರಿ. 1:5
- ಅಲ್ಲಾಹನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸಿರಿ. 2:21
- ಅಲ್ಲಾಹನಿಗೆ ಯಾವುದೇ ಪಾಲುದಾರರನ್ನು ಮಾಡಬೇಡಿ. 2:22
- ಅಲ್ಲಾಹನೇ ಕ್ಷಮಿಸುವವನು (ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸುವವನು), ಅವನು ಆದಮ್ (ಅಲೈಹಿಸ್ಸಲಾಮ್) ರ ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸಿದನು. 2:37
- ಸತ್ಯವನ್ನು ಅಸತ್ಯದೊಂದಿಗೆ ಬೆರೆಸಬೇಡಿ, ಮತ್ತು ಸತ್ಯವನ್ನು ಮರೆಮಾಚಬೇಡಿ. 2:42
- ಸಲಾತ್ (ದೈನಂದಿನ ಪ್ರಾರ್ಥನೆಗಳನ್ನು) ಸ್ಥಾಪಿಸಿರಿ ಮತ್ತು ಝಕಾತ್ (ದಾನ) ನೀಡಿರಿ. 2:43
- ನೀವೇ ಅದನ್ನು ಆಚರಿಸಿದ ನಂತರವೇ ಇತರರಿಗೆ ಸತ್ಕಾರ್ಯವನ್ನು ಆದೇಶಿಸಿರಿ. 2:44
- ನಿಮ್ಮ ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳಲ್ಲಿ ಅಲ್ಲಾಹನ ಸಹಾಯವನ್ನು ಕೋರಿರಿ. 2:45
- ಭ್ರಷ್ಟಾಚಾರದಲ್ಲಿ ತೊಡಗಬೇಡಿ ಮತ್ತು ಅದನ್ನು ಹರಡಬೇಡಿ. 2:60
- ಜನರು ಆರಾಧನಾ ಸ್ಥಳಗಳಿಗೆ ಹೋಗುವುದನ್ನು ತಡೆಯಬೇಡಿ. 2:114
- ಮಸೀದಿಯ ಪವಿತ್ರತೆಯನ್ನು ಗೌರವಿಸಿರಿ. ನಿಮ್ಮ ಪ್ರಾರ್ಥನಾ ಸ್ಥಳಗಳನ್ನು ಸ್ವಚ್ಛವಾಗಿ ಮತ್ತು ಪವಿತ್ರವಾಗಿ ಇರಿಸಿಕೊಳ್ಳಿ. 2:125
- ಅಲ್ಲಾಹನನ್ನು ಸ್ಮರಿಸಿರಿ (ಪ್ರಾರ್ಥನೆ, ಸ್ತುತಿ ಇತ್ಯಾದಿಗಳ ಮೂಲಕ) ಮತ್ತು ಅವನು ನಿಮ್ಮನ್ನು ಸ್ಮರಿಸುವನು, ಮತ್ತು ಅವನಿಗೆ ಕೃತಜ್ಞರಾಗಿರಿ. 2:152
- ಕಷ್ಟಗಳಲ್ಲಿ ಸಹನೆಯನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿರಿ. 2:153
- ಶೈತಾನನ ಹೆಜ್ಜೆಗಳನ್ನು ಅನುಸರಿಸಬೇಡಿ, ಅವನು ಸ್ಪಷ್ಟ ಶತ್ರು. 2:168
- ಯಾರನ್ನೂ ಕುರುಡಾಗಿ ಅನುಸರಿಸಬೇಡಿ. 2:170
- ಎಲ್ಲಾ ಅಮಾನತುಗಳನ್ನು ಕಾಪಾಡಿ ಮತ್ತು ಪೂರೈಸಿರಿ. ನಿಮ್ಮ ಧಾರ್ಮಿಕ ಕರ್ತವ್ಯಗಳನ್ನು ಪ್ರಾಮಾಣಿಕವಾಗಿ ನಿರ್ವಹಿಸಿರಿ. ನಿಮ್ಮ ಪ್ರತಿಜ್ಞೆಗಳು ಮತ್ತು ಒಪ್ಪಂದಗಳನ್ನು ಪೂರೈಸಿರಿ. ಭರವಸೆಗಳನ್ನು, ವಿಶೇಷವಾಗಿ ಅಲ್ಲಾಹನಿಗೆ ಮಾಡಿದ ಭರವಸೆಗಳನ್ನು ಪಾಲಿಸಿರಿ. ಅಗತ್ಯವಿರುವವರನ್ನು ಬೆಂಬಲಿಸಿರಿ ಮತ್ತು ಕಷ್ಟಗಳನ್ನು ನಿವಾರಿಸಿರಿ. ದೈವಿಕ ಅನುಗ್ರಹದ ನಷ್ಟಕ್ಕೆ ಕಾರಣವಾಗುವ ಪಾಪಗಳನ್ನು ಮಾಡುವುದನ್ನು ತಪ್ಪಿಸಿರಿ. ಅಹಂಕಾರವು ನಿಮ್ಮನ್ನು ಅನ್ಯಾಯಕ್ಕೆ ಕೊಂಡೊಯ್ಯಲು ಬಿಡಬೇಡಿ. 2:177
- ಕಿಸಾಸ್ನಲ್ಲಿ (ಶಿಕ್ಷೆಯಲ್ಲಿ ಸಮಾನತೆಯ ಕಾನೂನು) ನಿಮಗೆ ಜೀವನವಿದೆ. 2:179
- ರಮಜಾನ್ ತಿಂಗಳಿನಲ್ಲಿ ಉಪವಾಸ ಆಚರಿಸಿರಿ. ಮುತ್ತಕೀನ್ (ಧರ್ಮನಿಷ್ಠರು) ಆಗಲು ನಿಗದಿಪಡಿಸಿದ ಉಪವಾಸವನ್ನು ಪಾಲಿಸಿರಿ. 2:183
- ಕುರ್ಆನ್ ಅನ್ನು ಮಾರ್ಗದರ್ಶನದ ಅಂತಿಮ ಮೂಲವಾಗಿ ಗೌರವಿಸಿರಿ. 2:185
- ಪರಸ್ಪರರ ಆಸ್ತಿಯನ್ನು ಅನ್ಯಾಯವಾಗಿ ತಿನ್ನಬೇಡಿ, ಮತ್ತು ನ್ಯಾಯಾಧೀಶರಿಗೆ (ನಿಮ್ಮ ಪ್ರಕರಣಗಳನ್ನು ಸಲ್ಲಿಸುವ ಮೊದಲು) ಲಂಚ ನೀಡಬೇಡಿ. 2:188
- ಮಾತಿನಿಂದಲೋ ಕಾರ್ಯದಿಂದಲೋ ಇತರರನ್ನು ದಬ್ಬಾಳಿಕೆ ಮಾಡಬೇಡಿ. ಎಂದಿಗೂ ಆಕ್ರಮಣಕಾರನಾಗಿ ಯುದ್ಧ ಮಾಡಬೇಡಿ, ಆದರೆ ರಕ್ಷಣೆಗಾಗಿ ಮಾತ್ರ. 2:190
- ಅನಾಥರನ್ನು ರಕ್ಷಿಸಿರಿ. ಅನಾಥರ ವಿಷಯದಲ್ಲಿ, ಅವರ ಆಸ್ತಿಯಲ್ಲಿ ಪ್ರಾಮಾಣಿಕವಾಗಿ ಕೆಲಸ ಮಾಡಿರಿ ಮತ್ತು ಅವರ ಆಸ್ತಿಯನ್ನು ತಿನ್ನಬೇಡಿ. 2:220
- ಪಶ್ಚಾತ್ತಾಪ ಪಡಿರಿ ಮತ್ತು ಅಲ್ಲಾಹನ ಕ್ಷಮೆಯನ್ನು ಬೇಡಿರಿ. ಮುಟ್ಟಿನ ಅವಧಿಯಲ್ಲಿ ಲೈಂಗಿಕ ಸಂಭೋಗ ಮಾಡಬೇಡಿ. ಶುದ್ಧತೆಯನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಿರಿ (ದೈಹಿಕ ಮತ್ತು ಆಧ್ಯಾತ್ಮಿಕ ಎರಡರಲ್ಲೂ). 2:222
- ನಿಮ್ಮ ಕುಟುಂಬದ ಕಡೆಗೆ ನಿಮ್ಮ ಜವಾಬ್ದಾರಿಗಳನ್ನು ಪೂರೈಸಿರಿ. 2:233
- ನಾಯಕರನ್ನು ಅವರ ಅರ್ಹತೆಯ ಆಧಾರದ ಮೇಲೆ ಆಯ್ಕೆ ಮಾಡಿರಿ. 2:247
- ಧರ್ಮದಲ್ಲಿ ಬಲವಂತವಿಲ್ಲ. 2:256
- ದಾನದಲ್ಲಿ ಸಂಪತ್ತನ್ನು ಖರ್ಚು ಮಾಡಿರಿ. ಸಂಪತ್ತು ಮತ್ತು ಸಮಯ ಎರಡರಲ್ಲೂ ದಾನಿಗಳಾಗಿರಿ. 2:261
- ನಿಮ್ಮ ಔದಾರ್ಯವನ್ನು ಪ್ರಶಂಸಿಸಿಕೊಳ್ಳುವ ಮೂಲಕ ದಾನವನ್ನು ವ್ಯರ್ಥ ಮಾಡಬೇಡಿ. 2:264
- ಶೈತಾನನು ನಿಮಗೆ ಬಡತನದ ಬೆದರಿಕೆ ಹಾಕುತ್ತಾನೆ ಮತ್ತು ಅಶ್ಲೀಲ ಕಾರ್ಯಗಳನ್ನು (ಫಹ್ಶಾ — ದುಷ್ಕೃತ್ಯಗಳು, ಅಕ್ರಮ ಲೈಂಗಿಕ ಸಂಭೋಗ, ಪಾಪಗಳು) ಮಾಡಲು ಆದೇಶಿಸುತ್ತಾನೆ. 2:268
- ಅಗತ್ಯವಿರುವವರನ್ನು ಹುಡುಕಿ ಮತ್ತು ಅವರಿಗೆ ಸಹಾಯ ಮಾಡಿರಿ. 2:273
- ಬಡ್ಡಿ ಮತ್ತು ವ್ಯಾಜ್ಯದಲ್ಲಿ ತೊಡಗಬೇಡಿ. ಬಡ್ಡಿಯುಳ್ಳ ಆಸ್ತಿಯನ್ನು ತಿನ್ನಬೇಡಿ. ರಿಬಾ (ಬಡ್ಡಿ) ತಿನ್ನಬೇಡಿ. 2:275
- ಸಾಲಗಾರನು ಕಷ್ಟದಲ್ಲಿದ್ದರೆ ಮರುಪಾವತಿಗೆ ಹೆಚ್ಚಿನ ಸಮಯ ನೀಡಿರಿ. 2:280
- ವ್ಯಾಪಾರ ವ್ಯವಹಾರಗಳಲ್ಲಿ ನಿಮ್ಮ ಮಾತನ್ನು ಪಾಲಿಸಿರಿ. ನಿಮ್ಮ ಹಣಕಾಸಿನ ವ್ಯವಹಾರಗಳಲ್ಲಿ ಸತ್ಯವಂತರಾಗಿರಿ. ನಿಮ್ಮ ಎಲ್ಲಾ ಭರವಸೆಗಳಲ್ಲಿ ಪ್ರಾಮಾಣಿಕವಾಗಿ ವರ್ತಿಸಿರಿ. ನಿರ್ದಿಷ್ಟ ಅವಧಿಗೆ ಸಾಲದ ಒಪ್ಪಂದ ಮಾಡಿಕೊಳ್ಳುವಾಗ, ಅದನ್ನು ಬರೆಯಿರಿ. ನೀವು ವ್ಯಾಪಾರ ಒಪ್ಪಂದ ಮಾಡಿಕೊಳ್ಳುವಾಗಲೆಲ್ಲಾ ಸಾಕ್ಷಿಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿರಿ. 2:282
- ಎಲ್ಲಾ ಅಮಾನತುಗಳನ್ನು ಕಾಪಾಡಿ ಮತ್ತು ಪೂರೈಸಿರಿ. 2:283
- ಇಳಿಸಲ್ಪಟ್ಟ ಗ್ರಂಥಗಳನ್ನು ಮತ್ತು ಎಲ್ಲಾ ಪ್ರವಾದಿಗಳನ್ನು ನಂಬಿರಿ. 2:285
- ಅಲ್ಲಾಹನು ಯಾವುದೇ ವ್ಯಕ್ತಿಯ ಮೇಲೆ ಅವನ ಸಾಮರ್ಥ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಹೊರೆಯನ್ನು ಹಾಕುವುದಿಲ್ಲ. ಅವನು ಗಳಿಸಿದ ಒಳ್ಳೆಯದಕ್ಕೆ ಪ್ರತಿಫಲವನ್ನು ಪಡೆಯುತ್ತಾನೆ ಮತ್ತು ಗಳಿಸಿದ ಕೆಟ್ಟದಕ್ಕೆ ಶಿಕ್ಷೆಯನ್ನು ಪಡೆಯುತ್ತಾನೆ. ದೇವರು ಯಾವುದೇ ವ್ಯಕ್ತಿಯ ಮೇಲೆ ಅವನ ಸಾಮರ್ಥ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಹೊರೆಯನ್ನು ಹಾಕುವುದಿಲ್ಲ; ನಾವೂ ಅದನ್ನು ಮಾಡಬಾರದು. ಕಷ್ಟದಲ್ಲಿಯೂ ಅಲ್ಲಾಹನ ಯೋಜನೆಯನ್ನು ನಂಬಿರಿ. 2:286
- ಯಾರು ಒಪ್ಪಂದಗಳನ್ನು ಪೂರೈಸುತ್ತಾರೋ ಮತ್ತು ಅಲ್ಲಾಹನಿಗೆ ಭಯಪಡುತ್ತಾರೋ, ಅಲ್ಲಾಹನು ಧರ್ಮನಿಷ್ಠರನ್ನು ಪ್ರೀತಿಸುತ್ತಾನೆ. 3:76
- ನಿಮಗೆ ಸಾಧ್ಯವಿದ್ದರೆ ಹಜ್ಜ್ (ಯಾತ್ರೆ) ಮಾಡಿರಿ. 3:97
- ವಿಭಜನೆಯಾಗಬೇಡಿ. 3:103
- ಸತ್ಕಾರ್ಯವನ್ನು ಆದೇಶಿಸಿರಿ ಮತ್ತು ದುಷ್ಕಾರ್ಯವನ್ನು ನಿಷೇಧಿಸಿರಿ. ನಿಮ್ಮ ಸಮುದಾಯದಲ್ಲಿ ನ್ಯಾಯವನ್ನು ಪ್ರೋತ್ಸಾಹಿಸಿರಿ. ಇತರರನ್ನು ಅಲ್ಲಾಹನ ಸ್ಮರಣೆಗೆ ಕರೆಯಿರಿ. 3:104
- ವಿಶ್ವಾಸಿಗಳು ಅಲ್ಲಾಹನ ಮೇಲೆ ಭರವಸೆ ಇಡಬೇಕು. 3:122
- ರಿಬಾ (ಬಡ್ಡಿ) ತಿನ್ನಬೇಡಿ. 3:130
- ಕರುಣೆಯನ್ನು ಪಡೆಯಲು ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಸಂದೇಶವಾಹಕನ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿರಿ. 3:132
- ಅಲ್ಲಾಹನು (ಅಲ್ಲಾಹನ ಮಾರ್ಗದಲ್ಲಿ — ದಾನ, ಧರ್ಮಕಾರ್ಯಗಳು, ಇತ್ಯಾದಿಗಳಲ್ಲಿ) ಸಮೃದ್ಧಿಯಲ್ಲಿ ಮತ್ತು ಕಷ್ಟದಲ್ಲಿ ಖರ್ಚು ಮಾಡುವವರನ್ನು, ಕೋಪವನ್ನು ನುಂಗುವವರನ್ನು ಮತ್ತು ಜನರನ್ನು ಕ್ಷಮಿಸುವವರನ್ನು ಪ್ರೀತಿಸುತ್ತಾನೆ. 3:134
- ಕೋಪವನ್ನು ನುಂಗಿರಿ. ನಿಮ್ಮ ಕೋಪವನ್ನು ನಿಯಂತ್ರಿಸಿರಿ. 3:134
- ಇತರರ ತಪ್ಪುಗಳನ್ನು ಕ್ಷಮಿಸಿರಿ ಮತ್ತು ಮನ್ನಿಸಿರಿ. 3:135
- ಮಾತಿನಲ್ಲಿ ಒರಟಾಗಿರಬೇಡಿ. ನಿಮ್ಮಿಂದ ಭಿನ್ನವಾಗಿರುವವರ ಕಡೆಗೆ ಸಹನೆಯಿಂದಿರಿ. 3:159
- ಅಲ್ಲಾಹನು ನಿಮಗೆ ಸಹಾಯ ಮಾಡಿದರೆ, ಯಾರೂ ನಿಮ್ಮನ್ನು ಸೋಲಿಸಲಾರರು; ಮತ್ತು ಅವನು ನಿಮ್ಮನ್ನು ತೊರೆದರೆ, ಅವನ ನಂತರ ಯಾರು ನಿಮಗೆ ಸಹಾಯ ಮಾಡಬಲ್ಲರು? 3:160
- ಪ್ರತಿಯೊಬ್ಬರೂ ಸಾವನ್ನು ಸವಿಯುವರು. ಮತ್ತು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಮಾತ್ರ ನಿಮ್ಮ ಸಂಪೂರ್ಣ ಪ್ರತಿಫಲವನ್ನು ನೀಡಲಾಗುವುದು. 3:185
- ಪ್ರಕೃತಿಯ ಅದ್ಭುತಗಳು ಮತ್ತು ಈ ಬ್ರಹ್ಮಾಂಡದ ಸೃಷ್ಟಿಯ ಬಗ್ಗೆ ಆಳವಾಗಿ ಯೋಚಿಸಿರಿ. ದೇವರು ಅರ್ಥ ಮತ್ತು ಉದ್ದೇಶದೊಂದಿಗೆ ಬ್ರಹ್ಮಾಂಡವನ್ನು ಸೃಷ್ಟಿಸಿದನು ಎಂದು ತಿಳಿಯಿರಿ. 3:191
- ಪುರುಷರು ಮತ್ತು ಸ್ತ್ರೀಯರು ತಮ್ಮ ಕಾರ್ಯಗಳಿಗೆ ಸಮಾನ ಪ್ರತಿಫಲವನ್ನು ಪಡೆಯುತ್ತಾರೆ. 3:195
- ತಮ್ಮ ಒಡೆಯನಿಗೆ ಭಯಪಡುವವರಿಗೆ (ಸ್ವರ್ಗದಲ್ಲಿ) ತೋಟಗಳಿವೆ, ಅವುಗಳ ಕೆಳಗೆ ನದಿಗಳು ಹರಿಯುತ್ತವೆ; ಅವರು ಅಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ವಾಸಿಸುವರು, ಅಲ್ಲಾಹನ ಆತಿಥ್ಯವಾಗಿ. 3:198
- ಪ್ರತಿಯೊಂದು ಕಾರ್ಯದಲ್ಲೂ ಯಾವಾಗಲೂ ಅಲ್ಲಾಹನ ಸಂತುಷ್ಟಿಗಾಗಿ ಪ್ರಯತ್ನಿಸಿರಿ. 3:200
- ನಿಮ್ಮ ಒಡೆಯನಿಗೆ ಭಯಪಡಿರಿ, ಅವನಿಗೆ ಹೆದರಿರಿ ಮತ್ತು (ಬಾಂಧವ್ಯದ) ಸಂಬಂಧಗಳನ್ನು ಕಡಿದುಹಾಕಬೇಡಿ. 4:1
- ಅನಾಥರಿಗೆ ಅವರ ಆಸ್ತಿಯನ್ನು ನೀಡಿರಿ ಮತ್ತು (ನಿಮ್ಮ ಕೆಟ್ಟದ್ದನ್ನು) ಅವರ (ಒಳ್ಳೆಯದರೊಂದಿಗೆ) ವಿನಿಮಯ ಮಾಡಿಕೊಳ್ಳಬೇಡಿ; ಮತ್ತು ಅವರ ಆಸ್ತಿಯನ್ನು (ನಿಮ್ಮ ಆಸ್ತಿಗೆ ಸೇರಿಸಿ) ತಿನ್ನಬೇಡಿ. 4:2
- ನೀವು ಮದುವೆಯಾಗುವ ಸ್ತ್ರೀಯರಿಗೆ ಅವರ ಮಹ್ರ್ (ಮದುವೆಯ ಸಮಯದಲ್ಲಿ ಪತ್ನಿಗೆ ಪತಿ ನೀಡುವ ಕಡ್ಡಾಯ ವಿವಾಹ ಉಡುಗೊರೆ) ಸಂತೋಷದಿಂದ ನೀಡಿರಿ. 4:4
- ಅನಾಥರ ಹಕ್ಕುಗಳನ್ನು ರಕ್ಷಿಸಿರಿ. 4:6
- ಮೃತನ ಆಸ್ತಿಯನ್ನು ಅವನ ಕುಟುಂಬದ ಸದಸ್ಯರ ನಡುವೆ ಹಂಚಬೇಕು. ಸ್ತ್ರೀಯರಿಗೆ ಉತ್ತರಾಧಿಕಾರದ ಹಕ್ಕಿದೆ. 4:7
- ಅನಾಥರ ಆಸ್ತಿಯನ್ನು ಅನ್ಯಾಯವಾಗಿ ತಿನ್ನಬೇಡಿ. 4:10
- ಉತ್ತರಾಧಿಕಾರದ ಸಂಬಂಧಿಸಿದ ಆಜ್ಞೆಗಳನ್ನು ಪಾಲಿಸಿರಿ. 4:11
- ಸ್ತ್ರೀಯರನ್ನು ಅವರ ಇಚ್ಛೆಯ ವಿರುದ್ಧ ಉತ್ತರಾಧಿಕಾರದಲ್ಲಿ ಪಡೆಯುವುದು ನಿಷೇಧಿಸಲಾಗಿದೆ, ಮತ್ತು ನೀವು ಅವರೊಂದಿಗೆ ಕಠಿಣವಾಗಿ ವರ್ತಿಸಬಾರದು. ಅವರೊಂದಿಗೆ (ಪತ್ನಿಯರೊಂದಿಗೆ) ಗೌರವಯುತವಾಗಿ ಬಾಳಿರಿ. ಸ್ತ್ರೀಯರ ಹಕ್ಕುಗಳನ್ನು ಗೌರವಿಸಿರಿ ಮತ್ತು ಪಾಲಿಸಿರಿ. ನಿಮ್ಮ ಸಂಗಾತಿಯೊಂದಿಗೆ ದಯೆ ಮತ್ತು ಸಹಾನುಭೂತಿಯಿಂದ ವರ್ತಿಸಿರಿ. ಸ್ತ್ರೀಯರೊಂದಿಗೆ ಗೌರವ ಮತ್ತು ನ್ಯಾಯದಿಂದ ವರ್ತಿಸಿರಿ. 4:19
- ನಿಮ್ಮ ರಕ್ತಸಂಬಂಧಿಗಳನ್ನು ಮದುವೆಯಾಗಬೇಡಿ. 4:23
- ನಿಮ್ಮನ್ನು (ಅಥವಾ ಪರಸ್ಪರ) ಕೊಲ್ಲಬೇಡಿ. ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ನಿಮ್ಮ ಮೇಲೆ ಕರುಣಾಮಯಿ. ಪರಸ್ಪರರ ಆಸ್ತಿಯನ್ನು ಅನ್ಯಾಯವಾಗಿ ತಿನ್ನಬೇಡಿ. 4:29
- ನೀವು ನಿಷೇಧಿಸಲ್ಪಟ್ಟ ದೊಡ್ಡ ಪಾಪಗಳನ್ನು ತಪ್ಪಿಸಿದರೆ, ಅಲ್ಲಾಹನು ನಿಮ್ಮ (ಸಣ್ಣ) ಪಾಪಗಳನ್ನು ಅಳಿಸಿಹಾಕುವನು ಮತ್ತು ನಿಮ್ಮನ್ನು ಘನತೆಯ ಪ್ರವೇಶ (ಸ್ವರ್ಗ) ದಲ್ಲಿ ಪ್ರವೇಶಿಸುವನು. 4:31
- ಅಲ್ಲಾಹನು ನಿಮ್ಮಲ್ಲಿ ಕೆಲವರನ್ನು ಇತರರಿಗಿಂತ ಶ್ರೇಷ್ಠಗೊಳಿಸಿರುವ ವಿಷಯಗಳನ್ನು ಆಶಿಸಬೇಡಿ. ಅಸೂಯೆ ಮತ್ತು ಹೊಟ್ಟೆಕಿಚ್ಚಿನಿಂದ ದೂರವಿರಿ. 4:32
- ಪುರುಷರು ಸ್ತ್ರೀಯರ ರಕ್ಷಕರು ಮತ್ತು ಪೋಷಕರು, ಏಕೆಂದರೆ ಅಲ್ಲಾಹನು ಕೆಲವರನ್ನು ಇತರರಿಗಿಂತ ಶ್ರೇಷ್ಠಗೊಳಿಸಿದ್ದಾನೆ ಮತ್ತು ಅವರು ತಮ್ಮ ಸಂಪತ್ತಿನಿಂದ (ಅವರ ಪೋಷಣೆಗಾಗಿ) ಖರ್ಚು ಮಾಡುತ್ತಾರೆ. ಪುರುಷನು ಕುಟುಂಬದ ರಕ್ಷಕ ಮತ್ತು ಬೆಂಬಲಿ. 4:34
- ಅಲ್ಲಾಹನನ್ನು ಆರಾಧಿಸಿರಿ ಮತ್ತು ಅವನೊಂದಿಗೆ ಯಾರನ್ನೂ ಪಾಲುಗೊಳಿಸಬೇಡಿ, ತಂದೆ-ತಾಯಿ, ಸಂಬಂಧಿಕರು, ಅನಾಥರು, ಬಡವರು, ನೆರೆಯವರು, ಪಕ್ಕದಲ್ಲಿರುವ ಸಹಚರ, ಪ್ರಯಾಣಿಕರು (ನೀವು ಭೇಟಿಯಾಗುವವರು), ಮತ್ತು ನಿಮ್ಮ ಬಲಗೈ ಒಡೆತನದಲ್ಲಿರುವವರ (ಗುಲಾಮರ) ಕಡೆಗೆ ಒಳ್ಳೆಯದನ್ನು ಮಾಡಿರಿ. ಅಲ್ಲಾಹನು ಅಹಂಕಾರಿಗಳು ಮತ್ತು ಗರ್ವಿಷ್ಠರನ್ನು ಇಷ್ಟಪಡುವುದಿಲ್ಲ. ಇತರರ ಕಡೆಗೆ ಒಳ್ಳೆಯದನ್ನು ಮಾಡಿರಿ. ದುರ್ಬಲರ ಕಡೆಗೆ ಕರುಣೆ ತೋರಿಸಿರಿ. ಕುಟುಂಬ ಸಂಬಂಧಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿರಿ ಮತ್ತು ಸಂಬಂಧಿಕರನ್ನು ಗೌರವಿಸಿರಿ. 4:36
- ಜಿಪುಣರಾಗಬೇಡಿ. 4:37
- ಅಲ್ಲಾಹನು ತನಗೆ ಪಾಲುದಾರರನ್ನು ಮಾಡುವುದನ್ನು ಕ್ಷಮಿಸುವುದಿಲ್ಲ, ಆದರೆ ಅದರ ಹೊರತಾಗಿ ಅವನು ಇಚ್ಛಿಸುವವರಿಗೆ ಕ್ಷಮಿಸುವನು. 4:48
- ಇತರರಿಗೆ ಹೊಟ್ಟೆಕಿಚ್ಚು ಮಾಡಬೇಡಿ. 4:54
- ಅಲ್ಲಾಹನು ನಿಮಗೆ ಅಮಾನತುಗಳನ್ನು ಅವರ ಮಾಲೀಕರಿಗೆ ಹಿಂದಿರುಗಿಸಲು ಆದೇಶಿಸುತ್ತಾನೆ. ನೀವು ಜನರ ನಡುವೆ ತೀರ್ಪು ನೀಡುವಾಗ, ನ್ಯಾಯದಿಂದ ತೀರ್ಪು ನೀಡಿರಿ. 4:58
- ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಸಂದೇಶವಾಹಕನ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿರಿ. ನಿಮ್ಮ ನಡುವೆ ಅಧಿಕಾರ ಹೊಂದಿರುವವರನ್ನು ಗೌರವಿಸಿರಿ. 4:59
- ದುರ್ಬಲರು ಮತ್ತು ಅಸಹಾಯಕರನ್ನು ದಬ್ಬಾಳಿಕೆ ಮಾಡಬೇಡಿ. 4:75
- ನಿಮಗೆ ಒಳ್ಳೆಯದು ಬಂದರೆ ಅದು ಅಲ್ಲಾಹನ ಕಡೆಯಿಂದ; ಮತ್ತು ನಿಮಗೆ ಕೆಟ್ಟದು ಸಂಭವಿಸಿದರೆ ಅದು ನಿಮ್ಮ ಸ್ವಂತ ಕಡೆಯಿಂದ. 4:79
- ಯಾರು ಸಂದೇಶವಾಹಕನ (ಮುಹಮ್ಮದ್ ﷺ) ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸುತ್ತಾರೋ ಅವರು ಅಲ್ಲಾಹನ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿದರು. 4:80
- ಯಾರು ಸತ್ಕಾರ್ಯಕ್ಕಾಗಿ ಶಿಫಾರಸು ಮಾಡುತ್ತಾರೋ ಅವರು ಅದರ ಪ್ರತಿಫಲವನ್ನು ಪಡೆಯುವರು; ಮತ್ತು ಯಾರು ದುಷ್ಕಾರ್ಯಕ್ಕಾಗಿ ಶಿಫಾರಸು ಮಾಡುತ್ತಾರೋ ಅವರು ಅದರ ಹೊರೆಯನ್ನು ಹೊರುವರು. 4:85
- ವಿಶ್ವಾಸಿಗಳು ವಿಶ್ವಾಸಿಯನ್ನು ಕೊಲ್ಲುವುದು ಸರಿಯಲ್ಲ, ತಪ್ಪಾಗಿ ಹೊರತುಪಡಿಸಿ. 4:92
- ಯಾರು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ವಿಶ್ವಾಸಿಯನ್ನು ಕೊಲ್ಲುತ್ತಾರೋ, ಅವನ ಪ್ರತಿಫಲವು ನರಕವಾಗಿದೆ, ಅವನು ಅದರಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ವಾಸಿಸುವನು. ಅಲ್ಲಾಹನ ಕೋಪ ಮತ್ತು ಶಾಪವು ಅವನ ಮೇಲಿದೆ, ಮತ್ತು ಅವನಿಗೆ ಮಹಾ ಶಿಕ್ಷೆಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗಿದೆ. 4:93
- ಯಾರು ಅಲ್ಲಾಹನ ಮಾರ್ಗದಲ್ಲಿ (ತನ್ನ ಮನೆಯಿಂದ) ವಲಸೆ ಹೋಗುತ್ತಾರೋ, ಅವರು ಭೂಮಿಯಲ್ಲಿ ಅನೇಕ ಆಶ್ರಯ ಸ್ಥಳಗಳು ಮತ್ತು ಸಮೃದ್ಧಿಯನ್ನು ಕಾಣುವರು. 4:100
- ನಿಮ್ಮ ಪ್ರಾರ್ಥನೆಗಳನ್ನು ಸಮಯಕ್ಕೆ ಸರಿಯಾಗಿ ಮಾಡಿರಿ. 4:103
- ತಮ್ಮ ಅಮಾನತುಗಳಿಗೆ ದ್ರೋಹ ಮಾಡುವವರನ್ನು ಬೆಂಬಲಿಸಬೇಡಿ ಮತ್ತು ಅವರ ವಕೀಲರಾಗಬೇಡಿ. 4:105
- ಅಲ್ಲಾಹನ ಕ್ಷಮೆಯನ್ನು ಬೇಡಿರಿ, ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ಕ್ಷಮಾಶೀಲ, ಕರುಣಾಮಯಿ. 4:106
- ವಿಶ್ವಾಸಿಗಳೇ! ನ್ಯಾಯಕ್ಕಾಗಿ ದೃಢವಾಗಿ ನಿಲ್ಲಿರಿ, ಅಲ್ಲಾಹನಿಗೆ ಸಾಕ್ಷಿಗಳಾಗಿರಿ, ಅದು ನಿಮ್ಮ ಸ್ವಂತ ವಿರುದ್ಧವಾಗಿರಲಿ, ಅಥವಾ ನಿಮ್ಮ ತಂದೆ-ತಾಯಿ, ಅಥವಾ ನಿಮ್ಮ ಸಂಬಂಧಿಕರ ವಿರುದ್ಧವಾಗಿರಲಿ, ಅವನು ಶ್ರೀಮಂತನಾಗಿರಲಿ ಅಥವಾ ಬಡವನಾಗಿರಲಿ. ನ್ಯಾಯವನ್ನು ವಿಳಂಬ ಮಾಡಬೇಡಿ; ತಪ್ಪುಗಳನ್ನು ಸರಿಪಡಿಸಲು ತಕ್ಷಣ ಕ್ರಮ ತೆಗೆದುಕೊಳ್ಳಿರಿ. 4:135
- ಕಪಟಿಗಳು ಅಲ್ಲಾಹನನ್ನು ಮೋಸಗೊಳಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತಾರೆ, ಆದರೆ ಅವನೇ ಅವರನ್ನು ಮೋಸಗೊಳಿಸುತ್ತಾನೆ. 4:142
- ಕಪಟಿಗಳು ನರಕದ ಅತ್ಯಂತ ಕೆಳಗಿನ ಪದರದಲ್ಲಿರುವರು; ಮತ್ತು ನೀವು ಅವರಿಗೆ ಯಾವುದೇ ಸಹಾಯಕನನ್ನು ಕಾಣುವುದಿಲ್ಲ. 4:145
- ಅಲ್ಲಾಹನು ದುಷ್ಟತನವನ್ನು ಬಹಿರಂಗವಾಗಿ ಹೇಳುವುದನ್ನು ಇಷ್ಟಪಡುವುದಿಲ್ಲ, ಅನ್ಯಾಯಕ್ಕೆ ಒಳಗಾದವನ ಹೊರತುಪಡಿಸಿ. 4:148
- ಸಂದೇಶವಾಹಕರು ಶುಭಸಂದೇಶ ನೀಡುವವರು ಮತ್ತು ಎಚ್ಚರಿಕೆ ನೀಡುವವರಾಗಿ (ಕಳುಹಿಸಲ್ಪಟ್ಟರು), ಸಂದೇಶವಾಹಕರ (ಆಗಮನದ) ನಂತರ ಜನರು ಅಲ್ಲಾಹನ ವಿರುದ್ಧ ಯಾವುದೇ ಸಬೂಬನ್ನು ಹೊಂದದಿರಲು. 4:165
- ನಿಮ್ಮ ಒಪ್ಪಂದಗಳು ಮತ್ತು ಭರವಸೆಗಳನ್ನು ಪೂರೈಸಿರಿ. 5:1
- ಸದ್ಗುಣ ಮತ್ತು ಧರ್ಮನಿಷ್ಠೆಯಲ್ಲಿ ಪರಸ್ಪರ ಸಹಕರಿಸಿರಿ, ಮತ್ತು ಪಾಪ ಮತ್ತು ಶತ್ರುತ್ವದಲ್ಲಿ ಸಹಕರಿಸಬೇಡಿ. 5:2
- ಸತ್ತ ಪ್ರಾಣಿ, ರಕ್ತ ಮತ್ತು ಹಂದಿಯ ಮಾಂಸವನ್ನು ತಿನ್ನಬೇಡಿ. 5:3
- ನ್ಯಾಯವಾಗಿರಿ, ಇತರರ ಕಡೆಗಿನ ಶತ್ರುತ್ವ ಮತ್ತು ದ್ವೇಷವು ನಿಮ್ಮನ್ನು ನ್ಯಾಯದಿಂದ ದೂರವಾಗಿಸಲು ಬಿಡಬೇಡಿ. ನ್ಯಾಯವಾಗಿರಿ. ನ್ಯಾಯವಾಗಿರುವುದು ಧರ್ಮನಿಷ್ಠೆಗೆ ಹತ್ತಿರವಾಗಿದೆ ಎಂದು ತಿಳಿಯಿರಿ. ನ್ಯಾಯವನ್ನು ವಿಳಂಬ ಮಾಡಬೇಡಿ; ತಪ್ಪುಗಳನ್ನು ಸರಿಪಡಿಸಲು ತಕ್ಷಣ ಕ್ರಮ ತೆಗೆದುಕೊಳ್ಳಿರಿ. 5:8
- ಅಲ್ಲಾಹನನ್ನು ಸಮೀಪಿಸುವ ಸಾಧನಗಳನ್ನು ಹುಡುಕಿರಿ ಮತ್ತು ನಿಮ್ಮಿಂದಾದಷ್ಟು ಅವನ ಮಾರ್ಗದಲ್ಲಿ ಪ್ರಯತ್ನಿಸಿರಿ. ಇದರಿಂದ ನೀವು ಯಶಸ್ವಿಯಾಗುವಿರಿ. 5:35
- ನಿಮ್ಮ ಪ್ರತಿಜ್ಞೆಗಳು ಮತ್ತು ಒಪ್ಪಂದಗಳನ್ನು ಪೂರೈಸಿರಿ. 5:89
- ಮಾದಕ ಪಾನೀಯಗಳು ಮತ್ತು ಮದ್ಯವನ್ನು ತಪ್ಪಿಸಿರಿ. ಮಾದಕ ಪಾನೀಯಗಳನ್ನು (ಎಲ್ಲಾ ರೀತಿಯ ಮದ್ಯಪಾನ), ಜೂಜು, ಅಲ್-ಅನ್ಸಾಬ್ (ಕಲ್ಲಿನ ವೇದಿಕೆಗಳು), ಮತ್ತು ಅಲ್-ಅಝ್ಲಾಮ್ (ಅದೃಷ್ಟ ಅಥವಾ ನಿರ್ಧಾರಕ್ಕಾಗಿ ಬಾಣಗಳು) ಇವೆಲ್ಲವೂ ಶೈತಾನನ ಕೆಲಸದ ಅಶುದ್ಧತೆಯಾಗಿರುವುದರಿಂದ ಕಟ್ಟುನಿಟ್ಟಾಗಿ ತಪ್ಪಿಸಿರಿ. 5:90
- ನೀವು ಹಜ್ಜ್ ಅಥವಾ ಉಮ್ರಾ (ಯಾತ್ರೆ) ಗಾಗಿ ಇಹ್ರಾಮ್ ಸ್ಥಿತಿಯಲ್ಲಿರುವಾಗ ಬೇಟೆಯನ್ನು ಕೊಲ್ಲಬೇಡಿ. 5:95
- ನಿಮಗೆ ಸ್ಪಷ್ಟಪಡಿಸಿದರೆ ನಿಮ್ಮನ್ನು ಬಾಧಿಸಬಹುದಾದ ವಿಷಯಗಳನ್ನು ಕೇಳಬೇಡಿ. 5:101
- ಇತರರ ದೇವರುಗಳನ್ನು ಅವಮಾನಿಸಬೇಡಿ. ಅವರು (ಅವಿಶ್ವಾಸಿಗಳು) ಅಲ್ಲಾಹನನ್ನು ಬಿಟ್ಟು ಆರಾಧಿಸುವವುಗಳನ್ನು ಅವಮಾನಿಸಬೇಡಿ, ಇಲ್ಲದಿದ್ದರೆ ಅವರು ಅಜ್ಞಾನದಿಂದ ಅಲ್ಲಾಹನನ್ನು ಅವಮಾನಿಸಬಹುದು. 6:108
- ನೀವು ಭೂಮಿಯ ಮೇಲಿರುವ ಬಹುಸಂಖ್ಯಾತರ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿದರೆ, ಅವರು ನಿಮ್ಮನ್ನು ಅಲ್ಲಾಹನ ಮಾರ್ಗದಿಂದ ದಾರಿ ತಪ್ಪಿಸುವರು. ಅವರು ಕೇವಲ ಊಹೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತಾರೆ ಮತ್ತು ಅವರು ಕೇವಲ ಸುಳ್ಳು ಹೇಳುತ್ತಾರೆ. 6:116
- (ಮಾನವರೇ) ಎಲ್ಲಾ ರೀತಿಯ ಪಾಪಗಳನ್ನು, ಬಹಿರಂಗವಾದವು ಮತ್ತು ಗುಪ್ತವಾದವುಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಿರಿ. 6:120
- (ವಿಶ್ವಾಸಿಗಳೇ) ಯಾವ (ಮಾಂಸದ) ಮೇಲೆ ಅಲ್ಲಾಹನ ಹೆಸರನ್ನು (ಪ್ರಾಣಿಯನ್ನು ವಧಿಸುವ ಸಮಯದಲ್ಲಿ) ಉಚ್ಚರಿಸಲಾಗಿಲ್ಲವೋ ಅದನ್ನು ತಿನ್ನಬೇಡಿ. 6:121
- ಅಲ್ಲಾಹನು ಯಾರಿಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡಲು ಇಚ್ಛಿಸುತ್ತಾನೋ ಅವನ ಎದೆಯನ್ನು ಇಸ್ಲಾಂಗಾಗಿ ತೆರೆಯುತ್ತಾನೆ; ಮತ್ತು ಯಾರನ್ನು ದಾರಿತಪ್ಪಿಸಲು ಇಚ್ಛಿಸುತ್ತಾನೋ ಅವನ ಎದೆಯನ್ನು ಸಂಕುಚಿತ ಮತ್ತು ಭಾರವಾಗಿ ಮಾಡುತ್ತಾನೆ. 6:125
- ಖರ್ಚಿನಲ್ಲಿ ಮಧ್ಯಮಾರ್ಗವನ್ನು ಅನುಸರಿಸಿರಿ ಮತ್ತು ಅಪವ್ಯಯವನ್ನು ತಪ್ಪಿಸಿರಿ. ಎಲ್ಲಾ ಜೀವಿಗಳ ಹಕ್ಕುಗಳನ್ನು ರಕ್ಷಿಸಿರಿ. 6:141
- ಅಲ್ಲಾಹನಿಗೆ ಯಾವುದನ್ನೂ ಪಾಲುಗೊಳಿಸಬೇಡಿ, ತಂದೆ-ತಾಯಿಯ ಕಡೆಗೆ ಒಳ್ಳೆಯವರಾಗಿರಿ, ಬಡತನದ ಭಯದಿಂದ ನಿಮ್ಮ ಮಕ್ಕಳನ್ನು ಕೊಲ್ಲಬೇಡಿ, ಅಶ್ಲೀಲ ಕಾರ್ಯಗಳಿಗೆ ಸಮೀಪಿಸಬೇಡಿ, ಅಲ್ಲಾಹನು ನಿಷೇಧಿಸಿರುವ ಯಾವುದೇ ಜೀವವನ್ನು ಅನ್ಯಾಯವಾಗಿ ಕೊಲ್ಲಬೇಡಿ. 6:151- ಪ್ರಾಮಾಣಿಕರಾಗಿರಿ; ನಿಮ್ಮ ಯಾವುದೇ ವ್ಯವಹಾರಗಳಲ್ಲಿ ವಂಚನೆ ಮಾಡಬೇಡಿ. ಅನಾಥರ ಆಸ್ತಿಯ ಸಮೀಪ ಹೋಗಬೇಡಿ, ಅದನ್ನು ಸುಧಾರಿಸುವ ಉದ್ದೇಶವನ್ನು ಹೊರತುಪಡಿಸಿ, ನ್ಯಾಯದೊಂದಿಗೆ ಪೂರ್ಣ ಅಳತೆ ಮತ್ತು ಪೂರ್ಣ ತೂಕವನ್ನು ನೀಡಿರಿ, ನೀವು ಮಾತನಾಡುವಾಗ, ಅದು ಹತ್ತಿರದ ಸಂಬಂಧಿಯನ್ನು ಒಳಗೊಂಡಿದ್ದರೂ ಸಹ ಸತ್ಯವನ್ನು ಹೇಳಿರಿ, ಮತ್ತು ಅಲ್ಲಾಹನ ಒಪ್ಪಂದವನ್ನು ಪೂರೈಸಿರಿ. 6:152
- ನೇರವಾದ ಮಾರ್ಗವನ್ನು ಅನುಸರಿಸಿರಿ ಮತ್ತು (ಇತರ) ಮಾರ್ಗಗಳನ್ನು ಅನುಸರಿಸಬೇಡಿ, ಏಕೆಂದರೆ ಅವು ನಿಮ್ಮನ್ನು ಅವನ ಮಾರ್ಗದಿಂದ ಬೇರ್ಪಡಿಸುವುವು. 6:153
- (ಮುಹಮ್ಮದ್ ﷺ) ಹೇಳಿರಿ: "ಖಂಡಿತವಾಗಿಯೂ, ನನ್ನ ಪ್ರಾರ್ಥನೆ, ನನ್ನ ಯಜ್ಞ, ನನ್ನ ಜೀವನ ಮತ್ತು ನನ್ನ ಸಾವು ಸಮಸ್ತ ಲೋಕಗಳ ಒಡೆಯ ಅಲ್ಲಾಹನಿಗಾಗಿದೆ." 6:162
- ಅಹಂಕಾರಿಗಳಾಗಬೇಡಿ. 7:13
- ಶೈತಾನನು ನಿಮ್ಮನ್ನು ಮೋಸಗೊಳಿಸಲು ಬಿಡಬೇಡಿ. 7:27
- (ಮುಹಮ್ಮದ್ ﷺ) ಹೇಳಿರಿ: "ನನ್ನ ಒಡೆಯನು ನ್ಯಾಯವನ್ನು ಆದೇಶಿಸಿದ್ದಾನೆ…" 7:29
- ಎಲ್ಲಾ ವಿಷಯಗಳಲ್ಲಿ ಅಲ್ಲಾಹನು ನಿಗದಿಪಡಿಸಿದ ಮಿತಿಗಳನ್ನು ಪಾಲಿಸಿರಿ. ಮಾತು ಮತ್ತು ಕಾರ್ಯಗಳಲ್ಲಿ ಅತಿಕ್ರಮಣವನ್ನು ತಪ್ಪಿಸಿರಿ. ತಿನ್ನಿರಿ ಮತ್ತು ಕುಡಿಯಿರಿ ಆದರೆ ಅತಿಯಾಗಬೇಡಿ. ಪ್ರಾರ್ಥನೆಯ ಸಮಯದಲ್ಲಿ ಉತ್ತಮ ಬಟ್ಟೆಗಳನ್ನು ಧರಿಸಿರಿ. 7:31
- ಅಲ್ಲಾಹನು ಆಕಾಶಗಳು ಮತ್ತು ಭೂಮಿಯನ್ನು ಆರು ದಿನಗಳಲ್ಲಿ ಸೃಷ್ಟಿಸಿದನು, ನಂತರ ಅರ್ಶ್ (ಸಿಂಹಾಸನ) ದ ಮೇಲೆ (ತನ್ನ ಮಹಿಮೆಗೆ ಸೂಕ್ತವಾದ ರೀತಿಯಲ್ಲಿ) ಸ್ಥಿರನಾದನು. 7:54
- ನಿಮ್ಮ ಒಡೆಯನನ್ನು ವಿನಯದಿಂದ ಮತ್ತು ರಹಸ್ಯವಾಗಿ ಪ್ರಾರ್ಥಿಸಿರಿ. ಅವನು ಅತಿಕ್ರಮಿಗಳನ್ನು ಇಷ್ಟಪಡುವುದಿಲ್ಲ. 7:55
- ಮತ್ತು ಭೂಮಿಯನ್ನು ಸುಧಾರಿಸಿದ ನಂತರ ಅದರಲ್ಲಿ ಕೆಡುಕನ್ನು ಹಬ್ಬಿಸಬೇಡಿ, ಮತ್ತು ಭಯ ಮತ್ತು ಭರವಸೆಯಿಂದ ಅವನನ್ನು ಪ್ರಾರ್ಥಿಸಿರಿ. 7:56
- ಆದರೆ ಯಾರು ದುಷ್ಕಾರ್ಯಗಳನ್ನು ಮಾಡಿ, ನಂತರ ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟು ವಿಶ್ವಾಸವನ್ನು ಅವಲಂಬಿಸಿದರೋ, ಖಂಡಿತವಾಗಿಯೂ ನಿಮ್ಮ ಒಡೆಯನು ಅದರ ನಂತರ ಕ್ಷಮಾಶೀಲ, ಕರುಣಾಮಯಿ. 7:153
- (ಮುಹಮ್ಮದ್ ﷺ) ಹೇಳಿರಿ: "ಓ ಮಾನವರೇ! ಖಂಡಿತವಾಗಿಯೂ ನಾನು ನಿಮ್ಮೆಲ್ಲರ ಬಳಿಗೆ ಅಲ್ಲಾಹನ ಸಂದೇಶವಾಹಕನಾಗಿದ್ದೇನೆ…" 7:158
- ಮತ್ತು (ಎಲ್ಲಾ) ಅತ್ಯಂತ ಸುಂದರವಾದ ಹೆಸರುಗಳು ಅಲ್ಲಾಹನಿಗೆ ಸೇರಿವೆ, ಆದ್ದರಿಂದ ಅವುಗಳಿಂದ ಅವನನ್ನು ಪ್ರಾರ್ಥಿಸಿರಿ, ಮತ್ತು ಅವನ ಹೆಸರುಗಳ ಬಗ್ಗೆ ವಿಚಲಿತರಾಗುವವರನ್ನು ಬಿಟ್ಟುಬಿಡಿರಿ… 7:180
- ಅಲ್ಲಾಹನು ಯಾರನ್ನು ದಾರಿತಪ್ಪಿಸುತ್ತಾನೋ ಅವನಿಗೆ ಮಾರ್ಗದರ್ಶಕನಿಲ್ಲ; ಮತ್ತು ಅವನು ಅವರನ್ನು ತಮ್ಮ ಅತಿಕ್ರಮಣದಲ್ಲಿ ಕುರುಡಾಗಿ ಅಲೆಯಲು ಬಿಡುತ್ತಾನೆ. 7:186
- ಕ್ಷಮೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರಿ, ಸತ್ಕಾರ್ಯವನ್ನು ಆದೇಶಿಸಿರಿ, ಮತ್ತು ಮೂರ್ಖರಿಂದ (ಅಂದರೆ ಅವರನ್ನು ಶಿಕ್ಷಿಸದೆ) ದೂರವಿರಿ. 7:199
- ಇತರರ ತಪ್ಪುಗಳನ್ನು ಕ್ಷಮಿಸಿರಿ. 7:199
- ಮತ್ತು ಶೈತಾನನ ಕಡೆಯಿಂದ ಯಾವುದೇ ದುಷ್ಪ್ರೇರಣೆಯು ನಿಮ್ಮನ್ನು ಮುಟ್ಟಿದರೆ, ಅಲ್ಲಾಹನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಬೇಡಿರಿ. ಖಂಡಿತವಾಗಿಯೂ ಅವನು ಎಲ್ಲವನ್ನೂ ಕೇಳುವವನು, ಎಲ್ಲವನ್ನೂ ತಿಳಿದವನು. 7:200
- ವಿಶ್ವಾಸಿಗಳು ಎಂದರೆ ಅಲ್ಲಾಹನನ್ನು ಸ್ಮರಿಸಿದಾಗ ಅವರ ಹೃದಯಗಳು ಭಯದಿಂದ ಕಂಪಿಸುವವರು, ಮತ್ತು ಅವನ ವಚನಗಳನ್ನು ಅವರಿಗೆ ಓದಿ ಕೇಳಿಸಿದಾಗ ಅವರ ವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸುವವರು… 8:2
- ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಸಂದೇಶವಾಹಕನಿಗೆ ದ್ರೋಹ ಮಾಡಬೇಡಿ, ಮತ್ತು ನಿಮ್ಮ ಅಮಾನತುಗಳಿಗೆ (ಮತ್ತು ಅಲ್ಲಾಹನು ನಿಮಗೆ ಆದೇಶಿಸಿರುವ ಎಲ್ಲಾ ಕರ್ತವ್ಯಗಳಿಗೆ) ತಿಳಿದೂ ತಿಳಿದೂ ದ್ರೋಹ ಮಾಡಬೇಡಿ. 8:27
- ನೀವು ಅಲ್ಲಾಹನ ಆಜ್ಞೆಯನ್ನು ಪಾಲಿಸಿದರೆ ಮತ್ತು ಅವನಿಗೆ ಭಯಪಟ್ಟರೆ, ಅವನು ನಿಮಗೆ ಫುರ್ಕಾನ್ (ಸತ್ಯ ಮತ್ತು ಅಸತ್ಯವನ್ನು ಪ್ರತ್ಯೇಕಿಸಲು ಮಾನದಂಡ, ಅಥವಾ ಪ್ರತಿಯೊಂದು ಕಷ್ಟದಿಂದ ಹೊರಬರುವ ದಾರಿ) ನೀಡುವನು. 8:29
- ಅವಿಶ್ವಾಸಿಗಳು ತಮ್ಮ ಸಂಪತ್ತನ್ನು ಅಲ್ಲಾಹನ ಮಾರ್ಗದಿಂದ (ಜನರನ್ನು) ತಡೆಯಲು ಖರ್ಚು ಮಾಡುತ್ತಾರೆ, ಮತ್ತು ಅವರು ಹಾಗೆಯೇ ಖರ್ಚು ಮಾಡುತ್ತಲೇ ಇರುವರು; ಆದರೆ ಅಂತ್ಯದಲ್ಲಿ ಅದು ಅವರಿಗೆ ವಿಷಾದವಾಗುವುದು. 8:36
- ಅವಿಶ್ವಾಸಿಗಳಿಗೆ ಹೇಳಿರಿ, ಅವರು (ಅವಿಶ್ವಾಸದಿಂದ) ನಿಂತುಬಿಟ್ಟರೆ, ಅವರ ಹಿಂದಿನದನ್ನು ಕ್ಷಮಿಸಲಾಗುವುದು. ಆದರೆ ಅವರು (ಅದಕ್ಕೆ) ಮರಳಿದರೆ, ಅವರ ಹಿಂದಿನವರ (ಶಿಕ್ಷೆಗೊಳಗಾದವರ) ಉದಾಹರಣೆಗಳು ಮುಂಚೆಯೇ ಹೋಗಿವೆ (ಎಚ್ಚರಿಕೆಯಾಗಿ). 8:38
- ನೀವು (ಶತ್ರು) ಸೈನ್ಯವನ್ನು ಎದುರಿಸಿದಾಗ, ದೃಢವಾಗಿ ನಿಲ್ಲಿರಿ ಮತ್ತು ಅಲ್ಲಾಹನ ಹೆಸರನ್ನು ಹೆಚ್ಚಾಗಿ ಸ್ಮರಿಸಿರಿ (ನಾಲಿಗೆ ಮತ್ತು ಮನಸ್ಸಿನಿಂದ), ಇದರಿಂದ ನೀವು ಯಶಸ್ವಿಯಾಗುವಿರಿ. 8:45
- ಅಹಂಕಾರದಿಂದ ಮತ್ತು ಜನರಿಗೆ ತೋರಿಸಿಕೊಳ್ಳಲು ತಮ್ಮ ಮನೆಗಳಿಂದ ಹೊರಟವರಂತೆ ಮತ್ತು (ಜನರನ್ನು) ಅಲ್ಲಾಹನ ಮಾರ್ಗದಿಂದ ತಡೆದವರಂತೆ ಆಗಬೇಡಿ. 8:47
- ಅಲ್ಲಾಹನು ತಾನು ಒಂದು ಜನಾಂಗಕ್ಕೆ ನೀಡಿದ ಅನುಗ್ರಹವನ್ನು ಅವರು ತಮ್ಮ ಸ್ಥಿತಿಯನ್ನು ಬದಲಾಯಿಸುವವರೆಗೂ ಬದಲಾಯಿಸುವುದಿಲ್ಲ. 8:53
- ಅಲ್ಲಾಹನ ಬಳಿ ಅತ್ಯಂತ ಕೆಟ್ಟ ಪ್ರಾಣಿಗಳೆಂದರೆ ಅವಿಶ್ವಾಸಿಗಳು. 8:55
- ದೇವರು ತನ್ನನ್ನು ನಂಬುವವರ ಹೃದಯಗಳ ನಡುವೆ ಪ್ರೀತಿ ಮತ್ತು ಸ್ನೇಹವನ್ನು ಹುಟ್ಟಿಸುತ್ತಾನೆ. 8:63
- ಆಶ್ರಯವನ್ನು ಬೇಡುವವರನ್ನು ರಕ್ಷಿಸಿರಿ ಮತ್ತು ಸಹಾಯ ಮಾಡಿರಿ. 9:6
- ಬಹುದೇವಾರಾಧಕರು ಅಲ್ಲಾಹನ ಮಸೀದಿಗಳನ್ನು ನಿರ್ವಹಿಸುವುದು ಸರಿಯಲ್ಲ. 9:17
- ಅವರು (ಅವಿಶ್ವಾಸಿಗಳು, ಯಹೂದಿಗಳು ಮತ್ತು ಕ್ರೈಸ್ತರು) ತಮ್ಮ ಬಾಯಿಗಳಿಂದ ಅಲ್ಲಾಹನ ಬೆಳಕನ್ನು (ಮುಹಮ್ಮದ್ ﷺ ರವರೊಂದಿಗೆ ಕಳುಹಿಸಲ್ಪಟ್ಟ — ಇಸ್ಲಾಮಿಕ್ ಏಕದೇವತಾವಾದ) ಆರಿಸಿಬಿಡಲು ಬಯಸುತ್ತಾರೆ, ಆದರೆ ಅಲ್ಲಾಹನು ತನ್ನ ಬೆಳಕನ್ನು ಪೂರ್ಣಗೊಳಿಸುವುದನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆಯದನ್ನು ಅನುಮತಿಸುವುದಿಲ್ಲ, ಅವಿಶ್ವಾಸಿಗಳು ಅದನ್ನು ದ್ವೇಷಿಸಿದರೂ ಸಹ. 9:32
- ಸದಕಾದಳು (ಝಕಾತ್) ಇವರಿಗೆ ಮಾತ್ರ: 1) ಬಡವರು, 2) ಅಗತ್ಯವಿರುವವರು, 3) ಅದನ್ನು ಸಂಗ್ರಹಿಸಲು ನೇಮಿಸಲ್ಪಟ್ಟವರು, 4) ಇಸ್ಲಾಂಗೆ ಒಲಿದವರ ಹೃದಯಗಳನ್ನು ಆಕರ್ಷಿಸಲು, 5) ಗುಲಾಮರನ್ನು ವಿಮೋಚಿಸಲು, 6) ಸಾಲದಲ್ಲಿರುವವರಿಗೆ, 7) ಅಲ್ಲಾಹನ ಮಾರ್ಗದಲ್ಲಿ (ಮುಜಾಹಿದುನ್ ಗಳಿಗೆ), ಮತ್ತು 8) ಪ್ರಯಾಣಿಕರಿಗೆ. 9:60
- ಯಾರು ಅಲ್ಲಾಹನ ಮತ್ತು ಅವನ ಸಂದೇಶವಾಹಕನ (ﷺ) ವಿರುದ್ಧ ವಿರೋಧಿಸುತ್ತಾನೆ ಮತ್ತು ಶತ್ರುತ್ವ ತೋರಿಸುತ್ತಾನೆ, ಅವನಿಗೆ ನರಕದ ಬೆಂಕಿ ಇದೆ, ಅವನು ಅದರಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ವಾಸಿಸುವನು. ಅದು ಮಹಾ ಅವಮಾನವಾಗಿದೆ. 9:63
- ಕಪಟಿಗಳು, ಪುರುಷರು ಮತ್ತು ಸ್ತ್ರೀಯರು, ಪರಸ್ಪರರಂತೆ. ಅವರು ಅಲ್ಲಾಹನನ್ನು ಮರೆತರು, ಆದ್ದರಿಂದ ಅವನೂ ಅವರನ್ನು ಮರೆತನು. 9:67
- ಪವಿತ್ರತೆಯ ಕಡೆಗೆ ಪ್ರಯತ್ನಿಸಿರಿ. ಮಸೀದಿಯ ಪವಿತ್ರತೆಯನ್ನು ಗೌರವಿಸಿರಿ. 9:108
- (ಪ್ರವಾದಿ ಮತ್ತು ವಿಶ್ವಾಸಿಗಳಿಗೆ) ಬಹುದೇವಾರಾಧಕರಿಗಾಗಿ, ಅವರು ಸಂಬಂಧಿಕರಾಗಿದ್ದರೂ ಸಹ, ಅವರು ನರಕವಾಸಿಗಳೆಂದು ಸ್ಪಷ್ಟವಾದ ನಂತರ (ಅವರು ಅವಿಶ್ವಾಸದ ಸ್ಥಿತಿಯಲ್ಲಿ ಸತ್ತದ್ದರಿಂದ) ಕ್ಷಮೆಯನ್ನು ಬೇಡುವುದು ಸರಿಯಲ್ಲ. 9:113
- ಅಲ್ಲಾಹನ ವಿರುದ್ಧ ಸುಳ್ಳನ್ನು ಹೇಳುವವನಿಗಿಂತ ಅಥವಾ ಅವನ ವಚನಗಳನ್ನು ತಿರಸ್ಕರಿಸುವವನಿಗಿಂತ ಹೆಚ್ಚು ಅಕ್ರಮಿ ಯಾರು? ಖಂಡಿತವಾಗಿಯೂ ಅಪರಾಧಿಗಳು ಎಂದಿಗೂ ಯಶಸ್ವಿಯಾಗುವುದಿಲ್ಲ! 10:17
- ಅವರು ಅಲ್ಲಾಹನನ್ನು ಬಿಟ್ಟು ತಮಗೆ ನೋವು ಮಾಡದ ಮತ್ತು ಪ್ರಯೋಜನ ನೀಡದ ವಸ್ತುಗಳನ್ನು ಆರಾಧಿಸುತ್ತಾರೆ, ಮತ್ತು ಅವರು ಹೇಳುತ್ತಾರೆ: "ಇವರು ಅಲ್ಲಾಹನ ಬಳಿ ನಮ್ಮ ಶಿಫಾರಸುದಾರರು." ಹೇಳಿರಿ: "ನೀವು ಅಲ್ಲಾಹನಿಗೆ ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿ ಅವನಿಗೆ ತಿಳಿದಿಲ್ಲದ ವಿಷಯವನ್ನು ತಿಳಿಸುತ್ತೀರಾ?" ಅವನು ಪರಿಶುದ್ಧನು ಮತ್ತು ಅವರು ಪಾಲುಗೊಳಿಸುವುದಕ್ಕಿಂತ ಉನ್ನತನು! 10:18
- ದುಷ್ಕಾರ್ಯದ ಪ್ರತಿಫಲವು ಅದರಂತಹದೇ ಆಗಿದೆ. 10:27
- ಆ ಅಲ್ಲಾಹನೇ, ನಿಮ್ಮ ನಿಜವಾದ ಒಡೆಯ. ಸತ್ಯದ ನಂತರ, ದಾರಿತಪ್ಪುವಿಕೆಯನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ಏನು ಇದೆ? ಹಾಗಾದರೆ ನೀವು ಹೇಗೆ ತಿರುಗಿಸಲ್ಪಡುತ್ತೀರಿ? 10:32
- ಅವರಲ್ಲಿ ಹೆಚ್ಚಿನವರು ಕೇವಲ ಊಹೆಯನ್ನು ಅನುಸರಿಸುತ್ತಾರೆ. ಖಂಡಿತವಾಗಿಯೂ ಊಹೆಯು ಸತ್ಯದ ಎದುರು ಏನೂ ಪ್ರಯೋಜನವಿಲ್ಲ. 10:36
- ಖಂಡಿತವಾಗಿಯೂ! ಅಲ್ಲಾಹನು ಜನರಿಗೆ ಯಾವುದೇ ಅನ್ಯಾಯ ಮಾಡುವುದಿಲ್ಲ; ಆದರೆ ಜನರು ತಮ್ಮನ್ನು ತಾವೇ ಅನ್ಯಾಯ ಮಾಡಿಕೊಳ್ಳುತ್ತಾರೆ. 10:44
- ಅಲ್ಲಾಹನ ಅನುಗ್ರಹವು ಮಾನವನು ಸಂಗ್ರಹಿಸಬಹುದಾದ ಅಥವಾ ದಾಸ್ತಾನು ಮಾಡಬಹುದಾದ ಎಲ್ಲದಕ್ಕಿಂತ ಉತ್ತಮವಾಗಿದೆ ಎಂದು ತಿಳಿಯಿರಿ. 10:58
- ಅಲ್ಲಾಹನ ವಚನಗಳನ್ನು ತಿರಸ್ಕರಿಸುವವರಲ್ಲಿ ಒಬ್ಬರಾಗಬೇಡಿ, ಇಲ್ಲದಿದ್ದರೆ ನೀವು ನಷ್ಟವನ್ನು ಅನುಭವಿಸುವವರಲ್ಲಿ ಸೇರುವಿರಿ. 10:95
- ಅಲ್ಲಾಹನು ನಿಮ್ಮನ್ನು ಯಾವುದೇ ಹಾನಿಯಿಂದ ಮುಟ್ಟಿದರೆ, ಅವನನ್ನು ಹೊರತುಪಡಿಸಿ ಅದನ್ನು ತೆಗೆದುಹಾಕುವವನು ಯಾರೂ ಇಲ್ಲ; ಮತ್ತು ಅವನು ನಿಮಗೆ ಒಳ್ಳೆಯದನ್ನು ಬಯಸಿದರೆ, ಅವನ ಅನುಗ್ರಹವನ್ನು ತಿರುಗಿಸುವವನು ಯಾರೂ ಇಲ್ಲ, ಅವನು ಅದನ್ನು ತನ್ನ ದಾಸರಲ್ಲಿ ತಾನು ಇಚ್ಛಿಸುವವರಿಗೆ ನೀಡುತ್ತಾನೆ. 10:107
- ಭೂಮಿಯ ಮೇಲೆ ಯಾವುದೇ ಜೀವಿ ಇಲ್ಲ, ಅದರ ಆಹಾರವು ಅಲ್ಲಾಹನ ಮೇಲೆ ಇಲ್ಲದೆ. ಮತ್ತು ಅವನು ಅದರ ವಾಸಸ್ಥಾನ ಮತ್ತು ಅದರ ಸಂಗ್ರಹ ಸ್ಥಾನ (ಗರ್ಭಾಶಯ, ಸಮಾಧಿ, ಇತ್ಯಾದಿ) ವನ್ನು ತಿಳಿದಿದ್ದಾನೆ. 11:6
- ನಾವು ಮನುಷ್ಯನಿಗೆ ನಮ್ಮ ಕಡೆಯಿಂದ ಕರುಣೆಯನ್ನು ಸವಿಯಲು ಬಿಟ್ಟು, ನಂತರ ಅದನ್ನು ಅವನಿಂದ ಕಿತ್ತುಕೊಂಡರೆ, ಖಂಡಿತವಾಗಿಯೂ ಅವನು ಹತಾಶನಾಗುತ್ತಾನೆ, ಕೃತಘ್ನನಾಗುತ್ತಾನೆ. 11:9
- ಯಾರು ಐಹಿಕ ಜೀವನ ಮತ್ತು ಅದರ ಅಲಂಕಾರವನ್ನು ಬಯಸುತ್ತಾರೋ, ಅವರಿಗೆ ನಾವು ಅದರಲ್ಲಿ ಅವರ ಕಾರ್ಯಗಳ ಸಂಪೂರ್ಣ ಪ್ರತಿಫಲವನ್ನು ನೀಡುವೆವು ಮತ್ತು ಅವರಿಗೆ ಅದರಲ್ಲಿ ಯಾವುದೇ ಕಡಿಮೆಯಾಗುವುದಿಲ್ಲ. 11:15
- ನಾವು ಅವರಿಗೆ ಅನ್ಯಾಯ ಮಾಡಲಿಲ್ಲ, ಆದರೆ ಅವರು ತಮ್ಮನ್ನು ತಾವೇ ಅನ್ಯಾಯ ಮಾಡಿಕೊಂಡರು. ಮತ್ತು ಅವರು ಅಲ್ಲಾಹನನ್ನು ಬಿಟ್ಟು ಪ್ರಾರ್ಥಿಸುತ್ತಿದ್ದ ಅವರ ದೇವರುಗಳು, ನಿಮ್ಮ ಒಡೆಯನ ಆಜ್ಞೆಯು ಬಂದಾಗ ಅವರಿಗೆ ಯಾವುದೇ ಪ್ರಯೋಜನವನ್ನು ನೀಡಲಿಲ್ಲ, ಮತ್ತು ಅವರ ವಿನಾಶವನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆಯದನ್ನು ಅವರಿಗೆ ಹೆಚ್ಚಿಸಲಿಲ್ಲ. 11:101
- ಅದು (ಶಿಕ್ಷೆ) ಬರುವ ದಿನದಂದು, ಅವನ (ಅಲ್ಲಾಹನ) ಅನುಮತಿಯಿಲ್ಲದೆ ಯಾರೂ ಮಾತನಾಡುವುದಿಲ್ಲ. ಅವರಲ್ಲಿ ಕೆಲವರು ದುರದೃಷ್ಟಗಾರರು ಮತ್ತು (ಇತರರು) ಅದೃಷ್ಟಶಾಲಿಗಳು. 11:105
- ದುರದೃಷ್ಟಗಾರರಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ, ಅವರು ನರಕದಲ್ಲಿರುವರು, ಅಲ್ಲಿ ಅವರು ನಿಟ್ಟುಸಿರು ಮತ್ತು ಗೋಳಾಟವನ್ನು ಹೊಂದಿರುವರು. 11:106
- ಅವರು ಅದರಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ವಾಸಿಸುವರು, ಆಕಾಶಗಳು ಮತ್ತು ಭೂಮಿಯು ಇರುವವರೆಗೂ, ನಿಮ್ಮ ಒಡೆಯನು ಇಚ್ಛಿಸುವವರೆಗೆ ಹೊರತುಪಡಿಸಿ. ಖಂಡಿತವಾಗಿಯೂ ನಿಮ್ಮ ಒಡೆಯನು ತಾನು ಇಚ್ಛಿಸಿದ್ದನ್ನು ಮಾಡುವವನು. 11:107
- ಮತ್ತು ಅದೃಷ್ಟಶಾಲಿಗಳು, ಅವರು ಸ್ವರ್ಗದಲ್ಲಿರುವರು, ಅದರಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ವಾಸಿಸುವರು, ಆಕಾಶಗಳು ಮತ್ತು ಭೂಮಿಯು ಇರುವವರೆಗೂ, ನಿಮ್ಮ ಒಡೆಯನು ಇಚ್ಛಿಸುವವರೆಗೆ ಹೊರತುಪಡಿಸಿ, ಅಂತ್ಯವಿಲ್ಲದ ಕೊಡುಗೆಯಾಗಿ. 11:108
- ಅಕ್ರಮಿಗಳ ಕಡೆಗೆ ಒಲಿಯಬೇಡಿ, ಇಲ್ಲದಿದ್ದರೆ ನರಕವು ನಿಮ್ಮನ್ನು ಮುಟ್ಟುವುದು, ಮತ್ತು ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ನಿಮಗೆ ಯಾವುದೇ ರಕ್ಷಕರು ಇರುವುದಿಲ್ಲ, ಮತ್ತು ನಂತರ ನಿಮಗೆ ಸಹಾಯ ಮಾಡಲಾಗುವುದಿಲ್ಲ. 11:113
- ಹಗಲಿನ ಎರಡು ಕೊನೆಗಳಲ್ಲಿ ಮತ್ತು ರಾತ್ರಿಯ ಕೆಲವು ಗಂಟೆಗಳಲ್ಲಿ ಸಲಾತ್ ಅನ್ನು ಸ್ಥಾಪಿಸಿರಿ (ಅಂದರೆ 5 ದೈನಂದಿನ ಪ್ರಾರ್ಥನೆಗಳು). ಸತ್ಕಾರ್ಯಗಳು ದುಷ್ಕಾರ್ಯಗಳನ್ನು (ಅಂದರೆ ಸಣ್ಣ ಪಾಪಗಳನ್ನು) ನಿವಾರಿಸುತ್ತವೆ. 11:114
- ಆಕಾಶಗಳು ಮತ್ತು ಭೂಮಿಯ ಗುಪ್ತವಾದ ವಿಷಯಗಳು ಅಲ್ಲಾಹನಿಗೆ ಸೇರಿವೆ, ಮತ್ತು ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳು (ನಿರ್ಧಾರಕ್ಕಾಗಿ) ಅವನ ಕಡೆಗೆ ಮರಳುತ್ತವೆ. 11:123
- ಆಜ್ಞೆ (ಅಥವಾ ತೀರ್ಪು) ಅಲ್ಲಾಹನಿಗೆ ಮಾತ್ರ ಸೇರಿದೆ. ಅವನು ನೀವು ಅವನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸಬೇಕು (ಏಕದೇವತಾವಾದ) ಎಂದು ಆದೇಶಿಸಿದ್ದಾನೆ, ಅದು ನೇರವಾದ ಧರ್ಮವಾಗಿದೆ, ಆದರೆ ಹೆಚ್ಚಿನ ಜನರು ತಿಳಿದಿಲ್ಲ. 12:40
- ಅಲ್ಲಾಹನ ಕರುಣೆಯಿಂದ ಎಂದಿಗೂ ನಿರಾಶರಾಗಬೇಡಿ. 12:87
- ಮತ್ತು ಹೆಚ್ಚಿನ ಜನರು ವಿಶ್ವಾಸವನ್ನು ಅವಲಂಬಿಸುವುದಿಲ್ಲ, ನೀವು ಎಷ್ಟೇ ತೀವ್ರವಾಗಿ ಬಯಸಿದರೂ ಸಹ. 12:103
- ಮತ್ತು ಅವರಲ್ಲಿ ಹೆಚ್ಚಿನವರು ಅಲ್ಲಾಹನನ್ನು ವಿಶ್ವಾಸಿಸುವುದಿಲ್ಲ, ಅವರು ಅವನಿಗೆ ಪಾಲುದಾರರನ್ನು ಮಾಡದೆ (ಅಂದರೆ ಅವರು ಬಹುದೇವಾರಾಧಕರು). 12:106
- ಅದು (ಕುರ್ಆನ್) ಕಟ್ಟಿಕೊಂಡ ಮಾತಲ್ಲ, ಆದರೆ ಅದರ ಹಿಂದಿನ ಗ್ರಂಥಗಳ (ತೌರಾತ್, ಇಂಜೀಲ್ ಮತ್ತು ಇತರ ಗ್ರಂಥಗಳ) ದೃಢೀಕರಣವಾಗಿದೆ ಮತ್ತು ಪ್ರತಿಯೊಂದು ವಿಷಯದ ವಿವರವಾದ ವಿವರಣೆಯಾಗಿದೆ, ಮತ್ತು ವಿಶ್ವಾಸಿಸುವ ಜನರಿಗೆ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ಕರುಣೆಯಾಗಿದೆ. 12:111
- ಅಲ್ಲಾಹನು ತಾನು ಇಚ್ಛಿಸುವವರಿಗೆ ಜೀವನಾಧಾರವನ್ನು ವಿಸ್ತರಿಸುತ್ತಾನೆ ಮತ್ತು (ತಾನು ಇಚ್ಛಿಸುವವರಿಗೆ) ಸಂಕುಚಿತಗೊಳಿಸುತ್ತಾನೆ. 13:26
- ಅಲ್ಲಾಹನನ್ನು ಜಿಕ್ರ್ (ಸ್ಮರಣೆ) ಮೂಲಕ ಹೆಚ್ಚಾಗಿ ಸ್ಮರಿಸಿರಿ. ಅಲ್ಲಾಹನನ್ನು ವಿಶ್ವಾಸಿಸುವವರು ಅವನನ್ನು ಸ್ಮರಿಸುವುದರಲ್ಲಿ ತಮ್ಮ ಹೃದಯಗಳಿಗೆ ಸಮಾಧಾನವನ್ನು ಕಂಡುಕೊಳ್ಳುತ್ತಾರೆ. 13:28
- ವಿಶ್ವಾಸಿಸುವ ಮತ್ತು ಸತ್ಕಾರ್ಯಗಳನ್ನು ಮಾಡುವವರಿಗೆ ಸಂತೋಷ ಮತ್ತು ಮನಸ್ಸಿನ ಶಾಂತಿಯನ್ನು ನೀಡಲಾಗುತ್ತದೆ. 13:29
- ಯಾರು ಪರಲೋಕಕ್ಕಿಂತ ಐಹಿಕ ಜೀವನಕ್ಕೆ ಆದ್ಯತೆ ನೀಡುತ್ತಾರೆ ಮತ್ತು ಅಲ್ಲಾಹನ ಮಾರ್ಗದಿಂದ (ಜನರನ್ನು) ತಡೆಯುತ್ತಾರೆ ಮತ್ತು ಅದರಲ್ಲಿ ವಕ್ರತೆಯನ್ನು ಬಯಸುತ್ತಾರೆ — ಅವರು ದೂರದ ದಾರಿತಪ್ಪುವಿಕೆಯಲ್ಲಿದ್ದಾರೆ. 14:3
- ಆರಾಧನೆಯಲ್ಲಿ ವಿನಯ ಮತ್ತು ಕೃತಜ್ಞತೆಯನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿರಿ. 14:7
- ತಮ್ಮ ಒಡೆಯನನ್ನು ನಿರಾಕರಿಸುವವರ ಉಪಮೆಯು, ಅವರ ಕಾರ್ಯಗಳು ಬೂದಿಯಂತೆ, ಅದರ ಮೇಲೆ ಚಂಡಮಾರುತದ ದಿನದಲ್ಲಿ ಗಾಳಿಯು ತೀವ್ರವಾಗಿ ಬೀಸುತ್ತದೆ; ಅವರು ಗಳಿಸಿದ ಯಾವುದನ್ನೂ ಪಡೆಯಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ. 14:18
- ಅಲ್ಲಾಹನು ವಿಶ್ವಾಸಿಗಳನ್ನು ಈ ಲೋಕದಲ್ಲಿ (ಅಂದರೆ ಅವರು ಅಲ್ಲಾಹನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸುವುದನ್ನು ಮುಂದುವರಿಸುತ್ತಾರೆ) ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ದೃಢವಾದ ಮಾತಿನಿಂದ ಸ್ಥಿರಗೊಳಿಸುತ್ತಾನೆ. 14:27
- ಅಲ್ಲಾಹನು ಅಕ್ರಮಿಗಳು (ಬಹುದೇವಾರಾಧಕರು, ದಬ್ಬಾಳಿಕೆದಾರರು, ಇತ್ಯಾದಿ) ಮಾಡುವುದನ್ನು ಅರಿಯದವನೆಂದು ಭಾವಿಸಬೇಡಿ; ಆದರೆ ಅವನು ಅವರಿಗೆ ಕಣ್ಣುಗಳು ಭಯದಿಂದ ವಿಸ್ತಾರವಾಗಿ ತೆರೆಯುವ ದಿನದವರೆಗೆ ಅವಕಾಶ ನೀಡುತ್ತಾನೆ. 14:42
- ಅಲ್ಲಾಹನು ಪ್ರತಿಯೊಬ್ಬ ವ್ಯಕ್ತಿಗೂ ಅವನು ಗಳಿಸಿದ್ದಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಪ್ರತಿಫಲ ನೀಡಲು. ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ಲೆಕ್ಕ ತೆಗೆಯುವುದರಲ್ಲಿ ವೇಗವುಳ್ಳವನು. 14:51
- ಮತ್ತು ಖಂಡಿತವಾಗಿಯೂ ನಾವು ಮನುಷ್ಯನನ್ನು ಸದ್ದು ಮಾಡುವ ಮಣ್ಣಿನಿಂದ, ಕಪ್ಪು ಬದಲಾದ ಮಣ್ಣಿನಿಂದ ಸೃಷ್ಟಿಸಿದೆವು. 15:26
- ಮತ್ತು ಜಿನ್ನುಗಳನ್ನು, ನಾವು ಅವುಗಳನ್ನು ಅದಕ್ಕೂ ಮೊದಲು ಹೊಗೆಯಿಲ್ಲದ ಬೆಂಕಿಯ ಜ್ವಾಲೆಯಿಂದ ಸೃಷ್ಟಿಸಿದೆವು. 15:27
- ಅದು (ನರಕ) ಏಳು ಬಾಗಿಲುಗಳನ್ನು ಹೊಂದಿದೆ; ಪ್ರತಿಯೊಂದು ಬಾಗಿಲಿಗೆ (ವಿಶೇಷ) ಪಾಪಿಗಳ ವರ್ಗವಿದೆ. 15:44
- ಅವನು ಮನುಷ್ಯನನ್ನು ವೀರ್ಯದ ಹನಿಯಿಂದ (ಪುರುಷ ಮತ್ತು ಸ್ತ್ರೀಯ ಲೈಂಗಿಕ ಸ್ರಾವಗಳ ಮಿಶ್ರಣ) ಸೃಷ್ಟಿಸಿದನು, ಮತ್ತು ಇಗೋ, ಈ (ಮನುಷ್ಯ) ಸ್ಪಷ್ಟ ವಿರೋಧಿಯಾಗುತ್ತಾನೆ. 16:4
- ಮತ್ತು ಜಾನುವಾರುಗಳನ್ನು, ಅವನು ಅವುಗಳನ್ನು ನಿಮಗಾಗಿ ಸೃಷ್ಟಿಸಿದನು; ಅವುಗಳಲ್ಲಿ ನಿಮಗೆ ಉಷ್ಣತೆ (ಬೆಚ್ಚಗಿನ ಬಟ್ಟೆಗಳು) ಮತ್ತು ಅನೇಕ ಪ್ರಯೋಜನಗಳಿವೆ, ಮತ್ತು ಅವುಗಳಿಂದ ನೀವು ತಿನ್ನುತ್ತೀರಿ. 16:5
- ಮತ್ತು (ಅವನು ಸೃಷ್ಟಿಸಿದನು) ಕುದುರೆಗಳು, ಹೇಸರಗತ್ತೆಗಳು ಮತ್ತು ಕತ್ತೆಗಳನ್ನು, ನೀವು ಅವುಗಳನ್ನು ಸವಾರಿ ಮಾಡಲು ಮತ್ತು ಅಲಂಕಾರಕ್ಕಾಗಿ. ಮತ್ತು ಅವನು ನಿಮಗೆ ತಿಳಿದಿಲ್ಲದ (ಇತರ) ವಸ್ತುಗಳನ್ನು ಸೃಷ್ಟಿಸುತ್ತಾನೆ. 16:8
- ಅವನೇ ಆಕಾಶದಿಂದ ನೀರನ್ನು (ಮಳೆಯನ್ನು) ಇಳಿಸುತ್ತಾನೆ; ಅದರಿಂದ ನೀವು ಕುಡಿಯುತ್ತೀರಿ ಮತ್ತು ಅದರಿಂದ ನೀವು ನಿಮ್ಮ ಜಾನುವಾರುಗಳನ್ನು ಮೇಯಿಸುವ ಸಸ್ಯವರ್ಗವು ಬೆಳೆಯುತ್ತದೆ. 16:10
- ಅವನೇ ಸಮುದ್ರವನ್ನು ನಿಮಗೆ ವಶಪಡಿಸಿದನು, ಇದರಿಂದ ನೀವು ಅದರಿಂದ ತಾಜಾ ಮಾಂಸವನ್ನು (ಮೀನು) ತಿನ್ನಬಹುದು ಮತ್ತು ಅದರಿಂದ ನೀವು ಧರಿಸುವ ಆಭರಣಗಳನ್ನು ಹೊರತೆಗೆಯಬಹುದು. 16:14
- ಅವನು ಭೂಮಿಯಲ್ಲಿ ಸ್ಥಿರವಾದ ಪರ್ವತಗಳನ್ನು ಸ್ಥಾಪಿಸಿದನು, ಅದು ನಿಮ್ಮೊಂದಿಗೆ ಅದುರದಂತೆ, ಮತ್ತು ನದಿಗಳು ಮತ್ತು ರಸ್ತೆಗಳನ್ನು (ಸ್ಥಾಪಿಸಿದನು), ಇದರಿಂದ ನೀವು ಮಾರ್ಗದರ್ಶನ ಪಡೆಯಬಹುದು. 16:15
- ಸೃಷ್ಟಿಸುವವನು, ಸೃಷ್ಟಿಸದವನಂತೆಯೇ? ನೀವು ಯೋಚಿಸುವುದಿಲ್ಲವೇ? 16:17
- ನೀವು ಅಲ್ಲಾಹನ ಅನುಗ್ರಹಗಳನ್ನು ಎಣಿಸಲು ಪ್ರಯತ್ನಿಸಿದರೆ, ಅವುಗಳನ್ನು ಎಂದಿಗೂ ಎಣಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ. 16:18
- ಅಲ್ಲಾಹನು ನೀವು ಮರೆಮಾಚುವುದನ್ನು ಮತ್ತು ನೀವು ಬಹಿರಂಗಪಡಿಸುವುದನ್ನು ತಿಳಿದಿದ್ದಾನೆ. 16:19
- ಅವರು (ಬಹುದೇವಾರಾಧಕರು) ಅಲ್ಲಾಹನನ್ನು ಬಿಟ್ಟು ಪ್ರಾರ್ಥಿಸುವವುಗಳು ಏನನ್ನೂ ಸೃಷ್ಟಿಸಿಲ್ಲ, ಆದರೆ ಅವುಗಳನ್ನು ಸ್ವತಃ ಸೃಷ್ಟಿಸಲಾಗಿದೆ. 16:20
- (ಅವು) ಸತ್ತಿವೆ, ಜೀವವಿಲ್ಲ, ಮತ್ತು ಅವುಗಳನ್ನು ಯಾವಾಗ ಎಬ್ಬಿಸಲಾಗುವುದು ಎಂದು ತಿಳಿದಿಲ್ಲ. 16:21
- ನಾವು ಯಾವುದೇ ವಸ್ತುವನ್ನು ಅಪೇಕ್ಷಿಸಿದಾಗ, ಅದಕ್ಕೆ ನಮ್ಮ ಮಾತು: "ಆಗು!" ಎಂದು ಹೇಳುವುದು ಮಾತ್ರ, ಮತ್ತು ಅದು ಆಗುತ್ತದೆ. 16:40
- ದುಷ್ಟ ಪಿತೂರಿಗಳನ್ನು ಮಾಡುವವರು, ಅಲ್ಲಾಹನು ಅವರನ್ನು ಭೂಮಿಯಲ್ಲಿ ಮುಳುಗಿಸುವುದಿಲ್ಲವೇ ಅಥವಾ ಅವರು ನಿರೀಕ್ಷಿಸದ ದಿಕ್ಕಿನಿಂದ ಶಿಕ್ಷೆಯು ಅವರಿಗೆ ಬರುವುದಿಲ್ಲವೇ ಎಂದು ಭದ್ರತೆಯನ್ನು ಅನುಭವಿಸುತ್ತಾರೆಯೇ? 16:45
- ನಿಮ್ಮಲ್ಲಿರುವ ಯಾವುದೇ ಅನುಗ್ರಹಗಳು ಮತ್ತು ಒಳ್ಳೆಯ ವಸ್ತುಗಳು ಅಲ್ಲಾಹನ ಕಡೆಯಿಂದ ಬಂದಿವೆ. ನಂತರ, ಹಾನಿಯು ನಿಮ್ಮನ್ನು ಮುಟ್ಟಿದಾಗ, ನೀವು ಅವನಿಗೆ ಮೊರೆಯಿಡುತ್ತೀರಿ. 16:53
- ನಂತರ, ಅವನು ನಿಮ್ಮಿಂದ ಹಾನಿಯನ್ನು ನಿವಾರಿಸಿದಾಗ, ಇಗೋ, ನಿಮ್ಮಲ್ಲಿ ಕೆಲವರು ತಮ್ಮ ಒಡೆಯನಿಗೆ (ಅಲ್ಲಾಹನಿಗೆ) ಪಾಲುದಾರರನ್ನು ಮಾಡುತ್ತಾರೆ. 16:54
- ಜಾನುವಾರುಗಳಲ್ಲಿ ನಿಮಗೆ ಒಂದು ಪಾಠವಿದೆ. ನಾವು ಅವುಗಳ ಹೊಟ್ಟೆಯೊಳಗಿನಿಂದ, ಮಲ ಮತ್ತು ರಕ್ತದ ನಡುವಿನಿಂದ, ಶುದ್ಧ ಹಾಲನ್ನು ನಿಮಗೆ ಕುಡಿಸುತ್ತೇವೆ, ಅದು ಕುಡಿಯುವವರಿಗೆ ರುಚಿಕರವಾಗಿರುತ್ತದೆ. 16:66
- ಆದ್ದರಿಂದ ಅಲ್ಲಾಹನಿಗೆ ಯಾವುದೇ ಉಪಮೆಗಳನ್ನು ಮಾಡಬೇಡಿ (ಏಕೆಂದರೆ ಅವನಿಗೆ ಸಮಾನವಾದದ್ದು ಯಾವುದೂ ಇಲ್ಲ, ಮತ್ತು ಅವನು ಯಾವುದಕ್ಕೂ ಸಮಾನನಲ್ಲ). ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನು ತಿಳಿದಿದ್ದಾನೆ, ಮತ್ತು ನೀವು ತಿಳಿದಿಲ್ಲ. 16:74
- ದೇವರು ಮಾನವರಿಗೆ ಕೇಳುವ, ನೋಡುವ, ಬುದ್ಧಿಶಕ್ತಿ ಮತ್ತು ಭಾವನೆಗಳನ್ನು ನೀಡಿದ್ದಾನೆ ಎಂದು ತಿಳಿಯಿರಿ, ಇದರಿಂದ ಅವರು ಕೃತಜ್ಞರಾಗಬಹುದು. 16:78
- ದುರಾಸೆ ಮತ್ತು ಜಿಪುಣತನವನ್ನು ತಪ್ಪಿಸಿರಿ. 16:97
- ನೀವು ಕುರ್ಆನ್ ಅನ್ನು ಓದಲು ಬಯಸಿದಾಗ, ಶಪಿತ ಶೈತಾನನಿಂದ ಅಲ್ಲಾಹನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಬೇಡಿರಿ. 16:98
- ಅಜ್ಞಾನದಿಂದ ಮಾಡಿದ ತಪ್ಪು, ವ್ಯಕ್ತಿಯು ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟು ತನ್ನನ್ನು ಸರಿಪಡಿಸಿಕೊಂಡರೆ ಕ್ಷಮಿಸಲ್ಪಡುತ್ತದೆ ಎಂದು ತಿಳಿಯಿರಿ. 16:119
- (ಮುಹಮ್ಮದ್ ﷺ) ನಿಮ್ಮ ಒಡೆಯನ ಮಾರ್ಗಕ್ಕೆ (ಇಸ್ಲಾಂಗೆ) ಜ್ಞಾನ ಮತ್ತು ಸದುಪದೇಶದೊಂದಿಗೆ ಕರೆಯಿರಿ, ಮತ್ತು ಅವರೊಂದಿಗೆ ಅತ್ಯುತ್ತಮ ರೀತಿಯಲ್ಲಿ ವಾದಿಸಿರಿ. ಇತರರನ್ನು ಅಲ್ಲಾಹನ ಮಾರ್ಗಕ್ಕೆ ಕರೆಯುವುದು ಜ್ಞಾನ ಮತ್ತು ಸೌಜನ್ಯದಿಂದ ಮಾಡಬೇಕು. 16:125
- ಅಲ್ಲಾಹನು ತನಗೆ ಭಯಪಡುವವರೊಂದಿಗೆ (ಅವನ ಕಡೆಗೆ ತಮ್ಮ ಕರ್ತವ್ಯವನ್ನು ನಿರ್ವಹಿಸುವವರು) ಮತ್ತು ಸತ್ಕಾರ್ಯಗಳನ್ನು ಮಾಡುವವರೊಂದಿಗೆ ಇದ್ದಾನೆ. 16:128
- ಈ ಕುರ್ಆನ್ ಅತ್ಯಂತ ಸರಿಯಾದ ಮತ್ತು ನ್ಯಾಯಯುತವಾದುದಕ್ಕೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡುತ್ತದೆ. 17:9
- ಯಾರೂ ಇತರರ ಪಾಪದ ಹೊರೆಯನ್ನು ಹೊರುವುದಿಲ್ಲ. 17:15
- ಯಾರು ಪರಲೋಕವನ್ನು ಬಯಸುತ್ತಾರೋ ಮತ್ತು ಅದಕ್ಕಾಗಿ ಯೋಗ್ಯ ಪ್ರಯತ್ನವನ್ನು ಮಾಡುತ್ತಾರೋ, ಮತ್ತು ಅವನು ವಿಶ್ವಾಸಿಯಾಗಿದ್ದಾನೋ, ಅಂತಹವರ ಪ್ರಯತ್ನವನ್ನು ಪ್ರಶಂಸಿಸಲಾಗುವುದು ಮತ್ತು ಪ್ರತಿಫಲಿಸಲಾಗುವುದು (ಅಲ್ಲಾಹನಿಂದ). 17:19
- ನಿಮ್ಮ ತಂದೆ-ತಾಯಿಯನ್ನು ಗೌರವಿಸಿರಿ ಮತ್ತು ಅವರೊಂದಿಗೆ ದಯೆಯಿಂದ ವರ್ತಿಸಿರಿ. ತಂದೆ-ತಾಯಿಗೆ ವಿಧೇಯರಾಗಿರಿ. ಅವರಿಗೆ ಅಗೌರವದ ಮಾತನ್ನು ಹೇಳಬೇಡಿ. ಮತ್ತು ನಿಮ್ಮ ಒಡೆಯನು ಆದೇಶಿಸಿದ್ದಾನೆ: ನೀವು ಅವನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸಬೇಕು. ಮತ್ತು ನೀವು ತಂದೆ-ತಾಯಿಗೆ ಒಳ್ಳೆಯವರಾಗಿರಬೇಕು. ಅವರಲ್ಲಿ ಒಬ್ಬರು ಅಥವಾ ಇಬ್ಬರು ನಿಮ್ಮ ಬಳಿ ವೃದ್ಧಾಪ್ಯವನ್ನು ತಲುಪಿದರೆ, ಅವರಿಗೆ "ಛೆ" ಎಂದು ಹೇಳಬೇಡಿ ಮತ್ತು ಅವರನ್ನು ಗದರಿಸಬೇಡಿ, ಆದರೆ ಅವರೊಂದಿಗೆ ಗೌರವಯುತವಾಗಿ ಮಾತನಾಡಿರಿ. 17:23
- ಮತ್ತು ಕರುಣೆಯಿಂದ ವಿನಯದ ರೆಕ್ಕೆಯನ್ನು ಅವರಿಗಾಗಿ ತಗ್ಗಿಸಿರಿ, ಮತ್ತು ಹೇಳಿರಿ: "ನನ್ನ ಒಡೆಯನೇ! ಅವರು ನನ್ನನ್ನು ಚಿಕ್ಕವನಾಗಿದ್ದಾಗ ಪೋಷಿಸಿದಂತೆ ನೀನು ಅವರ ಮೇಲೆ ಕರುಣೆಯನ್ನು ಸುರಿಸು." 17:24
- ಖಂಡಿತವಾಗಿಯೂ ಅಪವ್ಯಯಕಾರರು ಶೈತಾನನ ಸಹೋದರರು, ಮತ್ತು ಶೈತಾನನು ತನ್ನ ಒಡೆಯನಿಗೆ ಕೃತಘ್ನನಾಗಿದ್ದಾನೆ. 17:27
- ಹಣವನ್ನು ದುಂದು ಮಾಡಬೇಡಿ. 17:29
- ಬಡತನದ ಭಯದಿಂದ ನಿಮ್ಮ ಮಕ್ಕಳನ್ನು ಕೊಲ್ಲಬೇಡಿ. 17:31
- ವ್ಯಭಿಚಾರಕ್ಕೆ ಸಮೀಪಿಸಬೇಡಿ. ವಿವಾಹದ ಪವಿತ್ರತೆಯನ್ನು ಕಾಪಾಡಿರಿ ಮತ್ತು ವ್ಯಭಿಚಾರವನ್ನು ತಪ್ಪಿಸಿರಿ. 17:32
- ಅಳೆಯುವಾಗ ಪೂರ್ಣ ಅಳತೆಯನ್ನು ನೀಡಿರಿ, ಮತ್ತು ಸರಿಯಾದ ತಕ್ಕಡಿಯಿಂದ ತೂಗಿರಿ. ಅದು ಉತ್ತಮವಾಗಿದೆ (ಲಾಭದಾಯಕ) ಮತ್ತು ಅಂತಿಮವಾಗಿ ಉತ್ತಮವಾಗಿದೆ. 17:35
- (ಮಾನವನೇ) ನಿಮಗೆ ಯಾವುದೇ ಜ್ಞಾನವಿಲ್ಲದ ವಿಷಯವನ್ನು ಅನುಸರಿಸಬೇಡಿ (ಉದಾಹರಣೆಗೆ, "ನಾನು ನೋಡಿದೆ" ಎಂದು ಹೇಳುವುದು, ವಾಸ್ತವವಾಗಿ ಅವನು ನೋಡದಿದ್ದರೆ, ಅಥವಾ "ನಾನು ಕೇಳಿದೆ" ಎಂದು ಹೇಳುವುದು, ಅವನು ಕೇಳದಿದ್ದರೆ). 17:36
- ವಿನಯವಾಗಿರಿ ಮತ್ತು ಅಹಂಕಾರಿಗಳಾಗಬೇಡಿ. ಭೂಮಿಯ ಮೇಲೆ ಗರ್ವದಿಂದ ನಡೆಯಬೇಡಿ. ಖಂಡಿತವಾಗಿಯೂ ನೀವು ಭೂಮಿಯನ್ನು ಸೀಳಲು ಸಾಧ್ಯವಿಲ್ಲ, ಅಥವಾ ಪರ್ವತಗಳ ಎತ್ತರವನ್ನು ತಲುಪಲು ಸಾಧ್ಯವಿಲ್ಲ. 17:37
- ನಿಮ್ಮ ಒಡೆಯನು ನಿಮ್ಮನ್ನು ಚೆನ್ನಾಗಿ ಬಲ್ಲನು; ಅವನು ಇಚ್ಛಿಸಿದರೆ, ಅವನು ನಿಮ್ಮ ಮೇಲೆ ಕರುಣೆಯನ್ನು ತೋರಿಸುವನು, ಅಥವಾ ಅವನು ಇಚ್ಛಿಸಿದರೆ, ಅವನು ನಿಮ್ಮನ್ನು ಶಿಕ್ಷಿಸುವನು. 17:54
- ಈ ಲೋಕದಲ್ಲಿ ಕುರುಡನಾಗಿರುವವನು (ಅಂದರೆ ಅಲ್ಲಾಹನ ಸೂಚನೆಗಳನ್ನು ನೋಡದೆ ಮತ್ತು ಅವನನ್ನು ನಂಬದೆ), ಅವನು ಪರಲೋಕದಲ್ಲಿಯೂ ಕುರುಡನಾಗಿರುವನು, ಮತ್ತು ಮಾರ್ಗದಿಂದ ಇನ್ನೂ ಹೆಚ್ಚು ದಾರಿತಪ್ಪಿರುವನು. 17:72
- ನಿಗದಿಪಡಿಸಿದ ಪ್ರಾರ್ಥನೆಯ ಸಮಯಗಳನ್ನು ಪಾಲಿಸಿರಿ. 17:78
- ಖಂಡಿತವಾಗಿಯೂ ನಾವು ಈ ಕುರ್ಆನಿನಲ್ಲಿ ಮಾನವರಿಗೆ ಪ್ರತಿಯೊಂದು ರೀತಿಯ ಉಪಮೆಗಳನ್ನು ವಿವರಿಸಿದ್ದೇವೆ, ಆದರೆ ಹೆಚ್ಚಿನ ಜನರು (ಸತ್ಯವನ್ನು) ತಿರಸ್ಕರಿಸುತ್ತಾರೆ ಮತ್ತು ಅವಿಶ್ವಾಸವನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆಯದನ್ನು ಸ್ವೀಕರಿಸುವುದಿಲ್ಲ. 17:89
- ನಾವು ಈ ಕುರ್ಆನಿನಲ್ಲಿ ಮಾನವರಿಗೆ ಪ್ರತಿಯೊಂದು ರೀತಿಯ ಉದಾಹರಣೆಗಳನ್ನು ನೀಡಿದ್ದೇವೆ. ಆದರೆ, ಮನುಷ್ಯನು ಯಾವುದಕ್ಕಿಂತ ಹೆಚ್ಚು ಜಗಳಗಂಟಿ. 18:54
- ಅವರ ಪ್ರತಿಫಲವು ನರಕವಾಗಿದೆ; ಏಕೆಂದರೆ ಅವರು ಅವಿಶ್ವಾಸ ಮಾಡಿದರು ಮತ್ತು ನನ್ನ ವಚನಗಳು ಮತ್ತು ನನ್ನ ಸಂದೇಶವಾಹಕರನ್ನು ಅಪಹಾಸ್ಯ ಮತ್ತು ಲೇವಡಿಗಾಗಿ ತೆಗೆದುಕೊಂಡರು. 18:106
- ಅಲ್ಲಾಹನು (ತನ್ನ ಮಹಿಮೆಗೆ) ಪುತ್ರನನ್ನು ಹೊಂದುವುದು ಸೂಕ್ತವಲ್ಲ (ಇದು ಕ್ರೈಸ್ತರು ಅಲ್ಲಾಹನ ವಿರುದ್ಧ ಮಾಡಿದ ಅಪವಾದವನ್ನು ಉಲ್ಲೇಖಿಸುತ್ತದೆ, ಯೇಸು ಅಲ್ಲಾಹನ ಪುತ್ರ ಎಂದು). ಅವನು ಪರಿಶುದ್ಧನು (ಮತ್ತು ಅವರು ಪಾಲುಗೊಳಿಸುವುದಕ್ಕಿಂತ ಉನ್ನತನು). 19:35
- ಜನರೊಂದಿಗೆ ಮೃದುವಾಗಿ ಮಾತನಾಡಿರಿ. 20:44
- ಸತ್ಕಾರ್ಯಗಳಲ್ಲಿ ಪರಸ್ಪರ ಸ್ಪರ್ಧಿಸಿರಿ. 21:90
- ವ್ಯರ್ಥ ಮಾತುಗಳನ್ನು ತಪ್ಪಿಸಿರಿ. 23:3
- ನಿಮ್ಮ ನಾಚಿಕೆಯನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಿರಿ. 23:5
- ಪಾಪ ಪ್ರವೃತ್ತಿಗಳಿಂದ ನಿಮ್ಮ ಹೃದಯವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಿರಿ. 23:97
- ಇತರರನ್ನು ಕ್ಷಮಿಸಿರಿ ಮತ್ತು ಅವರ ತಪ್ಪುಗಳನ್ನು ಮನ್ನಿಸಿರಿ. 24:22
- ಇತರರ ಗೌಪ್ಯತೆಯನ್ನು ಗೌರವಿಸಿರಿ, ವಿಶೇಷವಾಗಿ ಅವರ ಸ್ವಂತ ಮನೆಗಳಲ್ಲಿ. ನೆರೆಯವರ ಹಕ್ಕುಗಳನ್ನು ಪೂರೈಸಿರಿ. 24:27
- (ಪುರುಷರು ಮತ್ತು ಸ್ತ್ರೀಯರು ಇಬ್ಬರೂ) ನಿಮ್ಮ ನೋಟವನ್ನು ತಗ್ಗಿಸಿರಿ. ನಿಮ್ಮ ನಾಚಿಕೆ ಮತ್ತು ಪಾವಿತ್ರ್ಯವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಿರಿ. 24:30
- ಉಡುಗೆ ಮತ್ತು ನಡವಳಿಕೆಯಲ್ಲಿ ನಾಚಿಕೆಯನ್ನು ಪಾಲಿಸಿರಿ. 24:31
