- ಅನುಮತಿಯಿಲ್ಲದೆ ಪೋಷಕರ ಖಾಸಗಿ ಕೋಣೆಗೆ ಪ್ರವೇಶಿಸಬೇಡಿ. 24:58
- ವಿನಮ್ರರು ಮತ್ತು ನಮ್ರರುಗಳಾಗಿರಿ. 25:63
- ಸುಳ್ಳು ಸಾಕ್ಷ್ಯ ಮತ್ತು ವಂಚನೆಯನ್ನು ತಪ್ಪಿಸಿರಿ. 25:72
- ಪರಲೋಕದ ಪ್ರತಿಫಲಕ್ಕಾಗಿ ಪ್ರಯತ್ನಿಸಿರಿ, ಆದರೆ ಈ ಲೋಕದ ನಿಮ್ಮ ವ್ಯವಹಾರಗಳನ್ನು ನಿರ್ಲಕ್ಷಿಸಬೇಡಿ. 28:77
- ಅಲ್ಲಾಹನೊಂದಿಗೆ ಯಾವುದೇ ಇತರ ದೇವರನ್ನು ಪ್ರಾರ್ಥಿಸಬೇಡಿ. 28:88
- ಸಲಿಂಗಕಾಮದಲ್ಲಿ ತೊಡಗಬೇಡಿ. 29:29
