- ಸಲಾತ್ ಅನ್ನು ಸ್ಥಾಪಿಸಿರಿ ಮತ್ತು ಝಕಾತ್ ನೀಡಿರಿ. 31:4
- ಸತ್ಕಾರ್ಯವನ್ನು ಆದೇಶಿಸಿರಿ ಮತ್ತು ದುಷ್ಕಾರ್ಯವನ್ನು ನಿಷೇಧಿಸಿರಿ. 31:17
- ನಿಮ್ಮ ನಡವಳಿಕೆಯಲ್ಲಿ ಅಹಂಕಾರವನ್ನು ತಪ್ಪಿಸಿರಿ. ವ್ಯರ್ಥ ಮಾತುಗಳಲ್ಲಿ ಸಮಯವನ್ನು ವ್ಯರ್ಥ ಮಾಡಬೇಡಿ. 31:18
- ನಿಮ್ಮ ನಡಿಗೆ ಮತ್ತು ಧ್ವನಿಯ ಪ್ರಮಾಣದಲ್ಲಿ ಮಧ್ಯಮಾರ್ಗವನ್ನು ಅನುಸರಿಸಿರಿ. 31:19
- ಪ್ರವಾದಿ ಮುಹಮ್ಮದ್ ರವರ ಮಾದರಿಯನ್ನು ಅನುಸರಿಸಿರಿ. 33:21
- ಸ್ತ್ರೀಯರು ತಮ್ಮ ಸೌಂದರ್ಯ ಮತ್ತು ಆಭರಣಗಳನ್ನು ಪ್ರದರ್ಶಿಸಬಾರದು ಅಥವಾ ಹೆಮ್ಮೆಪಡಬಾರದು. 33:33
- ಎಲ್ಲಾ ಸಂದರ್ಭಗಳಲ್ಲೂ ಸತ್ಯವನ್ನು ಹೇಳಿರಿ. 33:70
- ಚಿಂತನೆಯ ಮೂಲಕ ಜ್ಞಾನ ಮತ್ತು ತಿಳುವಳಿಕೆಯನ್ನು ಹುಡುಕಿರಿ. 38:29
- ಕುರ್ಆನಿನ ಆಜ್ಞೆಗಳನ್ನು ಪಾಲಿಸಿರಿ. 39:23
- ಪಾಪಿಯು ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟು ಅವನ ಕಡೆಗೆ ತಿರುಗಿದಾಗ, ದೇವರು ಎಲ್ಲಾ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸುತ್ತಾನೆ. 39:53
- ಅಲ್ಲಾಹನಿಗೆ ಪ್ರಾಮಾಣಿಕ ದುಆ (ಪ್ರಾರ್ಥನೆ) ಮಾಡಿರಿ. 40:60
- ಕೆಟ್ಟದ್ದನ್ನು ಉತ್ತಮವಾದುದರೊಂದಿಗೆ ತಡೆಯಿರಿ. 41:34
- ಸಮಾಲೋಚನೆಯ ಮೂಲಕ ವ್ಯವಹಾರಗಳನ್ನು ನಿರ್ಧರಿಸಿರಿ. 42:38
- ನಿಮ್ಮ ಧ್ವನಿಯನ್ನು ಪ್ರವಾದಿಯ ಧ್ವನಿಗಿಂತ ಎತ್ತರಿಸಬೇಡಿ. 49:2
- ರಹಸ್ಯಗಳನ್ನು ಕಾಪಾಡಿರಿ ಮತ್ತು ವಿಶ್ವಾಸಘಾತವನ್ನು ತಪ್ಪಿಸಿರಿ. 49:6
- ವಿರುದ್ಧದಲ್ಲಿರುವವರ ನಡುವೆ ಶಾಂತಿಯನ್ನು ಸುಗಮಗೊಳಿಸಿರಿ. ಸಂಘರ್ಷಗಳಲ್ಲಿ ಸಮನ್ವಯವನ್ನು ಹುಡುಕಿರಿ. 49:9
- ಇತರರನ್ನು ಅಪಹಾಸ್ಯ ಮಾಡಬೇಡಿ. 49:11
- ಅನುಮಾನವನ್ನು ತಪ್ಪಿಸಿರಿ. ಗೂಢಚರ್ಯೆ ಮತ್ತು ಅಪನಿಂದೆಯನ್ನು ತಪ್ಪಿಸಿರಿ. ಇತರರ ಬಗ್ಗೆ ದೂಷಿಸಬೇಡಿ ಮತ್ತು ಅಪವಾದ ಹೇಳಬೇಡಿ. ಅಪನಿಂದೆ ಮತ್ತು ಅಪವಾದದ ಎಲ್ಲಾ ರೂಪಗಳಿಂದ ದೂರವಿರಿ. ಅಹಂಕಾರವು ನಿಮ್ಮನ್ನು ಅನ್ಯಾಯಕ್ಕೆ ಕೊಂಡೊಯ್ಯಲು ಬಿಡಬೇಡಿ. 49:12
- ಧರ್ಮನಿಷ್ಠೆಯು ಮಾತ್ರ ವ್ಯಕ್ತಿಯನ್ನು ಉದಾತ್ತಗೊಳಿಸುತ್ತದೆ ಎಂದು ತಿಳಿಯಿರಿ. ಜನರು ಮತ್ತು ಸಂಸ್ಕೃತಿಗಳ ನಡುವಿನ ವ್ಯತ್ಯಾಸಗಳನ್ನು ಗೌರವಿಸಿರಿ. 49:13
- ಅತಿಥಿಗಳನ್ನು ಗೌರವಿಸಿರಿ. 51:26
