- ಸಂಪತ್ತು ನಿಮ್ಮನ್ನು ಅಲ್ಲಾಹನ ಸ್ಮರಣೆಯಿಂದ ವಿಚಲಿತಗೊಳಿಸಲು ಬಿಡಬೇಡಿ. 58:11
- ಜ್ಞಾನವುಳ್ಳವರಿಗೆ ಅಲ್ಲಾಹನು ಉನ್ನತ ಸ್ಥಾನವನ್ನು ನೀಡುವನು. 58:11
- ಅವಿಶ್ವಾಸಿಗಳೊಂದಿಗೆ ದಯೆ ಮತ್ತು ನ್ಯಾಯದಿಂದ ವರ್ತಿಸಿರಿ. 60:8
- ನಿಮ್ಮ ನಂಬಿಕೆಗಳು ಮತ್ತು ಕಾರ್ಯಗಳಲ್ಲಿ ಕಪಟತನವನ್ನು ತಪ್ಪಿಸಿರಿ. 63:9
