- ತಮ್ಮ ಆತ್ಮಗಳನ್ನು ಪರಿಶುದ್ಧಗೊಳಿಸುವವರು ಯಶಸ್ವಿಯಾಗುತ್ತಾರೆ, ಮತ್ತು ಅವುಗಳನ್ನು ಭ್ರಷ್ಟಗೊಳಿಸುವವರು ವಿಫಲರಾಗುತ್ತಾರೆ. 91:10
- ಅಗತ್ಯವಿರುವವರನ್ನು ನಿರ್ಲಕ್ಷಿಸಬೇಡಿ ಅಥವಾ ದೂರ ತಳ್ಳಬೇಡಿ. 93:10
